import Foundation

/// The status of a macOS permission request.
public enum PermissionStatus: Sendable, Equatable {
    case notDetermined
    case granted
    case denied
}

/// Abstracts macOS permission checks and requests.
///
/// Conform in Infrastructure with `SystemPermissionService`.
/// Inject into Presentation via `OnboardingViewModel` so views never
/// import AVFoundation or CoreGraphics directly.
public protocol PermissionService: Sendable {
    /// Current microphone authorization status.
    var microphoneStatus: PermissionStatus { get async }
    /// Current screen-capture authorization status.
    var screenCaptureStatus: PermissionStatus { get async }
    /// Current calendar authorization status.
    var calendarStatus: PermissionStatus { get async }
    /// Requests microphone access and returns the resulting status.
    func requestMicrophone() async -> PermissionStatus
    /// Requests screen-capture access and returns the resulting status.
    func requestScreenCapture() async -> PermissionStatus
    /// Requests calendar access and returns the resulting status.
    func requestCalendar() async -> PermissionStatus
}

import Foundation

/// The status of a macOS permission request.
public enum PermissionStatus: Sendable, Equatable {
    case notDetermined
    case granted
    case denied
}

/// Abstracts macOS permission checks and requests.
///
/// Conform in Infrastructure with `SystemPermissionService`.
/// Inject into Presentation via `OnboardingViewModel` so views never
/// import AVFoundation or CoreGraphics directly.
public protocol PermissionService: Sendable {
    /// Current microphone authorization status.
    var microphoneStatus: PermissionStatus { get async }
    /// Current screen-capture authorization status.
    var screenCaptureStatus: PermissionStatus { get async }
    /// Requests microphone access and returns the resulting status.
    func requestMicrophone() async -> PermissionStatus
    /// Requests screen-capture access and returns the resulting status.
    func requestScreenCapture() async -> PermissionStatus
}

import Foundation

/// Prevents macOS from sleeping during an active recording session.
///
/// Conforming types wrap IOPMAssertion or a suitable test double.
/// Actor-agnostic — callers decide their own isolation.
///
/// This protocol lives in the Business layer — no IOKit dependency here.
/// Implementations are expected to be `@MainActor`; callers must be on the main actor.
public protocol SleepAssertionService: AnyObject {
    /// Acquire a sleep-prevention assertion with the given reason string.
    /// Returns `true` on success.
    @MainActor func preventSleep(reason: String) -> Bool

    /// Release the sleep-prevention assertion.
    /// Returns `true` on success.
    @MainActor @discardableResult
    func allowSleep() -> Bool
}

