import Foundation
import Testing

@Suite("Express Sprint TDD Tests")
struct ExpressIssuesTests {

    private func fileContent(at path: String) throws -> String {
        let url = URL(fileURLWithPath: "/Volumes/Extra/repos/gitrdunhq/the-record-suite/\(path)")
        return try String(contentsOf: url, encoding: .utf8)
    }

    @Test("Issue 2: StopAndTranscribeUseCase logs session.id as .public")
    func testStopAndTranscribeUseCaseLogging() throws {
        let content =
            try fileContent(
                at: "Record-CrossPlatform-Foundation/Sources/Business/UseCases/StopAndTranscribeUseCase.swift",
            )
        #expect(content.contains("privacy: .public"), "Expected session.id to be logged with privacy: .public")
        #expect(
            !content.contains("session.id, privacy: .private"),
            "Expected session.id not to be logged with privacy: .private",
        )
    }

    @Test("Issue 7: QueryContextUseCase removes redundant logger and is nonisolated")
    func testQueryContextUseCaseLogger() throws {
        let content =
            try fileContent(at: "Record-CrossPlatform-Foundation/Sources/Business/UseCases/QueryContextUseCase.swift")
        #expect(content.contains("nonisolated private let logger"), "Expected logger to be nonisolated")
        #expect(!content.contains("let logger = logger"), "Expected redundant local logger alias to be removed")
    }

    @Test("Issue 8: App.swift closures use [weak self]")
    func testAppSwiftWeakSelf() throws {
        let content = try fileContent(at: "Record-App/Sources/TheRecord/App.swift")


        let weakSelfCount = content.components(separatedBy: "Task { [weak self] in").count - 1
        #expect(weakSelfCount >= 3, "Expected at least 3 occurrences of Task { [weak self] in inside App.swift")
    }

    @Test("Issue 9: LiveTranslateUseCase explicitly enforces & Sendable")
    func testLiveTranslateUseCaseSendable() throws {
        let content =
            try fileContent(at: "Record-CrossPlatform-Foundation/Sources/Business/UseCases/LiveTranslateUseCase.swift")
        #expect(
            content.contains("any TranslationEngine & Sendable"),
            "Expected translation engine to explicitly enforce & Sendable",
        )
    }
}

    // AC-E4d: KeychainCredentialStore is constructed for Notion credentials
    @Test("E4d: buildMCPProviders constructs KeychainCredentialStore for Notion")
    func buildMCPProvidersConstructsKeychain() {
        #expect(
            Self.buildersSource.contains("KeychainCredentialStore"),
            "buildMCPProviders must construct KeychainCredentialStore for Notion API key"
        )
    }

    // AC-E4e: GRDBContextCache is gated on config.contextCache.enabled and persisted
    // under Directories.appSupport, instead of being constructed unconditionally with
    // a nil (in-memory, non-persistent) database path.
    @Test("E4e: buildMCPProviders gates context cache on config.contextCache.enabled and uses Directories.appSupport")
    func REDACTED() {
        #expect(
            Self.buildersSource.contains("config.contextCache.enabled"),
            "buildMCPProviders must only construct GRDBContextCache when config.contextCache.enabled is true"
        )
        #expect(
            Self.buildersSource.contains("Directories.appSupport"),
            "buildMCPProviders must persist GRDBContextCache under Directories.appSupport, not an in-memory nil path"
        )
    }
}

