import Testing
import Foundation

// MARK: - Slice B: B6 — Task.yield() in transcription loop

/// Source inspection tests verifying that StreamingTranscriptionUseCase
/// yields on every loop iteration to avoid starving the cooperative pool.
@Suite("StreamingTranscriptionUseCase — cooperative yield (Slice B / B6)")
struct StreamingTranscriptionSliceBTests {

    private func source() throws -> String {
        let thisFile = URL(fileURLWithPath: #filePath)
        let repoRoot = thisFile
            .deletingLastPathComponent() // Business/
            .deletingLastPathComponent() // Unit/
            .deletingLastPathComponent() // Tests/
            .deletingLastPathComponent() // repo root
        let path = repoRoot
            .appendingPathComponent("Sources/Business/UseCases/StreamingTranscriptionUseCase.swift")
            .path
        return try String(contentsOfFile: path, encoding: .utf8)
    }

    /// Both `transcribeStream` overloads share a single `runTranscriptionLoop`
    /// helper (F17) — one `Task.yield()` call site covers both overloads.
    @Test
    func `transcription loop yields on every iteration`() throws {
        let src = try source()
        let count = src.components(separatedBy: "Task.yield()").count - 1
        #expect(count >= 1, "The shared transcription loop must call Task.yield() — found \(count)")
    }

    /// Both overloads must route through the shared loop so the yield above
    /// actually covers both — not just whichever overload happens to be tested.
    @Test
    func `both transcribeStream overloads route through the shared loop`() throws {
        let src = try source()
        let count = src.components(separatedBy: "Self.runTranscriptionLoop(").count - 1
        #expect(count >= 2, "Both transcribeStream overloads must call Self.runTranscriptionLoop — found \(count)")
    }
}

