    private var recordingStopObserver: NSObjectProtocol?
    private var windowKeyObserver: NSObjectProtocol?
    private var currentPrivacyMode: PrivacyMode = .default
    // #213: retained so setupPrivacyModeObserver can forward live setting
    // changes to the same instance wired into the Business-layer use cases.
    private var privacyModeProvider: LivePrivacyModeProvider?

