import AppKit
import Foundation
import Logging
import Domain
import AudioInfrastructure
import MLInfrastructure
import StorageInfrastructure
import Business
import Presentation
import RecordPro
import Utilities

/// Single composition root for THE RECORD.
///
/// Owns all long-lived infrastructure objects and constructs the full
/// dependency graph when `assemble(config:)` is called.
@MainActor
final class AppAssembler {

    struct Assembled {
        let appState: AppState
        let menuBarVM: MenuBarViewModel
        let libraryVM: MeetingLibraryViewModel
        let searchVM: SearchViewModel
        let detailVM: MeetingDetailViewModel
        let commitmentsVM: CommitmentsViewModel
        let contextSuggestionsVM: ContextSuggestionsViewModel
        let migrationTask: Task<Void, Never>
        let repairUseCase: RepairTranscriptUseCase
        let privacyModeProvider: LivePrivacyModeProvider
        let speakerProfileStore: JSONSpeakerProfileStore
    }

    // Long-lived infrastructure — must outlive all VMs.
    var storage: GRDBStorageActor?
    var trackCommitmentsUseCase: TrackCommitmentsUseCase?
    var transcriptionBuilt: TranscriptionSubAssembler.Built?
    // #250: retained so its init-spawned launch()/start() chain (weak self)
    // survives past buildMenuBarVM() returning — otherwise ARC deallocates it
    // before the detector ever observes a calendar event.
    var calendarAwareMeetingDetector: CalendarAwareMeetingDetector?

    let logger = AppLogger.for(category: "AppAssembler")

    // Retained so assemble() can be called again without leaking the previous loop.
    var searchSyncTask: Task<Void, Never>?
    var taskBag = TaskBag()

    /// Stops long-lived infrastructure that requires explicit teardown.
    /// Awaited from `applicationShouldTerminate` (#44, #280) so shutdown
    /// completes before the process exits — previously the detector shutdown
    /// was fire-and-forget and the database pool was never closed.
    func teardown() async {
        transcriptionBuilt?.prewarmTask.cancel()
        searchSyncTask?.cancel()
        await withAsyncTeardown {
            if let detector = calendarAwareMeetingDetector {
                await detector.shutdown()
            }
        } teardown: {
            // Storage must close even if detector shutdown misbehaves.
            do {
                try await storage?.close()
            } catch {
                logger.error("Storage close during teardown failed: \(error.localizedDescription, privacy: .public)")
            }
        }
    }

    // sequential setup — extraction would harm readability
    // swiftlint:disable:next function_body_length
    func assemble(config: AppConfig, enableCoreAudioListeners: Bool = true) async -> Assembled {
        taskBag = TaskBag()
        let st = await buildStorage()
        // #216: composition root wiring — was constructed inline in TheRecordApp.
        let speakerProfileStore = JSONSpeakerProfileStore()
        // Resolve the commitment use case once — both engine and VM share the same instance.
        let sharedTrackUseCase = trackCommitmentsUseCase ?? TrackCommitmentsUseCase(store: InMemoryCommitmentStore())

        let alignUseCase = AlignTranscriptUseCase(
            sampleLoader: AudioFileLoader(),
            reader: st,
            writer: st
        )
        // #213: real PrivacyModeProvider, seeded from the persisted setting, so
        // ExportTranscriptUseCase/QueryContextUseCase/GenericMCPProvider stop
        // seeing nil and their privacy-mode guards actually execute.
        let privacyModeProvider = LivePrivacyModeProvider(initialMode: config.privacyMode)
        let (_, engine, suggestionsVM, queryContext) = buildEngine(
            config: config,
            fallbackTrack: sharedTrackUseCase,
            alignment: alignUseCase,
            privacyModeProvider: privacyModeProvider
        )
        let (libVM, migrationTask) = buildLibraryVM(storage: st)
        let (menuBarVM, pipelineCoordinator) = buildMenuBarVM(
            storage: st, engine: engine, suggestionsVM: suggestionsVM,
            migrationTask: migrationTask, config: config, queryContext: queryContext,
            enableCoreAudioListeners: enableCoreAudioListeners
        )

        // Initialize the Single Source of Truth
        let appState = AppState(
            recording: menuBarVM.recordingStateVM,
            library: libVM,
            initialConfig: config
        )

        // Late-bind AppState to MenuBarVM
        menuBarVM.bindAppState(appState)

        // Wire PipelineCoordinator to AppState.pipeline
        await pipelineCoordinator.setOnStateChange { [weak appState] cleanup, pipeline in
            guard let appState else { return }
            Task { @MainActor in
                appState.pipeline.cleanupState = cleanup
                appState.pipeline.pipelineState = pipeline
            }
        }

        // Recovery fires AFTER menuBarVM is wired
        taskBag.add(Task {
            do {
                let ids = try await RecoverPendingSessionsUseCase(storage: st)()
                for id in ids {
                    await menuBarVM.recoverPendingSession(id)
                }
            } catch {
                let errDesc = String(reflecting: error)
                logger.error("Crash recovery check failed: \(errDesc, privacy: .public)")
            }
        })

        let commitmentsVM = CommitmentsViewModel(useCase: sharedTrackUseCase)

        let repairEngine = transcriptionBuilt?.summarizationEngine ?? MLXSummarizationPlugin()
        let repairUseCase = RepairTranscriptUseCase(
            repairService: ProTranscriptRepairService(engine: repairEngine)
        )

        let detailVM = MeetingDetailViewModel(
            reader: st, writer: st, repairUseCase: repairUseCase
        )

        // Bind DetailVM to AppState for unified selection auto-loading
        appState.bind(detailVM: detailVM)

        let searchVM = SearchViewModel(
            searchUseCase: SearchRecordingsUseCase(storage: st),
            libraryViewModel: libVM
        )

        // Keep searchVM.meetings in sync with libraryVM whenever it reloads (#72, #85).
        searchSyncTask?.cancel()
        searchSyncTask = SearchLibrarySync.start(library: libVM, search: searchVM)

        return Assembled(
            appState: appState,
            menuBarVM: menuBarVM,
            libraryVM: libVM,
            searchVM: searchVM,
            detailVM: detailVM,
            commitmentsVM: commitmentsVM,
            contextSuggestionsVM: suggestionsVM,
            migrationTask: migrationTask,
            repairUseCase: repairUseCase,
            privacyModeProvider: privacyModeProvider,
            speakerProfileStore: speakerProfileStore
        )
    }

}

import Foundation
import OSLog
import Domain

/// Use case for enrolling and updating speaker profiles with voice embeddings.
public actor EnrollSpeakerUseCase {
    private let store: any SpeakerProfileStore
    private let embedding: any VoiceEmbeddingEngine
    private let logger = Logger(subsystem: "app.the-record", category: "EnrollSpeaker")

    /// Initializes the use case with a speaker profile store and voice embedding engine.
    /// - Parameters:
    ///   - store: The store for persisting speaker profiles.
    ///   - embedding: The engine for extracting voice embeddings from audio samples.
    public init(store: any SpeakerProfileStore, embedding: any VoiceEmbeddingEngine) {
        self.store = store
        self.embedding = embedding
    }

    /// Enrolls a new speaker with an audio sample.
    /// - Parameters:
    ///   - name: The speaker's name (must not be empty or whitespace-only).
    ///   - samples: Raw audio samples as floats (must contain at least 16000 samples).
    /// - Returns: The created speaker profile.
    /// - Throws: `Speakererror.invalidName`, `SpeakerError.insufficientAudio`, or `SpeakerError.duplicateName`.
    public func enroll(name: String, samples: [Float]) async throws -> SpeakerProfile {
        guard !name.trimmingCharacters(in: .whitespaces).isEmpty else {
            throw SpeakerError.invalidName
        }
        guard samples.count >= 16000 else {
            throw SpeakerError.insufficientAudio
        }

        let vector = await embedding.extract(from: samples)
        let profile = SpeakerProfile(
            name: name, embedding: vector, sampleCount: 1,
        )
        let existing = try await store.allProfiles()
        if existing.contains(where: { $0.name == name }) {
            throw SpeakerError.duplicateName
        }
        try await store.save(profile)
        logger.info("Enrolled speaker '\(name, privacy: .private)' with \(samples.count, privacy: .public) samples")
        return profile
    }

    /// Updates a speaker profile by averaging new voice samples into the existing embedding.
    /// - Parameters:
    ///   - profileId: The ID of the speaker profile to update.
    ///   - newSamples: Additional raw audio samples to incorporate into the embedding.
    /// - Returns: The updated speaker profile.
    /// - Throws: `SpeakerError.profileNotFound` if the profile does not exist.
    public func updateWithAdditionalSamples(
        profileId: SpeakerID, newSamples: [Float],
    ) async throws -> SpeakerProfile {
        let newVector = await embedding.extract(from: newSamples)

        try await store.updateProfile(id: profileId) { profile in
            let weight = Float(profile.sampleCount)
            let totalWeight = weight + 1.0
            var merged = profile.embedding
            for i in 0 ..< merged.count {
                merged[i] = (merged[i] * weight + newVector[i]) / totalWeight
            }
            return SpeakerProfile(
                id: profile.id, name: profile.name,
                embedding: merged, enrolledAt: profile.enrolledAt,
                sampleCount: profile.sampleCount + 1,
            )
        }

        let profiles = try await store.allProfiles()
        guard let updated = profiles.first(where: { $0.id == profileId }) else {
            throw SpeakerError.profileNotFound
        }
        return updated
    }
}

import Foundation
import OSLog
import Domain

public actor MatchSpeakersUseCase {
    private static let minimumSegmentSamples = 8000 // 0.5 s @ 16 kHz

    private let store: any SpeakerProfileStore
    private let embedding: any VoiceEmbeddingEngine
    private let matchThreshold: Float
    private let logger = Logger(subsystem: "app.the-record", category: "MatchSpeakers")

    public init(
        store: any SpeakerProfileStore,
        embedding: any VoiceEmbeddingEngine,
        matchThreshold: Float = 0.75,
    ) {
        self.store = store
        self.embedding = embedding
        self.matchThreshold = matchThreshold
    }

    public func matchSpeaker(samples: [Float]) async throws -> SpeakerMatch? {
        let profiles = try await store.allProfiles()
        guard !profiles.isEmpty else { return nil }

        let queryVector = await embedding.extract(from: samples)
        var bestMatch: SpeakerMatch?
        for profile in profiles {
            try Task.checkCancellation()
            let similarity = await embedding.cosineSimilarity(queryVector, profile.embedding)
            if similarity >= matchThreshold {
                if similarity > Float(bestMatch?.confidence ?? 0) {
                    bestMatch = SpeakerMatch(
                        profileId: profile.id,
                        profileName: profile.name,
                        confidence: Double(similarity),
                    )
                }
            }
        }

        if let match = bestMatch {

            logger
                .info(
                    // swiftlint:disable:next line_length
                    "Matched speaker '\(match.profileName, privacy: .public)' (conf: \(match.confidence, format: .fixed(precision: 2), privacy: .public))",
                )
        }
        return bestMatch
    }

    public func labelDiarization(
        _ transcript: DiarizedTranscript, audioSamples: [Float],
        sampleRate: Double = 16000,
    ) async throws -> DiarizedTranscript {
        let profiles = try await store.allProfiles()
        guard !profiles.isEmpty else { return transcript }

        var labelMap: [SpeakerID: (profileId: SpeakerID, name: String)] = [:]

        for segment in transcript.segments {
            try Task.checkCancellation()

            guard labelMap[segment.speakerId] == nil else { continue }
            let start = Int(segment.startTime * sampleRate)
            let end = min(Int(segment.endTime * sampleRate), audioSamples.count)
            guard end > start, end - start >= Self.minimumSegmentSamples else { continue }

            let segmentSamples = Array(audioSamples[start ..< end])
            if let match = try await matchSpeaker(samples: segmentSamples) {
                labelMap[segment.speakerId] = (profileId: match.profileId, name: match.profileName)
            }
        }

        guard !labelMap.isEmpty else { return transcript }

        let relabeled = transcript.segments.map { seg in
            if let mapping = labelMap[seg.speakerId] {
                return DiarizedSegment(
                    text: seg.text, speakerId: mapping.profileId,
                    startTime: seg.startTime, endTime: seg.endTime,
                    confidence: seg.confidence,
                )
            }
            return seg
        }

        logger
            .info(
                // swiftlint:disable:next line_length
                "Relabeled \(labelMap.count, privacy: .public) speakers: \(labelMap.values.map(\.name).joined(separator: ", "), privacy: .private)",
            )
        return DiarizedTranscript(
            segments: relabeled,
            speakerCount: transcript.speakerCount,
            processingTime: transcript.processingTime,
        )
    }
}

