import Domain
import Foundation

// MARK: - Delete All Data state (#123)

extension SettingsViewModel {

    // MARK: Published state

    /// Whether a recording is currently in progress (injected by the recording state observer).
    /// When `true`, the Delete All Data action is disabled.
    public var isDeleteAllDataEnabled: Bool {
        !isRecordingActive
    }

    /// `true` when the user has typed exactly "DELETE" in the confirmation field (case-sensitive,
    /// no leading/trailing whitespace).
    public var isDeleteAllConfirmed: Bool {
        deleteAllConfirmationText == "DELETE"
    }

    // MARK: Orchestration

    /// Performs the full data-erase flow via the supplied ``DataEraser``.
    ///
    /// Guards:
    /// - Does nothing when `isDeleteAllConfirmed` is `false`.
    /// - Does nothing when `isDeleteAllDataEnabled` is `false` (recording in progress).
    ///
    /// On success: populates `deleteAllDataLog`, resets `deleteAllConfirmationText`.
    /// On error: propagates the thrown error to the caller and still resets `deleteAllConfirmationText`.
    ///
    /// Issue #123 — Uninstall / data cleanup.
    public func performDeleteAllData(dataEraser: any DataEraser) async throws {
        guard isDeleteAllConfirmed, isDeleteAllDataEnabled else { return }

        isDeletingAllData = true
        defer {
            isDeletingAllData = false
            deleteAllConfirmationText = ""
        }

        let deleted = try await dataEraser.eraseAllData()
        deleteAllDataLog = deleted
    }
}

    }
}
