    // Safety: created once at process load time, then only read concurrently.
    private nonisolated(unsafe) static let fftSetupBox: FFTSetupBox? = FFTSetupBox(vDSP_Length(9))

    /// #279: Hann window computed once instead of per frame (was recomputed
    /// up to 200 times per extract call).
    private static let hannWindow: [Float] = {
        var window = [Float](repeating: 0, count: fftSize)
        vDSP_hann_window(&window, vDSP_Length(fftSize), Int32(vDSP_HANN_NORM))
        return window
    }()

    public static func extract(from samples: [Float]) -> [Float] {
        guard samples.count >= fftSize else {
            return [Float](repeating: 0, count: embeddingDim)
        }

        let melEnergies = computeMelSpectrogram(samples)
        return averageAndProject(melEnergies)
    }

    public static func cosineSimilarity(_ a: [Float], _ b: [Float]) -> Float {
        guard a.count == b.count, !a.isEmpty else { return 0 }
        var dot: Float = 0, normA: Float = 0, normB: Float = 0
        vDSP_dotpr(a, 1, b, 1, &dot, vDSP_Length(a.count))
        vDSP_svesq(a, 1, &normA, vDSP_Length(a.count))
        vDSP_svesq(b, 1, &normB, vDSP_Length(b.count))
        let denom = sqrt(normA) * sqrt(normB)
        guard denom > 0 else { return 0 }
        return dot / denom
    }

    private static func computeMelSpectrogram(_ samples: [Float]) -> [[Float]] {
        let numFrames = (samples.count - fftSize) / hopSize + 1
        guard numFrames > 0 else { return [] }

        var frames: [[Float]] = []
        frames.reserveCapacity(min(numFrames, 200))
        // #279: frames are zero-copy sub-spans of the input instead of a
        // fresh 2 KB [Float] per frame (up to 200 per extract call).
        // `Array.span` is macOS 26-gated, so the span comes from the buffer
        // pointer (SE-0447); it never escapes this closure.
        samples.withUnsafeBufferPointer { buf in
            let span = Span(_unsafeElements: buf)
            for i in 0 ..< min(numFrames, 200) {
                let start = i * hopSize
                let end = start + fftSize
                guard end <= span.count else { break }
                let power = computePowerSpectrum(span.extracting(start ..< end))
                let mel = applyMelFilterbank(power)
                frames.append(mel)
            }
        }
        return frames
    }

    private static func computePowerSpectrum(_ frame: Span<Float>) -> [Float] {
        let log2n = vDSP_Length(log2(Float(fftSize)))
        guard let setup = Self.fftSetupBox?.setup else {
            return [Float](repeating: 0, count: fftSize / 2)
        }

        var realPart = [Float](repeating: 0, count: fftSize / 2)
        var imagPart = [Float](repeating: 0, count: fftSize / 2)
        // #279: the windowed frame lives in a 2 KB stack scratch buffer
        // instead of two heap arrays per frame (`var windowed = frame` copy
        // plus a per-frame Hann recompute — see the cached hannWindow above).
        withUnsafeTemporaryAllocation(of: Float.self, capacity: fftSize) { windowed in
            frame.withUnsafeBufferPointer { framePtr in
                vDSP_vmul(framePtr.baseAddress!, 1, hannWindow, 1, windowed.baseAddress!, 1, vDSP_Length(fftSize))
            }
            realPart.withUnsafeMutableBufferPointer { realBuf in
                imagPart.withUnsafeMutableBufferPointer { imagBuf in
                    var splitComplex = DSPSplitComplex(realp: realBuf.baseAddress!, imagp: imagBuf.baseAddress!)
                    windowed.baseAddress!.withMemoryRebound(to: DSPComplex.self, capacity: fftSize / 2) { complexPtr in
                        vDSP_ctoz(complexPtr, 2, &splitComplex, 1, vDSP_Length(fftSize / 2))
                        vDSP_fft_zrip(setup, &splitComplex, 1, log2n, FFTDirection(kFFTDirection_Forward))
                    }
                }
            }
        }


