        id: RecordingID,
        url: URL,
        recordedAt: Date,
        duration: TimeInterval,
        fileSize: Int64,
        configuration: AudioConfiguration,
        sampleCount: Int
    ) {
        self.id = id
        self.url = url
        self.recordedAt = recordedAt
        self.duration = duration
        self.fileSize = fileSize
        self.configuration = configuration
        self.sampleCount = sampleCount
    }
}

