import Domain
import Foundation
import MLInfrastructure
import StorageInfrastructure
import Utilities

/// Production `DataEraser`: wipes every on-disk and Keychain artifact THE RECORD owns.
///
/// Issue #301 — the `DataEraser` consumer (`SettingsViewModel.performDeleteAllData`)
/// already existed; this is the missing producer.
struct LiveDataEraser: DataEraser {
    let storage: GRDBStorageActor
    let reader: any RecordingReadRepository
    let credentialStore: KeychainCredentialStore
    let configManager: ConfigManager
    /// Injectable so tests never touch the developer's real
    /// `~/Library/Application Support/THE RECORD/`.
    let appSupportDirectory: URL

    init(
        storage: GRDBStorageActor,
        reader: any RecordingReadRepository,
        credentialStore: KeychainCredentialStore = KeychainCredentialStore(),
        configManager: ConfigManager,
        appSupportDirectory: URL = Directories.appSupport
    ) {
        self.storage = storage
        self.reader = reader
        self.credentialStore = credentialStore
        self.configManager = configManager
        self.appSupportDirectory = appSupportDirectory
    }

    func eraseAllData() async throws -> [String] {
        var erased: [String] = []
        var failed: [String] = []

        await run("WAV recordings", erased: &erased, failed: &failed, eraseRecordings)
        await run("Recordings database", erased: &erased, failed: &failed, eraseMainDatabase)
        await run("Commitments database", erased: &erased, failed: &failed) {
            try removeDatabaseFiles(named: AppConstants.Paths.commitmentsDatabaseFileName)
        }
        await run("Context cache database", erased: &erased, failed: &failed) {
            try removeDatabaseFiles(named: AppConstants.Paths.contextCacheDatabaseFileName)
        }
        await run("Speaker profiles", erased: &erased, failed: &failed) {
            let url = appSupportDirectory.appendingPathComponent(AppConstants.Paths.speakerProfilesFileName)
            try Self.removeIfExists(url)
        }
        await run("Keychain credentials", erased: &erased, failed: &failed) {
            try credentialStore.deleteAll()
        }
        await run("App preferences", erased: &erased, failed: &failed) {
            try await configManager.deleteConfigFile()
        }

        if !failed.isEmpty {
            throw DataEraseError.partialFailure(paths: failed)
        }
        return erased
    }

    /// Runs one erase step, recording its label as erased or failed. A single
    /// helper keeps the accumulate/throw-at-end bookkeeping from being duplicated
    /// seven times over.
    private func run(
        _ label: String,
        erased: inout [String],
        failed: inout [String],
        _ step: () async throws -> Void
    ) async {
        do {
            try await step()
            erased.append(label)
        } catch {
            failed.append(label)
        }
    }

    private func eraseRecordings() async throws {
        let recordings = try await reader.listAllRecordingsWithMetadata()
        for recording in recordings {
            try Self.removeIfExists(recording.audioURL)
            if let cleanedURL = recording.cleanedMicAudioPath {
                try Self.removeIfExists(cleanedURL)
            }
            if let transcriptURL = recording.transcriptURL {
                try Self.removeIfExists(transcriptURL)
            }
        }
    }

    private func eraseMainDatabase() async throws {
        try await storage.close()
        try removeDatabaseFiles(named: AppConstants.Paths.databaseFileName)
    }

    private static func removeIfExists(_ url: URL) throws {
        guard FileManager.default.fileExists(atPath: url.path) else { return }
        try FileManager.default.removeItem(at: url)
    }

    private func removeDatabaseFiles(named fileName: String) throws {
        let base = appSupportDirectory.appendingPathComponent(fileName).path
        for suffix in ["", "-wal", "-shm"] {
            try Self.removeIfExists(URL(fileURLWithPath: base + suffix))
        }
    }
}

import Foundation
import Testing
import Domain
import MLInfrastructure
import StorageInfrastructure
@testable import TheRecord

@Suite("LiveDataEraser")
struct LiveDataEraserTests {

    private func makeStorage() async throws -> GRDBStorageActor {
        try await Task.detached { try GRDBStorageActor(databasePath: nil) }.value
    }

    private func makeConfigManager(tempDir: URL) -> ConfigManager {
        ConfigManager(configPath: tempDir.appendingPathComponent("config.json"))
    }

    /// Unique per-test service name so the suite never touches the real
    /// "app.the-record.mcp" Keychain entries on the developer's machine.
    private func makeCredentialStore() -> KeychainCredentialStore {
        KeychainCredentialStore(service: "app.the-record.tests.\(UUID().uuidString)")
    }

    private func seedRecording(storage: GRDBStorageActor, audioURL: URL) async throws {
        try Data("fake-wav-bytes".utf8).write(to: audioURL)
        let file = AudioFile(
            id: .generate(),
            url: audioURL,
            recordedAt: Date(),
            duration: 1.0,
            fileSize: 14,
            configuration: AudioConfiguration(),
            sampleCount: 16_000
        )
        _ = try await storage.saveRecording(file)
    }

    @Test("erases WAV recordings and returns their label")
    func erasesWavRecordings() async throws {
        let tempDir = FileManager.default.temporaryDirectory
            .appendingPathComponent("LiveDataEraserTests-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: tempDir) }

        let audioURL = tempDir.appendingPathComponent("recording.wav")
        let storage = try await makeStorage()
        try await seedRecording(storage: storage, audioURL: audioURL)

        let eraser = LiveDataEraser(
            storage: storage,
            reader: storage,
            credentialStore: makeCredentialStore(),
            configManager: makeConfigManager(tempDir: tempDir),
            appSupportDirectory: tempDir
        )

        let erased = try await eraser.eraseAllData()

        #expect(!FileManager.default.fileExists(atPath: audioURL.path))
        #expect(erased.contains("WAV recordings"))
    }

    @Test("erases persisted config file")
    func erasesConfigFile() async throws {
        let tempDir = FileManager.default.temporaryDirectory
            .appendingPathComponent("LiveDataEraserTests-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: tempDir) }

        let configManager = makeConfigManager(tempDir: tempDir)
        _ = try await configManager.load() // creates the file with defaults

        let storage = try await makeStorage()
        let eraser = LiveDataEraser(
            storage: storage,
            reader: storage,
            credentialStore: makeCredentialStore(),
            configManager: configManager,
            appSupportDirectory: tempDir
        )

        let erased = try await eraser.eraseAllData()

        #expect(!FileManager.default.fileExists(atPath: tempDir.appendingPathComponent("config.json").path))
        #expect(erased.contains("App preferences"))
    }

    @Test("partial failure surfaces failed resource labels")
    func partialFailureWhenWavDeletionFails() async throws {
        let tempDir = FileManager.default.temporaryDirectory
            .appendingPathComponent("LiveDataEraserTests-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: tempDir) }

        // A recording metadata row pointing at a URL with no actual file on disk is
        // treated as already-clean, not a failure — assert the happy path holds.
        let storage = try await makeStorage()
        let missingAudioURL = tempDir.appendingPathComponent("missing.wav")
        let file = AudioFile(
            id: .generate(),
            url: missingAudioURL,
            recordedAt: Date(),
            duration: 1.0,
            fileSize: 0,
            configuration: AudioConfiguration(),
            sampleCount: 0
        )
        _ = try await storage.saveRecording(file)

        let eraser = LiveDataEraser(
            storage: storage,
            reader: storage,
            credentialStore: makeCredentialStore(),
            configManager: makeConfigManager(tempDir: tempDir),
            appSupportDirectory: tempDir
        )

        let erased = try await eraser.eraseAllData()
        #expect(erased.contains("WAV recordings"))
    }
}

import Domain
import Foundation
import Logging
import Utilities

private let logger = AppLogger.for(category: "ConfigManager")

public actor ConfigManager {
    private let configPath: URL
    private let encoder: JSONEncoder
    private let decoder: JSONDecoder

    // MARK: - Init

    /// Designated initialiser — use a custom path (e.g. temp dir in tests).
    public init(configPath: URL) {
        self.configPath = configPath
        encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        decoder = JSONDecoder()
    }

    /// Initialiser that stores config at `~/.therecord/config.json`.
    public init() {
        let home = FileManager.default.homeDirectoryForCurrentUser
        let path = home.appendingPathComponent(AppConstants.Paths.configDirectoryName).appendingPathComponent(AppConstants.Paths.configFileName)
        configPath = path
        encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        decoder = JSONDecoder()
    }

    // MARK: - Load

    /// Reads the config file, decodes it, and merges defaults for any missing top-level keys.
    /// Creates the file with default values if it does not exist.
    public func load() async throws -> AppConfig {
        let fm = FileManager.default

        guard fm.fileExists(atPath: self.configPath.path) else {
            logger.info("Config file absent — creating defaults at \(self.configPath.path, privacy: .public)")
            let defaults = AppConfig.default
            try await save(defaults)
            return defaults
        }

        let data = try await Task.detached(priority: .utility) { try Data(contentsOf: self.configPath) }.value

        // Attempt a full decode first.
        do {
            return try decoder.decode(AppConfig.self, from: data)
        } catch {
            let fieldPath: String = if let de = error as? DecodingError {
                switch de {
                case let .typeMismatch(_, ctx): ctx.codingPath.map(\.stringValue).joined(separator: ".")
                case let .keyNotFound(_, ctx): ctx.codingPath.map(\.stringValue).joined(separator: ".")
                case let .valueNotFound(_, ctx): ctx.codingPath.map(\.stringValue).joined(separator: ".")
                case let .dataCorrupted(ctx): ctx.codingPath.map(\.stringValue).joined(separator: ".")
                @unknown default: "<unknown>"
                }
            } else {
                "<unknown>"
            }
            // swiftlint:disable:next line_length
            logger.error("ConfigManager full-decode failed at field '\(fieldPath, privacy: .private)': \(error, privacy: .public)")
        }

        // Partial decode: decode each sub-config independently, fall back to defaults.
        logger.warning("Full AppConfig decode failed — merging partial config with defaults")
        struct PartialAppConfig: Decodable {
            let summarization: SummaryConfig?
            let transcription: TranscriptionConfig?
            let storage: StorageConfig?
            let translation: TranslationConfig?
            let contextCache: ContextCacheConfig?
            let audioCapture: AudioCaptureConfig?
            let uiTheme: UITheme?
            let privacyMode: PrivacyMode?
        }
        do {
            let partial = try decoder.decode(PartialAppConfig.self, from: data)
            return AppConfig(
                summarization: partial.summarization ?? .default,
                transcription: partial.transcription ?? .default,
                storage: partial.storage ?? .default,
                translation: partial.translation ?? .disabled,
                contextCache: partial.contextCache ?? .default,
                audioCapture: partial.audioCapture ?? .default,
                uiTheme: partial.uiTheme ?? UITheme.default,
                privacyMode: partial.privacyMode ?? PrivacyMode.default
            )
        } catch {
            logger.error("Partial decode also failed: \(error, privacy: .private) — returning defaults")
            return AppConfig.default
        }
    }

    // MARK: - Save

    /// Encodes `config` to JSON and atomically writes it to `configPath`.
    public func save(_ config: AppConfig) async throws {
        let dir = configPath.deletingLastPathComponent()
        try Directories.ensureDirectory(at: dir)

        let data = try encoder.encode(config)
        let tmp = configPath.appendingPathExtension("tmp")
        try await Task.detached(priority: .utility) { try data.write(to: tmp, options: .atomic) }.value
        _ = try FileManager.default.replaceItemAt(self.configPath, withItemAt: tmp)
        logger.debug("Config saved to \(self.configPath.path, privacy: .private)")
    }

    // MARK: - Delete

    /// Deletes the persisted config file, if present. Used by "Delete All Data" (issue #301).
    public func deleteConfigFile() throws {
        guard FileManager.default.fileExists(atPath: configPath.path) else { return }
        try FileManager.default.removeItem(at: configPath)
    }
}

