import Foundation
import OSLog
import Domain

/// Use case for enrolling and updating speaker profiles with voice embeddings.
public actor EnrollSpeakerUseCase {
    private let store: any SpeakerProfileStore
    private let embedding: any VoiceEmbeddingEngine
    private let logger = Logger(subsystem: "app.the-record", category: "EnrollSpeaker")

    /// Initializes the use case with a speaker profile store and voice embedding engine.
    /// - Parameters:
    ///   - store: The store for persisting speaker profiles.
    ///   - embedding: The engine for extracting voice embeddings from audio samples.
    public init(store: any SpeakerProfileStore, embedding: any VoiceEmbeddingEngine) {
        self.store = store
        self.embedding = embedding
    }

    /// Enrolls a new speaker with an audio sample.
    /// - Parameters:
    ///   - name: The speaker's name (must not be empty or whitespace-only).
    ///   - samples: Raw audio samples as floats (must contain at least 16000 samples).
    /// - Returns: The created speaker profile.
    /// - Throws: `Speakererror.invalidName`, `SpeakerError.insufficientAudio`, or `SpeakerError.duplicateName`.
    public func enroll(name: String, samples: [Float]) async throws -> SpeakerProfile {
        guard !name.trimmingCharacters(in: .whitespaces).isEmpty else {
            throw SpeakerError.invalidName
        }
        guard samples.count >= 16000 else {
            throw SpeakerError.insufficientAudio
        }

        let vector = await embedding.extract(from: samples)
        let profile = SpeakerProfile(
            name: name, embedding: vector, sampleCount: 1,
        )
        let existing = try await store.allProfiles()
        if existing.contains(where: { $0.name == name }) {
            throw SpeakerError.duplicateName
        }
        try await store.save(profile)
        logger.info("Enrolled speaker '\(name, privacy: .private)' with \(samples.count, privacy: .public) samples")
        return profile
    }

    /// Updates a speaker profile by averaging new voice samples into the existing embedding.
    /// - Parameters:
    ///   - profileId: The ID of the speaker profile to update.
    ///   - newSamples: Additional raw audio samples to incorporate into the embedding.
    /// - Returns: The updated speaker profile.
    /// - Throws: `SpeakerError.profileNotFound` if the profile does not exist.
    public func updateWithAdditionalSamples(
        profileId: SpeakerID, newSamples: [Float],
    ) async throws -> SpeakerProfile {
        let newVector = await embedding.extract(from: newSamples)

        try await store.updateProfile(id: profileId) { profile in
            let weight = Float(profile.sampleCount)
            let totalWeight = weight + 1.0
            var merged = profile.embedding
            for i in 0 ..< merged.count {
                merged[i] = (merged[i] * weight + newVector[i]) / totalWeight
            }
            return SpeakerProfile(
                id: profile.id, name: profile.name,
                embedding: merged, enrolledAt: profile.enrolledAt,
                sampleCount: profile.sampleCount + 1,
            )
        }

        let profiles = try await store.allProfiles()
        guard let updated = profiles.first(where: { $0.id == profileId }) else {
            throw SpeakerError.profileNotFound
        }
        return updated
    }
}

import Foundation
import OSLog
import Domain

public actor MatchSpeakersUseCase {
    private static let minimumSegmentSamples = 8000 // 0.5 s @ 16 kHz

    private let store: any SpeakerProfileStore
    private let embedding: any VoiceEmbeddingEngine
    private let matchThreshold: Float
    private let logger = Logger(subsystem: "app.the-record", category: "MatchSpeakers")

    public init(
        store: any SpeakerProfileStore,
        embedding: any VoiceEmbeddingEngine,
        matchThreshold: Float = 0.75,
    ) {
        self.store = store
        self.embedding = embedding
        self.matchThreshold = matchThreshold
    }

    public func matchSpeaker(samples: [Float]) async throws -> SpeakerMatch? {
        let profiles = try await store.allProfiles()
        guard !profiles.isEmpty else { return nil }

        let queryVector = await embedding.extract(from: samples)
        var bestMatch: SpeakerMatch?
        for profile in profiles {
            try Task.checkCancellation()
            let similarity = await embedding.cosineSimilarity(queryVector, profile.embedding)
            if similarity >= matchThreshold {
                if similarity > Float(bestMatch?.confidence ?? 0) {
                    bestMatch = SpeakerMatch(
                        profileId: profile.id,
                        profileName: profile.name,
                        confidence: Double(similarity),
                    )
                }
            }
        }

        if let match = bestMatch {

            logger
                .info(
                    // swiftlint:disable:next line_length
                    "Matched speaker '\(match.profileName, privacy: .public)' (conf: \(match.confidence, format: .fixed(precision: 2), privacy: .public))",
                )
        }
        return bestMatch
    }

    public func labelDiarization(
        _ transcript: DiarizedTranscript, audioSamples: [Float],
        sampleRate: Double = 16000,
    ) async throws -> DiarizedTranscript {
        let profiles = try await store.allProfiles()
        guard !profiles.isEmpty else { return transcript }

        var labelMap: [SpeakerID: (profileId: SpeakerID, name: String)] = [:]

        for segment in transcript.segments {
            try Task.checkCancellation()

            guard labelMap[segment.speakerId] == nil else { continue }
            let start = Int(segment.startTime * sampleRate)
            let end = min(Int(segment.endTime * sampleRate), audioSamples.count)
            guard end > start, end - start >= Self.minimumSegmentSamples else { continue }

            let segmentSamples = Array(audioSamples[start ..< end])
            if let match = try await matchSpeaker(samples: segmentSamples) {
                labelMap[segment.speakerId] = (profileId: match.profileId, name: match.profileName)
            }
        }

        guard !labelMap.isEmpty else { return transcript }

        let relabeled = transcript.segments.map { seg in
            if let mapping = labelMap[seg.speakerId] {
                return DiarizedSegment(
                    text: seg.text, speakerId: mapping.profileId,
                    startTime: seg.startTime, endTime: seg.endTime,
                    confidence: seg.confidence,
                )
            }
            return seg
        }

        logger
            .info(
                // swiftlint:disable:next line_length
                "Relabeled \(labelMap.count, privacy: .public) speakers: \(labelMap.values.map(\.name).joined(separator: ", "), privacy: .private)",
            )
        return DiarizedTranscript(
            segments: relabeled,
            speakerCount: transcript.speakerCount,
            processingTime: transcript.processingTime,
        )
    }
}

import Foundation
import OSLog
import Domain

/// Orchestrates a post-transcription diarization pass.
///
/// Loads stored audio for a recording, runs it through the diarization engine
/// to identify speaker boundaries, then merges those boundaries with the
/// transcription segments to produce a fully attributed ``DiarizedTranscript``.
///
/// Each ``TranscriptionSegment`` is assigned the speaker whose time range has
/// the maximum overlap with it. Segments that fall entirely outside all speaker
/// ranges are labelled `"Unknown"`.
///
/// All I/O is delegated to injected domain protocols — this actor contains no
/// direct file-system, audio-framework, or inference dependencies.
public actor DiarizeMeetingUseCase {

    // MARK: - Dependencies

    private let diarization: any DiarizationEngine
    private let sampleLoader: any AudioSampleLoader
    private let reader: any RecordingReadRepository
    private let writer: any DiarizationWriteRepository

    // MARK: - Logging

    private let logger = Logger(subsystem: "app.the-record", category: "Diarization")

    // MARK: - Init

    public init(
        diarization: any DiarizationEngine,
        sampleLoader: any AudioSampleLoader,
        reader: any RecordingReadRepository,
        writer: any DiarizationWriteRepository
    ) {
        self.diarization = diarization
        self.sampleLoader = sampleLoader
        self.reader = reader
        self.writer = writer
    }

    // MARK: - Diarize

    /// Produces a diarized transcript by aligning speaker segments with
    /// transcription segments for a stored recording.
    ///
    /// - Parameters:
    ///   - recordingId: Unique identifier of the stored recording.
    ///   - transcription: The transcription result to enrich with speaker labels.
    /// - Returns: A ``DiarizedTranscript`` where every segment carries a speaker
    ///   identity, or `"Unknown"` when no speaker segment overlaps it.
    /// - Throws: Any error produced by storage, sample loader, or diarization —
    ///   errors are never swallowed here.
    public func diarize(
        recordingId: RecordingID,
        transcription: TranscriptionResult,
    ) async throws -> DiarizedTranscript {
        logger.info("Starting diarization for \(recordingId.rawValue, privacy: .public)")

        let recording = try await reader.getRecording(id: recordingId)
        let audioURL = recording.metadata.audioURL
        logger.info("Retrieved recording: \(recording.metadata.id, privacy: .public)")

        let samples = try await sampleLoader.loadSamples(from: audioURL)
        // swiftlint:disable:next line_length
        logger.info("Loaded \(samples.count, privacy: .public) samples from \(audioURL.lastPathComponent, privacy: .public)")

        let startTime = CFAbsoluteTimeGetCurrent()
        let speakerSegments = try await runDiarization(samples: samples)
        let diarizedSegments = alignSegments(speakers: speakerSegments, transcription: transcription)
        let elapsed = CFAbsoluteTimeGetCurrent() - startTime

        let uniqueSpeakers = Set(speakerSegments.map(\.speakerId))
        // swiftlint:disable:next line_length
        logger.info("Merged \(diarizedSegments.count, privacy: .public) segments across \(uniqueSpeakers.count, privacy: .public) speakers in \(elapsed, format: .fixed(precision: 3), privacy: .public)s")

        let diarizedTranscript = DiarizedTranscript(
            segments: diarizedSegments,
            speakerCount: uniqueSpeakers.count,
            processingTime: elapsed,
        )

        try await writer.attachDiarization(id: recordingId, diarization: diarizedTranscript)
        logger.info("Saved \(diarizedTranscript.segments.count, privacy: .public) segments for \(recordingId, privacy: .private)")

        return diarizedTranscript
    }

    // MARK: - Helpers

    /// Prepares the diarization engine if needed and runs it on the given samples.
    private func runDiarization(samples: [Float]) async throws -> [SpeakerSegment] {
        if await !diarization.isReady() { try await diarization.prepare() }
        let segments = try await diarization.diarize(samples: samples, sampleRate: 16000)
        logger.info("Diarization engine returned \(segments.count, privacy: .public) speaker segments")
        for (i, seg) in segments.prefix(10).enumerated() {
            // swiftlint:disable:next line_length
            logger.info("  speaker[\(i, privacy: .public)]: id=\(seg.speakerId, privacy: .public) start=\(seg.startTime, format: .fixed(precision: 1), privacy: .public)s end=\(seg.endTime, format: .fixed(precision: 1), privacy: .public)s")
        }
        return segments
    }

    /// Aligns transcription segments with speaker segments by maximum time overlap.
    private func alignSegments(
        speakers: [SpeakerSegment],
        transcription: TranscriptionResult,
    ) -> [DiarizedSegment] {
        // swiftlint:disable:next line_length
        logger.info("Merging \(speakers.count, privacy: .public) speaker segments × \(transcription.segments.count, privacy: .public) transcription segments")
        for (i, seg) in transcription.segments.prefix(5).enumerated() {
            // swiftlint:disable:next line_length
            logger.info("  transcript[\(i, privacy: .public)]: start=\(seg.startTime, format: .fixed(precision: 1), privacy: .public)s end=\(seg.endTime, format: .fixed(precision: 1), privacy: .public)s text=\(String(seg.text.prefix(40)), privacy: .private)")
        }
        return transcription.segments.map { seg in
            let best = speakers
                .map { (speaker: $0, overlap: overlapDuration($0, seg)) }
                .max(by: { $0.overlap < $1.overlap })
            let speakerId: SpeakerID = if let b = best, b.overlap > 0 { b.speaker.speakerId } else { .unknown }
            return DiarizedSegment(
                text: seg.text,
                speakerId: speakerId,
                startTime: seg.startTime,
                endTime: seg.endTime,
                confidence: seg.confidence,
            )
        }
    }

    nonisolated private func overlapDuration(
        _ speaker: SpeakerSegment,
        _ transcript: TranscriptionSegment,
    ) -> TimeInterval {
        max(0, min(speaker.endTime, transcript.endTime) - max(speaker.startTime, transcript.startTime))
    }
}

