private func makeTranscriptionResultForDiarization() -> TranscriptionResult {
    let segments = [
        TranscriptionSegment(
            id: SegmentID("seg-0"),
            text: "Hello world",
            startTime: 0.0,
            endTime: 5.0,
            confidence: 0.9,
            isFinal: true,
            sequenceNumber: 0,
        ),
        TranscriptionSegment(
            id: SegmentID("seg-1"),
            text: "How are you",
            startTime: 5.0,
            endTime: 10.0,
