6	public struct VoiceEmbeddingActor: VoiceEmbeddingEngine, Sendable {
7	    public init() {}
8	
9	    public func extract(from samples: [Float]) async -> [Float] {
10	        await Task.detached(priority: .userInitiated) {
11	            VoiceEmbedding.extract(from: samples)
12	        }.value
13	    }
14	
15	    public func cosineSimilarity(_ a: [Float], _ b: [Float]) async -> Float {
16	        await Task.detached(priority: .userInitiated) {
17	            VoiceEmbedding.cosineSimilarity(a, b)
18	        }.value
19	    }
20	}
21	
22	public enum VoiceEmbedding {
23	    private static let logger = AppLogger.for(category: "VoiceEmbedding")
24	    private static let embeddingDim = 64
25	    private static let fftSize = 512
26	    private static let hopSize = 256
27	    private static let numMelBands = 40
28	    private static let sampleRate: Float = 16000
29	    /// Wraps the C FFT setup so vDSP_destroy_fftsetup is called deterministically at process exit.
30	    private final class FFTSetupBox {
31	        let setup: OpaquePointer
32	        init?(_ log2n: vDSP_Length) {
33	            guard let s = vDSP_create_fftsetup(log2n, FFTRadix(kFFTRadix2)) else { return nil }
34	            setup = s
35	        }
36	
37	        deinit { vDSP_destroy_fftsetup(setup) }
38	    }
39	
40	    // Safety: created once at process load time, then only read concurrently.
41	    private nonisolated(unsafe) static let fftSetupBox: FFTSetupBox? = FFTSetupBox(vDSP_Length(9))
42	
43	    /// #279: Hann window computed once instead of per frame (was recomputed
44	    /// up to 200 times per extract call).
45	    private static let hannWindow: [Float] = {
46	        var window = [Float](repeating: 0, count: fftSize)
47	        vDSP_hann_window(&window, vDSP_Length(fftSize), Int32(vDSP_HANN_NORM))
48	        return window
49	    }()
50	
51	    public static func extract(from samples: [Float]) -> [Float] {
52	        guard samples.count >= fftSize else {
53	            return [Float](repeating: 0, count: embeddingDim)
54	        }
55	
56	        let melEnergies = computeMelSpectrogram(samples)
57	        return averageAndProject(melEnergies)
58	    }
59	
60	    public static func cosineSimilarity(_ a: [Float], _ b: [Float]) -> Float {
61	        guard a.count == b.count, !a.isEmpty else { return 0 }
62	        var dot: Float = 0, normA: Float = 0, normB: Float = 0
63	        vDSP_dotpr(a, 1, b, 1, &dot, vDSP_Length(a.count))
64	        vDSP_svesq(a, 1, &normA, vDSP_Length(a.count))
65	        vDSP_svesq(b, 1, &normB, vDSP_Length(b.count))
66	        let denom = sqrt(normA) * sqrt(normB)
67	        guard denom > 0 else { return 0 }
68	        return dot / denom
69	    }
70	
71	    private static func computeMelSpectrogram(_ samples: [Float]) -> [[Float]] {
72	        let numFrames = (samples.count - fftSize) / hopSize + 1
73	        guard numFrames > 0 else { return [] }
74	
75	        var frames: [[Float]] = []
76	        frames.reserveCapacity(min(numFrames, 200))
77	        // #279: frames are zero-copy sub-spans of the input instead of a
78	        // fresh 2 KB [Float] per frame (up to 200 per extract call).
79	        // `Array.span` is macOS 26-gated, so the span comes from the buffer
80	        // pointer (SE-0447); it never escapes this closure.
81	        samples.withUnsafeBufferPointer { buf in
82	            let span = Span(_unsafeElements: buf)
83	            for i in 0 ..< min(numFrames, 200) {
84	                let start = i * hopSize
85	                let end = start + fftSize
86	                guard end <= span.count else { break }
87	                let power = computePowerSpectrum(span.extracting(start ..< end))
88	                let mel = applyMelFilterbank(power)
89	                frames.append(mel)
90	            }
91	        }
92	        return frames
93	    }
94	
95	    private static func computePowerSpectrum(_ frame: Span<Float>) -> [Float] {
96	        let log2n = vDSP_Length(log2(Float(fftSize)))
97	        guard let setup = Self.fftSetupBox?.setup else {
98	            return [Float](repeating: 0, count: fftSize / 2)
99	        }
100	
101	        var realPart = [Float](repeating: 0, count: fftSize / 2)
102	        var imagPart = [Float](repeating: 0, count: fftSize / 2)
103	        // #279: the windowed frame lives in a 2 KB stack scratch buffer
104	        // instead of two heap arrays per frame (`var windowed = frame` copy
105	        // plus a per-frame Hann recompute — see the cached hannWindow above).
