import Domain
import Foundation

// MARK: - Speaker profiles + audio device config

extension SettingsViewModel {
    public func loadProfiles() async {
        guard let store = profileStore else { return }
        do {
            speakerProfiles = try await store.allProfiles()
        } catch {
            errorMessage = "Failed to load speaker profiles"
        }
    }

    public func deleteProfile(id: SpeakerID) async {
        guard let store = profileStore else { return }
        do {
            try await store.delete(id: id)
            speakerProfiles.removeAll { $0.id == id }
        } catch {
            errorMessage = "Failed to delete profile"
        }
    }

    public func loadAudioDevices() {
        guard let enumerator = deviceEnumeration else { return }
        outputDevices = enumerator.listOutputDevices()
        inputDevices = enumerator.listInputDevices()
        if selectedOutputDeviceID.isEmpty, let d = enumerator.defaultOutputDevice() {
            selectedOutputDeviceID = d.id.rawValue
        }
        if selectedInputDeviceID.isEmpty, let d = enumerator.defaultInputDevice() {
            selectedInputDeviceID = d.id.rawValue
        }
    }

    public func saveAudioDeviceSelection() async {
        guard let store = audioDeviceConfigStore else { return }
        let newCapture = AudioCaptureConfig(
            outputDeviceUID: tapAllAudio ? nil :
                (selectedOutputDeviceID.isEmpty ? nil : DeviceID(selectedOutputDeviceID)),
            inputDeviceUID: selectedInputDeviceID.isEmpty ? nil : DeviceID(selectedInputDeviceID),
            tapAllAudio: tapAllAudio,
            echoCancellationEnabled: echoCancellationEnabled
        )
        do {
            try await store.save(newCapture)
        } catch {
            errorMessage = "Failed to save audio device selection"
        }
    }
}

