import SwiftUI

extension SettingsView {
    var transcriptionTab: some View {
        Form {
            Section("Engine") {
                Picker("Default engine", selection: $viewModel.defaultEngine) {
                    Text("Parakeet TDT (155x RTF, recommended)").tag(TranscriptionEngineKey.parakeet)
                    Text("WhisperKit (English fallback)").tag(TranscriptionEngineKey.whisperkit)
                }
                .onChange(of: viewModel.defaultEngine) { viewModel.saveEngine() }
                Text("Takes effect on next launch.")
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }
            Section("Translation") {
                Toggle("Live translation", isOn: $viewModel.translationEnabled)
                if viewModel.translationEnabled {
                    TextField("Source language", text: $viewModel.sourceLanguage)
                    TextField("Target language", text: $viewModel.targetLanguage)
                }
            }
            Section("Post-Recording") {
                Toggle("Archive pass (re-transcribe with high-accuracy model)", isOn: $viewModel.archivePassEnabled)
                    .accessibilityLabel("Enable archive transcription pass")
                Text("When enabled, the live transcript is replaced by a higher-accuracy version after the meeting ends. Disable on 8 GB machines to save memory.")
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }
        }
        .padding()
    }

    var speakersTab: some View {
        Form {
            Section("Voice Profiles (\(viewModel.speakerProfiles.count))") {
                if viewModel.speakerProfiles.isEmpty {
                    Text("No speaker profiles enrolled yet.")
                        .foregroundStyle(.secondary)
                } else {
                    ForEach(viewModel.speakerProfiles) { profile in
                        HStack {
                            VStack(alignment: .leading) {
                                Text(profile.name).font(.headline)
                                Text("Enrolled \(profile.enrolledAt.formatted(date: .abbreviated, time: .omitted))")
                                    .font(.caption).foregroundStyle(.secondary)
                            }
                            Spacer()
                            Text("\(profile.sampleCount) samples")
                                .font(.caption).foregroundStyle(.secondary)
                            Button(role: .destructive) {
                                Task { await viewModel.deleteProfile(id: profile.id) }
                            } label: {
                                Image(systemName: "trash")
                            }
                            .buttonStyle(.plain)
                            .accessibilityLabel("Delete \(profile.name)")
                        }
                    }
                }
            }
        }
        .padding()
    }

    var exportTab: some View {
        Form {
            Section("Export Options") {
                Label("Save to Disk — export transcript in any format", systemImage: "folder")
                Label("Email — compose with transcript attached", systemImage: "envelope")
