import Foundation
@testable import Business
import Domain

public actor MockStorageEngine: StorageEngine {

    private var store: [RecordingID: StoredRecording] = [:]
    private var diarizations: [RecordingID: DiarizedTranscript] = [:]
    private var draftStore: [RecordingID: String] = [:]

    public var saveRecordingCalled = false
    public var saveRecordingCallCount = 0
    public var getRecordingCalled = false
    public var getRecordingCallCount = 0
    public var listRecordingsCalled = false
    public var listRecordingsCallCount = 0
    public var deleteRecordingCalled = false
    public var deleteRecordingCallCount = 0
    public var updateTranscriptCalled = false
    public var searchTranscriptsCalled = false
    public var saveDraftTranscriptCalled = false
    public var getTranscriptDraftCalled = false
    public var totalStorageSizeCalled = false
    public var attachDiarizationCalled = false
    public var markNeedsRetranscriptionCalled = false
    public var markNeedsRetranscriptionCallCount = 0

    public func getSegments(id: RecordingID) async throws -> [DiarizedSegment] {
        []
    }

    public var mockStoredRecording: StoredRecording?
    public var mockRecordings: [StoredRecording] = []
    public var mockTotalSize: Int64 = 0
    public var errorToThrow: Error?

    public init() {}

    // MARK: - RecordingRepository

    public var markSessionStartedCalled = false
    public var markSessionStartedCallCount = 0

    public func markSessionStarted(id: RecordingID, startedAt: Date) async throws {
        markSessionStartedCalled = true
        markSessionStartedCallCount += 1
        if let error = errorToThrow { throw error }
    }

    public var updateCleanedMicPathCalled = false
    public var lastCleanedMicPath: URL?

    public func updateCleanedMicPath(id: RecordingID, path: URL?) async throws {
        updateCleanedMicPathCalled = true
        lastCleanedMicPath = path
        if let error = errorToThrow { throw error }
        if let existing = store[id] {
            let updated = RecordingMetadata(
                id: existing.metadata.id,
                recordedAt: existing.metadata.recordedAt,
                duration: existing.metadata.duration,
                fileSize: existing.metadata.fileSize,
                audioURL: existing.metadata.audioURL,
                transcriptURL: existing.metadata.transcriptURL,
                modelId: existing.metadata.modelId,
                processingTime: existing.metadata.processingTime,
                computeUnit: existing.metadata.computeUnit,
                wordCount: existing.metadata.wordCount,
                speakerCount: existing.metadata.speakerCount,
                diarizationTime: existing.metadata.diarizationTime,
                cleanedMicAudioPath: path
            )
            store[id] = StoredRecording(metadata: updated, transcript: existing.transcript)
        }
    }

    public func saveRecording(_ file: AudioFile) async throws -> StoredRecording {
        saveRecordingCalled = true
        saveRecordingCallCount += 1
        if let error = errorToThrow { throw error }
        if let mock = mockStoredRecording { return mock }
        let meta = RecordingMetadata(
            id: file.id,
            recordedAt: file.recordedAt,
            duration: file.duration,
            fileSize: file.fileSize,
            audioURL: file.url,
            transcriptURL: nil,
            modelId: ModelID("mock-model"),
            processingTime: 0.0,
            computeUnit: .cpuOnly,
            wordCount: 0,
        )
        let recording = StoredRecording(metadata: meta)
        store[file.id] = recording
        return recording
    }

    public func getRecording(id: RecordingID) async throws -> StoredRecording {
        getRecordingCalled = true
        getRecordingCallCount += 1
        if let error = errorToThrow { throw error }
        if let recording = store[id] { return recording }
        if let mock = mockStoredRecording { return mock }
        throw MockStorageEngineError.notFound
    }

    public var listAllRecordingsWithMetadataCallCount = 0

    public func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata] {
