    public func deleteRecording(id: RecordingID) async throws {
        deleteRecordingCalled = true
        deleteRecordingCallCount += 1
        if let error = errorToThrow { throw error }
        guard store[id] != nil || mockRecordings.contains(where: { $0.metadata.id == id }) else {
