/// Single composition root for THE RECORD.
///
/// Owns all long-lived infrastructure objects and constructs the full
/// dependency graph when `assemble(config:)` is called.
@MainActor
final class AppAssembler {

    struct Assembled {
        let appState: AppState
        let menuBarVM: MenuBarViewModel
        let libraryVM: MeetingLibraryViewModel
        let searchVM: SearchViewModel
        let detailVM: MeetingDetailViewModel
        let commitmentsVM: CommitmentsViewModel
        let contextSuggestionsVM: ContextSuggestionsViewModel
        let migrationTask: Task<Void, Never>
        let repairUseCase: RepairTranscriptUseCase
        let privacyModeProvider: LivePrivacyModeProvider
        let speakerProfileStore: JSONSpeakerProfileStore
    }

    // Long-lived infrastructure — must outlive all VMs.
    var storage: GRDBStorageActor?
    var trackCommitmentsUseCase: TrackCommitmentsUseCase?
    var transcriptionBuilt: TranscriptionSubAssembler.Built?
    // #250: retained so its init-spawned launch()/start() chain (weak self)
    // survives past buildMenuBarVM() returning — otherwise ARC deallocates it
    // before the detector ever observes a calendar event.
    var calendarAwareMeetingDetector: CalendarAwareMeetingDetector?

    let logger = AppLogger.for(category: "AppAssembler")

    // Retained so assemble() can be called again without leaking the previous loop.
    var searchSyncTask: Task<Void, Never>?
    var taskBag = TaskBag()

    /// Stops long-lived infrastructure that requires explicit teardown.
    /// Awaited from `applicationShouldTerminate` (#44, #280) so shutdown
    /// completes before the process exits — previously the detector shutdown
    /// was fire-and-forget and the database pool was never closed.
    func teardown() async {
        transcriptionBuilt?.prewarmTask.cancel()
        searchSyncTask?.cancel()
        await withAsyncTeardown {
            if let detector = calendarAwareMeetingDetector {
                await detector.shutdown()
            }
        } teardown: {
            // Storage must close even if detector shutdown misbehaves.
            do {
                try await storage?.close()
            } catch {
                logger.error("Storage close during teardown failed: \(error.localizedDescription, privacy: .public)")
            }
        }
    }

    // sequential setup — extraction would harm readability
    // swiftlint:disable:next function_body_length
    func assemble(config: AppConfig, enableCoreAudioListeners: Bool = true) async -> Assembled {
        taskBag = TaskBag()
        let st = await buildStorage()
        // #301: retain so teardown() can actually close the pool (was never assigned,
        // so storage?.close() silently no-opped on every app quit) and so LiveDataEraser
        // can be built from the live instance.
        storage = st
        // #216: composition root wiring — was constructed inline in TheRecordApp.
        let speakerProfileStore = JSONSpeakerProfileStore()
        // Resolve the commitment use case once — both engine and VM share the same instance.
        let sharedTrackUseCase = trackCommitmentsUseCase ?? TrackCommitmentsUseCase(store: InMemoryCommitmentStore())

        let alignUseCase = AlignTranscriptUseCase(
            sampleLoader: AudioFileLoader(),
            reader: st,
            writer: st
        )
        // #213: real PrivacyModeProvider, seeded from the persisted setting, so
        // ExportTranscriptUseCase/QueryContextUseCase/GenericMCPProvider stop
        // seeing nil and their privacy-mode guards actually execute.
        let privacyModeProvider = LivePrivacyModeProvider(initialMode: config.privacyMode)
        let (_, engine, suggestionsVM, queryContext) = buildEngine(
            config: config,
            fallbackTrack: sharedTrackUseCase,
            alignment: alignUseCase,
            privacyModeProvider: privacyModeProvider
        )
        let (libVM, migrationTask) = buildLibraryVM(storage: st)
        let (menuBarVM, pipelineCoordinator) = buildMenuBarVM(
            storage: st, engine: engine, suggestionsVM: suggestionsVM,
            migrationTask: migrationTask, config: config, queryContext: queryContext,
            enableCoreAudioListeners: enableCoreAudioListeners
        )

        // Initialize the Single Source of Truth
        let appState = AppState(
            recording: menuBarVM.recordingStateVM,
            library: libVM,
            initialConfig: config
        )

        // Late-bind AppState to MenuBarVM
        menuBarVM.bindAppState(appState)

        // Wire PipelineCoordinator to AppState.pipeline
        await pipelineCoordinator.setOnStateChange { [weak appState] cleanup, pipeline in
            guard let appState else { return }
            Task { @MainActor in
                appState.pipeline.cleanupState = cleanup
                appState.pipeline.pipelineState = pipeline
            }
        }

        // Recovery fires AFTER menuBarVM is wired
        taskBag.add(Task {
            do {
                let ids = try await RecoverPendingSessionsUseCase(storage: st)()
                for id in ids {
                    await menuBarVM.recoverPendingSession(id)
                }
            } catch {
                let errDesc = String(reflecting: error)
                logger.error("Crash recovery check failed: \(errDesc, privacy: .public)")
            }
        })

        let commitmentsVM = CommitmentsViewModel(useCase: sharedTrackUseCase)

        let repairEngine = transcriptionBuilt?.summarizationEngine ?? MLXSummarizationPlugin()
        let repairUseCase = RepairTranscriptUseCase(
            repairService: ProTranscriptRepairService(engine: repairEngine)
        )

        let detailVM = MeetingDetailViewModel(
            reader: st, writer: st, repairUseCase: repairUseCase
        )

        // Bind DetailVM to AppState for unified selection auto-loading
        appState.bind(detailVM: detailVM)

        let searchVM = SearchViewModel(
            searchUseCase: SearchRecordingsUseCase(storage: st),
            libraryViewModel: libVM
        )

        // Keep searchVM.meetings in sync with libraryVM whenever it reloads (#72, #85).
        searchSyncTask?.cancel()
        searchSyncTask = SearchLibrarySync.start(library: libVM, search: searchVM)

        return Assembled(
            appState: appState,
            menuBarVM: menuBarVM,
            libraryVM: libVM,
            searchVM: searchVM,
            detailVM: detailVM,
            commitmentsVM: commitmentsVM,
            contextSuggestionsVM: suggestionsVM,
            migrationTask: migrationTask,
            repairUseCase: repairUseCase,
            privacyModeProvider: privacyModeProvider,
            speakerProfileStore: speakerProfileStore
        )
    }

}

import Testing
import Foundation
@testable import Business
import Domain
