import Testing
import Foundation
@testable import Business
import Domain
import AudioInfrastructure
import MLInfrastructure

/// Integration test for real speaker enrollment + matching (#300).
///
/// Exercises the real `VoiceEmbeddingActor` (Accelerate/vDSP FFT embedding),
/// real `EnrollSpeakerUseCase`, and real `MatchSpeakersUseCase` against three
/// distinct real speakers from LibriSpeech dev-clean — no mocked embeddings
/// or mocked similarity scores. Confirms the actual math discriminates
/// between different human voices and matches a voice against itself.
///
/// Gated behind RUN_INTEGRATION_TESTS=1 so it never runs in the default unit
/// suite / CI — it loads real multi-second WAV files and runs real FFT work.
///
/// Run with:
///   RUN_INTEGRATION_TESTS=1 swift test --filter "SpeakerEnrollmentIntegration"
private let integrationEnabled = ProcessInfo.processInfo.environment["RUN_INTEGRATION_TESTS"] == "1"

@Suite("Speaker enrollment + matching integration (#300)", .serialized)
struct SpeakerEnrollmentIntegrationTests {

    // MARK: - Fixtures

    /// `Data/speaker-fixtures/speaker-<id>.wav` — real LibriSpeech dev-clean
    /// speakers, mono 16kHz float PCM, 40-100s each.
    private func fixtureURL(speakerId: String) -> URL {
        URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent() // Business/
            .deletingLastPathComponent() // Unit/
            .deletingLastPathComponent() // Tests/
            .deletingLastPathComponent() // Record-App/
            .appendingPathComponent("Data/speaker-fixtures/speaker-\(speakerId).wav")
    }

    private func loadSamples(speakerId: String) async throws -> [Float] {
        try await AudioFileLoader().loadSamples(from: fixtureURL(speakerId: speakerId))
    }

    // MARK: - AC1: enroll from real audio, embedding persisted

    @Test(
        "AC1: enrolling from a real speaker's audio persists a non-empty embedding",
        .enabled(if: integrationEnabled, "Set RUN_INTEGRATION_TESTS=1 to run this test")
    )
    func enrollFromRealAudioPersistsEmbedding() async throws {
        let store = JSONSpeakerProfileStore(directory: try makeTempDir())
        let embedding = VoiceEmbeddingActor()
        let useCase = EnrollSpeakerUseCase(store: store, embedding: embedding)

        let samples = try await loadSamples(speakerId: "2412")
        let profile = try await useCase.enroll(name: "Speaker 2412", samples: samples)

        #expect(profile.name == "Speaker 2412")
        #expect(!profile.embedding.isEmpty, "Real VoiceEmbedding must produce a non-empty embedding vector")
    }

    // MARK: - AC2: matching the same speaker's held-out audio succeeds

    @Test(
        "AC2: matching a held-out clip from the SAME enrolled speaker succeeds above threshold",
        .enabled(if: integrationEnabled, "Set RUN_INTEGRATION_TESTS=1 to run this test")
    )
    func matchSameSpeakerSucceeds() async throws {
        let store = JSONSpeakerProfileStore(directory: try makeTempDir())
        let embedding = VoiceEmbeddingActor()
        let enroll = EnrollSpeakerUseCase(store: store, embedding: embedding)
        let match = MatchSpeakersUseCase(store: store, embedding: embedding)

        let allSamples = try await loadSamples(speakerId: "2078")
        let half = allSamples.count / 2
        // Enroll from the first half, match against the second half — same
        // speaker, disjoint audio, so this is a genuine same-speaker test.
        _ = try await enroll.enroll(name: "Speaker 2078", samples: Array(allSamples[..<half]))

