import Testing
import Foundation
@testable import Business
import Domain
import TestMocks

// MARK: - Factories

private func makeStoredRecordingForDiarization(
    id: RecordingID = RecordingID("recording-001"),
    audioURL: URL = URL(fileURLWithPath: "/recordings/test-audio.wav"),
) -> StoredRecording {
    let meta = RecordingMetadata(
        id: id,
        recordedAt: Date(timeIntervalSince1970: 1_700_000_000),
        duration: 120.0,
        fileSize: 2_097_152,
        audioURL: audioURL,
        transcriptURL: nil,
        modelId: ModelID("openai_whisper-tiny"),
        processingTime: 2.0,
        computeUnit: .cpuAndNeuralEngine,
        wordCount: 0,
    )
    return StoredRecording(metadata: meta)
}

private func makeTranscriptionResultForDiarization() -> TranscriptionResult {
    let segments = [
        TranscriptionSegment(
            id: SegmentID("seg-0"),
            text: "Hello world",
            startTime: 0.0,
            endTime: 5.0,
            confidence: 0.9,
            isFinal: true,
            sequenceNumber: 0,
        ),
        TranscriptionSegment(
            id: SegmentID("seg-1"),
            text: "How are you",
            startTime: 5.0,
            endTime: 10.0,
            confidence: 0.8,
            isFinal: true,
            sequenceNumber: 1,
        ),
        TranscriptionSegment(
            id: SegmentID("seg-2"),
            text: "I am fine",
            startTime: 10.0,
            endTime: 15.0,
            confidence: 0.85,
            isFinal: true,
            sequenceNumber: 2,
        ),
    ]
    return TranscriptionResult(
        segments: segments,
        fullText: "Hello world How are you I am fine",
        processingTime: 1.0,
        modelId: ModelID("openai_whisper-tiny"),
        recordedAt: Date(timeIntervalSince1970: 1_700_000_000),
        computeUnit: .cpuAndNeuralEngine,
        passType: .cleanup,
    )
}

/// Builds a two-segment transcription where `seg-gap` (20–25 s) falls outside
/// all speaker coverage, used to verify the "Unknown" fallback.
private func makeTranscriptionWithGapSegment() -> TranscriptionResult {
    let segments = [
        TranscriptionSegment(
            id: SegmentID("seg-0"),
            text: "Hello",
            startTime: 0.0,
            endTime: 5.0,
            confidence: 0.9,
            isFinal: true,
            sequenceNumber: 0,
        ),
        TranscriptionSegment(
            id: SegmentID("seg-gap"),
            text: "Gap segment",
            startTime: 20.0,
            endTime: 25.0,
            confidence: 0.7,
            isFinal: true,
            sequenceNumber: 1,
        ),
    ]
    return TranscriptionResult(
        segments: segments,
        fullText: "Hello Gap segment",
        processingTime: 1.0,
        modelId: ModelID("openai_whisper-tiny"),
        recordedAt: Date(timeIntervalSince1970: 1_700_000_000),
        computeUnit: .cpuAndNeuralEngine,
        passType: .cleanup,
    )
}

/// speaker-0 covers 0–7 s, speaker-1 covers 7–15 s.
/// Expected assignments:
///   seg-0 (0-5):   overlap speaker-0 = 5.0, speaker-1 = 0.0 → speaker-0
///   seg-1 (5-10):  overlap speaker-0 = 2.0, speaker-1 = 3.0 → speaker-1
///   seg-2 (10-15): overlap speaker-0 = 0.0, speaker-1 = 5.0 → speaker-1
private func makeSpeakerSegmentsForDiarization() -> [SpeakerSegment] {
    [
        SpeakerSegment(speakerId: SpeakerID("speaker-0"), startTime: 0.0, endTime: 7.0, confidence: 0.9),
        SpeakerSegment(speakerId: SpeakerID("speaker-1"), startTime: 7.0, endTime: 15.0, confidence: 0.85),
    ]
}

// MARK: - BM-038 Spy

//
// SpyDiarizationEngine exists because MockDiarizationEngine.isReady() is
// coupled to errorToThrow — there is no way to model "not ready but
// prepare() succeeds" (AC-A) without modifying the shared mock.
// BM-038 GREEN agent: implement isReady()+prepare() gate in
// DiarizeMeetingUseCase.diarize(), then these three tests go green.

private actor SpyDiarizationEngine: DiarizationEngine {
    var ready: Bool
    var prepareError: (any Error)?

    var prepareCalled = false
    var prepareCallCount = 0
    var diarizeCalled = false
    var diarizeCallCount = 0

    init(ready: Bool = false, prepareError: (any Error)? = nil) {
        self.ready = ready
        self.prepareError = prepareError
    }

    func isReady() async -> Bool {
        ready
    }

    func prepare() async throws {
        prepareCalled = true
        prepareCallCount += 1
        if let error = prepareError { throw error }
        ready = true
    }

    func diarize(samples: [Float], sampleRate: Int) async throws -> [SpeakerSegment] {
        diarizeCalled = true
        diarizeCallCount += 1
        return [
            SpeakerSegment(speakerId: SpeakerID("speaker-0"), startTime: 0.0, endTime: 15.0, confidence: 0.9),
        ]
    }
}

// MARK: - Suite

@Suite("DiarizeMeetingUseCase")
struct DiarizeMeetingUseCaseTests {

    // MARK: - Happy path

    @Test("happy path assigns correct speakers to 3 transcript segments across 2 speaker ranges")
    func happyPathAssignsCorrectSpeakers() async throws {
        let mockStorage = MockStorageEngine()
        await mockStorage.setMockStoredRecording(makeStoredRecordingForDiarization())

        let mockDiarization = MockDiarizationEngine()
        await mockDiarization.setMockSegments(makeSpeakerSegmentsForDiarization())

        let useCase = DiarizeMeetingUseCase(
            diarization: mockDiarization,
            sampleLoader: MockAudioSampleLoader(),
            reader: mockStorage, writer: mockStorage,
        )

        let result = try await useCase.diarize(
            recordingId: RecordingID("recording-001"),
            transcription: makeTranscriptionResultForDiarization(),
        )

        #expect(result.segments.count == 3)
        #expect(result.segments[0].speakerId == SpeakerID("speaker-0"))
        #expect(result.segments[1].speakerId == SpeakerID("speaker-1"))
        #expect(result.segments[2].speakerId == SpeakerID("speaker-1"))
        #expect(result.speakerCount == 2)
    }

    // MARK: - Error propagation

    @Test("storage failure propagates without being swallowed")
    func storageFailurePropagates() async throws {
        let mockStorage = MockStorageEngine()
        await mockStorage.setErrorToThrow(MockStorageEngineError.notFound)

        let useCase = DiarizeMeetingUseCase(
            diarization: MockDiarizationEngine(),
            sampleLoader: MockAudioSampleLoader(),
            reader: mockStorage, writer: mockStorage,
        )

        await #expect(throws: (any Error).self) {
            _ = try await useCase.diarize(
                recordingId: RecordingID("recording-001"),
                transcription: makeTranscriptionResultForDiarization(),
            )
        }
    }

    @Test("diarization failure propagates without being swallowed")
    func diarizationFailurePropagates() async throws {
        let mockStorage = MockStorageEngine()
        await mockStorage.setMockStoredRecording(makeStoredRecordingForDiarization())

        let mockDiarization = MockDiarizationEngine()
        await mockDiarization.setErrorToThrow(RecordingError.sessionExpired)

        let useCase = DiarizeMeetingUseCase(
            diarization: mockDiarization,
            sampleLoader: MockAudioSampleLoader(),
            reader: mockStorage, writer: mockStorage,
        )

        await #expect(throws: (any Error).self) {
            _ = try await useCase.diarize(
                recordingId: RecordingID("recording-001"),
                transcription: makeTranscriptionResultForDiarization(),
            )
        }
    }

    // MARK: - Unknown speaker fallback

    @Test("segment outside all speaker ranges is assigned Unknown")
    func segmentWithNoOverlapGetsUnknown() async throws {
        let mockStorage = MockStorageEngine()
        await mockStorage.setMockStoredRecording(makeStoredRecordingForDiarization())

        let mockDiarization = MockDiarizationEngine()
        // Speaker segments cover 0–15 s only.
        await mockDiarization.setMockSegments(makeSpeakerSegmentsForDiarization())

        // seg-gap (20–25 s) has no overlap with the speaker segments (0–15 s).
        let transcription = makeTranscriptionWithGapSegment()

        let useCase = DiarizeMeetingUseCase(
            diarization: mockDiarization,
            sampleLoader: MockAudioSampleLoader(),
            reader: mockStorage, writer: mockStorage,
        )

        let result = try await useCase.diarize(
            recordingId: RecordingID("recording-001"),
            transcription: transcription,
        )

        #expect(result.segments.count == 2)
        #expect(result.segments[0].speakerId == SpeakerID("speaker-0"))
        #expect(result.segments[1].speakerId == SpeakerID.unknown)
    }

    // MARK: - Persistence (Codex adversarial finding 2)

    /// Verifies that diarize() persists the diarization result to storage via
    /// attachDiarization so speaker labels survive app restart.
    @Test("diarize persists diarization result via storage.attachDiarization")
    func executePersistsDiarizationViaStorage() async throws {
        let mockStorage = MockStorageEngine()
        await mockStorage.setMockStoredRecording(makeStoredRecordingForDiarization())

        let mockDiarization = MockDiarizationEngine()
        await mockDiarization.setMockSegments(makeSpeakerSegmentsForDiarization())

        let useCase = DiarizeMeetingUseCase(
            diarization: mockDiarization,
            sampleLoader: MockAudioSampleLoader(),
            reader: mockStorage, writer: mockStorage,
        )

        _ = try await useCase.diarize(
            recordingId: RecordingID("recording-001"),
            transcription: makeTranscriptionResultForDiarization(),
        )

        let called = await mockStorage.attachDiarizationCalled
        #expect(called == true)
    }

    // MARK: - Model readiness gate (BM-038)

    //
    // These three tests cover the isReady() → prepare() gate that mirrors the
    // BM-031/033 pattern in StreamingTranscriptionUseCase.
    //
    // RED today because DiarizeMeetingUseCase.diarize() calls diarize()
    // without first checking isReady() or calling prepare().

    /// AC-A: engine not ready, prepare() succeeds.
    /// Expect: prepare() IS called (lazy-load) and diarize() IS called.
    ///
    /// RED: prepareCalled stays false because the use case never calls prepare().
    @Test("engine not ready, prepare succeeds — lazy-load then diarize fires")
    func engineNotReadyPrepareSucceedsDiarizeRuns() async throws {
        let engine = SpyDiarizationEngine(ready: false, prepareError: nil)
        let mockStorage = MockStorageEngine()
        await mockStorage.setMockStoredRecording(makeStoredRecordingForDiarization())

        let useCase = DiarizeMeetingUseCase(
            diarization: engine,
            sampleLoader: MockAudioSampleLoader(),
            reader: mockStorage, writer: mockStorage,
        )

        _ = try await useCase.diarize(
            recordingId: RecordingID("recording-001"),
            transcription: makeTranscriptionResultForDiarization(),
        )

        let prepareCalled = await engine.prepareCalled
        let diarizeCalled = await engine.diarizeCalled
        #expect(prepareCalled == true, "prepare() must be called when engine is not ready")
        #expect(diarizeCalled == true, "diarize() must be called after prepare() succeeds")
    }

    /// AC-B: engine not ready, prepare() throws.
    /// Expect: execute() propagates the error AND diarize() is never called.
    ///
    /// RED (two failure modes today):
    ///  1. execute() does NOT throw (prepare is skipped entirely, diarize succeeds).
    ///  2. diarizeCalled is true (diarize() is called directly before any gate).
    @Test("engine not ready, prepare throws — diarize never fires and error propagates")
    func engineNotReadyPrepareThrowsDiarizeNeverFires() async throws {
        struct PrepareError: Error {}
        let engine = SpyDiarizationEngine(ready: false, prepareError: PrepareError())
        let mockStorage = MockStorageEngine()
        await mockStorage.setMockStoredRecording(makeStoredRecordingForDiarization())

        let useCase = DiarizeMeetingUseCase(
            diarization: engine,
            sampleLoader: MockAudioSampleLoader(),
            reader: mockStorage, writer: mockStorage,
        )

        await #expect(throws: (any Error).self) {
            _ = try await useCase.diarize(
                recordingId: RecordingID("recording-001"),
                transcription: makeTranscriptionResultForDiarization(),
            )
        }

        let diarizeCalled = await engine.diarizeCalled
        #expect(diarizeCalled == false, "diarize() must NOT be called when prepare() throws")
    }

    /// AC-C: engine already ready.
    /// Expect: prepare() is NOT called and diarize() runs immediately.
    ///
    /// Pre-green today (use case already skips prepare and calls diarize).
    /// Confirms the optimisation is preserved once the gate is added.
    @Test("engine already ready — prepare skipped, diarize runs immediately")
    func engineAlreadyReadyPrepareSkippedDiarizeRunsImmediately() async throws {
        let engine = SpyDiarizationEngine(ready: true, prepareError: nil)
        let mockStorage = MockStorageEngine()
