import AppKit
import Foundation
import Logging
import Domain
import AudioInfrastructure
import MLInfrastructure
import StorageInfrastructure
import Business
import Presentation
import RecordPro
import Utilities

/// Single composition root for THE RECORD.
///
/// Owns all long-lived infrastructure objects and constructs the full
/// dependency graph when `assemble(config:)` is called.
@MainActor
final class AppAssembler {

    struct Assembled {
        let appState: AppState
        let menuBarVM: MenuBarViewModel
        let libraryVM: MeetingLibraryViewModel
        let searchVM: SearchViewModel
        let detailVM: MeetingDetailViewModel
        let commitmentsVM: CommitmentsViewModel
        let contextSuggestionsVM: ContextSuggestionsViewModel
        let migrationTask: Task<Void, Never>
        let repairUseCase: RepairTranscriptUseCase
        let privacyModeProvider: LivePrivacyModeProvider
        let speakerProfileStore: JSONSpeakerProfileStore
    }

    // Long-lived infrastructure — must outlive all VMs.
    var storage: GRDBStorageActor?
    var trackCommitmentsUseCase: TrackCommitmentsUseCase?
    var transcriptionBuilt: TranscriptionSubAssembler.Built?
    // #250: retained so its init-spawned launch()/start() chain (weak self)
    // survives past buildMenuBarVM() returning — otherwise ARC deallocates it
    // before the detector ever observes a calendar event.
    var calendarAwareMeetingDetector: CalendarAwareMeetingDetector?

    let logger = AppLogger.for(category: "AppAssembler")

    // Retained so assemble() can be called again without leaking the previous loop.
    var searchSyncTask: Task<Void, Never>?
    var taskBag = TaskBag()

    /// Stops long-lived infrastructure that requires explicit teardown.
    /// Awaited from `applicationShouldTerminate` (#44, #280) so shutdown
    /// completes before the process exits — previously the detector shutdown
    /// was fire-and-forget and the database pool was never closed.
    func teardown() async {
        transcriptionBuilt?.prewarmTask.cancel()
        searchSyncTask?.cancel()
        await withAsyncTeardown {
            if let detector = calendarAwareMeetingDetector {
                await detector.shutdown()
            }
        } teardown: {
            // Storage must close even if detector shutdown misbehaves.
            do {
                try await storage?.close()
            } catch {
                logger.error("Storage close during teardown failed: \(error.localizedDescription, privacy: .public)")
            }
        }
    }

    // sequential setup — extraction would harm readability
    // swiftlint:disable:next function_body_length
    func assemble(config: AppConfig, enableCoreAudioListeners: Bool = true) async -> Assembled {
        taskBag = TaskBag()
        let st = await buildStorage()
        // #216: composition root wiring — was constructed inline in TheRecordApp.
        let speakerProfileStore = JSONSpeakerProfileStore()
        // Resolve the commitment use case once — both engine and VM share the same instance.
        let sharedTrackUseCase = trackCommitmentsUseCase ?? TrackCommitmentsUseCase(store: InMemoryCommitmentStore())

        let alignUseCase = AlignTranscriptUseCase(
            sampleLoader: AudioFileLoader(),
            reader: st,
            writer: st
        )
        // #213: real PrivacyModeProvider, seeded from the persisted setting, so
        // ExportTranscriptUseCase/QueryContextUseCase/GenericMCPProvider stop
        // seeing nil and their privacy-mode guards actually execute.
        let privacyModeProvider = LivePrivacyModeProvider(initialMode: config.privacyMode)
        let (_, engine, suggestionsVM, queryContext) = buildEngine(
            config: config,
            fallbackTrack: sharedTrackUseCase,
            alignment: alignUseCase,
            privacyModeProvider: privacyModeProvider
        )
        let (libVM, migrationTask) = buildLibraryVM(storage: st)
        let (menuBarVM, pipelineCoordinator) = buildMenuBarVM(
            storage: st, engine: engine, suggestionsVM: suggestionsVM,
            migrationTask: migrationTask, config: config, queryContext: queryContext,
            enableCoreAudioListeners: enableCoreAudioListeners
        )

        // Initialize the Single Source of Truth
        let appState = AppState(
            recording: menuBarVM.recordingStateVM,
            library: libVM,
            initialConfig: config
        )

        // Late-bind AppState to MenuBarVM
        menuBarVM.bindAppState(appState)

        // Wire PipelineCoordinator to AppState.pipeline
        await pipelineCoordinator.setOnStateChange { [weak appState] cleanup, pipeline in
            guard let appState else { return }
            Task { @MainActor in
                appState.pipeline.cleanupState = cleanup
                appState.pipeline.pipelineState = pipeline
            }
        }

        // Recovery fires AFTER menuBarVM is wired
        taskBag.add(Task {
            do {
                let ids = try await RecoverPendingSessionsUseCase(storage: st)()
                for id in ids {
                    await menuBarVM.recoverPendingSession(id)
                }
            } catch {
                let errDesc = String(reflecting: error)
                logger.error("Crash recovery check failed: \(errDesc, privacy: .public)")
            }
        })

        let commitmentsVM = CommitmentsViewModel(useCase: sharedTrackUseCase)

        let repairEngine = transcriptionBuilt?.summarizationEngine ?? MLXSummarizationPlugin()
        let repairUseCase = RepairTranscriptUseCase(
            repairService: ProTranscriptRepairService(engine: repairEngine)
        )

        let detailVM = MeetingDetailViewModel(
            reader: st, writer: st, repairUseCase: repairUseCase
        )

        // Bind DetailVM to AppState for unified selection auto-loading
        appState.bind(detailVM: detailVM)

        let searchVM = SearchViewModel(
            searchUseCase: SearchRecordingsUseCase(storage: st),
            libraryViewModel: libVM
        )

        // Keep searchVM.meetings in sync with libraryVM whenever it reloads (#72, #85).
        searchSyncTask?.cancel()
        searchSyncTask = SearchLibrarySync.start(library: libVM, search: searchVM)

        return Assembled(
            appState: appState,
            menuBarVM: menuBarVM,
            libraryVM: libVM,
            searchVM: searchVM,
            detailVM: detailVM,
            commitmentsVM: commitmentsVM,
            contextSuggestionsVM: suggestionsVM,
            migrationTask: migrationTask,
            repairUseCase: repairUseCase,
            privacyModeProvider: privacyModeProvider,
            speakerProfileStore: speakerProfileStore
        )
    }

}

import AppKit
import AudioInfrastructure
import Business
import Domain
import Foundation
import MLInfrastructure
import StorageInfrastructure
import OSLog
import Presentation
import Utilities
import RecordPro

// MARK: - Builder Methods

@MainActor
extension AppAssembler {

    // MARK: - Storage

    func buildStorage() async -> GRDBStorageActor {
        let isTest = ProcessInfo.processInfo.environment["XCTestConfigurationFilePath"] != nil
            || ProcessInfo.processInfo.processName.lowercased().contains("test")
            || ProcessInfo.processInfo.processName.lowercased().contains("xctest")

        let storage: GRDBStorageActor
        do {
            storage = try await Task.detached {
                try isTest ? GRDBStorageActor(databasePath: nil) : GRDBStorageActor()
            }.value
        } catch {
            let errDesc = String(reflecting: error)
            logger
                .critical(
                    "SQLite initialization failed: \(errDesc, privacy: .public) — falling back to in-memory storage",
                )
            do {
                storage = try await Task.detached {
                    try GRDBStorageActor(databasePath: nil)
                }.value
                await showFatalAlert(error: error)
            } catch let fallbackError {
                let fbDesc = String(reflecting: fallbackError)
                logger
                    .critical(
                        "SQLite fallback also failed: \(fbDesc, privacy: .public) — terminating via NSApp.terminate",
                    )
                await showFatalAlert(error: fallbackError)
                do { try await Task.sleep(nanoseconds: 10_000_000_000) } catch {}
                exit(1)
            }
        }

        let commitmentStore: GRDBCommitmentStore?
        do {
            commitmentStore = try await Task.detached {
                if isTest {
                    return try GRDBCommitmentStore(databasePath: nil)
                } else {
                    let dbDir = Directories.appSupport
                    try Directories.ensureDirectory(at: dbDir)
                    let dbURL = dbDir.appendingPathComponent(
                        AppConstants.Paths.commitmentsDatabaseFileName
                    )
                    return try GRDBCommitmentStore(databasePath: dbURL)
                }
            }.value
        } catch {
            let errDesc = String(reflecting: error)
            logger.error("Failed to init GRDBCommitmentStore: \(errDesc, privacy: .public)")
            commitmentStore = nil
        }

        trackCommitmentsUseCase = commitmentStore.map { TrackCommitmentsUseCase(store: $0) }
        return storage
    }

    /// Shows a fatal database-error alert, activates an existing instance if found,
    /// and terminates the app. Extracted to deduplicate the two identical alert blocks
    /// in `buildStorage`.
    @MainActor
    private func showFatalAlert(error: any Error) {
        let alert = NSAlert()
        alert.messageText = "THE RECORD could not start"
        // swiftlint:disable:next line_length
        let isLockError = String(describing: error).lowercased().contains("lock")
        let hint = isLockError
            ? "A previous instance of THE RECORD may still be shutting down. Force-quit it from Activity Monitor and try again."
            : "If THE RECORD is already running, quit it and try again."
        alert.informativeText = "Failed to initialise the database: \(error.localizedDescription). \(hint)"
        alert.alertStyle = .warning
        alert.addButton(withTitle: "OK")
        alert.runModal()
        if let existing = NSRunningApplication.runningApplications(
            withBundleIdentifier: AppConstants.Bundle.identifier,
        ).first(where: { $0 != .current }) {
            existing.activate()
        }
        NSApp.terminate(nil)
    }

    // MARK: - Engine

    func buildEngine(
        config: AppConfig,
        fallbackTrack: TrackCommitmentsUseCase,
        alignment: (any AlignmentUseCase)? = nil,
        privacyModeProvider: LivePrivacyModeProvider,
        // swiftlint:disable:next large_tuple
    ) -> (TrackCommitmentsUseCase, TheRecordEngine, ContextSuggestionsViewModel, QueryContextUseCase) {
        let classifyUseCase = ClassifySegmentUseCase(classifier: OnDeviceNLPPlugin())
        let providers = buildMCPProviders(config: config, privacyModeProvider: privacyModeProvider)
        let queryContext = QueryContextUseCase(privacyModeProvider: privacyModeProvider)
        let engine = TheRecordEngine(
            classify: classifyUseCase,
            track: fallbackTrack,
            query: queryContext,
            providers: providers,
            alignment: alignment,
        )
        let suggestionsVM = ContextSuggestionsViewModel()
        return (fallbackTrack, engine, suggestionsVM, queryContext)
    }

    func buildMCPProviders(config: AppConfig, privacyModeProvider: LivePrivacyModeProvider) -> [any ContextProvider] {
        guard config.mcpConsentGranted else { return [] }

        let contextCache = makeContextCache(config: config.contextCache)

        // Migrate Keychain accessibility for existing credentials (no-op on clean install).
        let credentialStore = KeychainCredentialStore()
        try? credentialStore.migrateAccessibilityIfNeeded()

        var providers = makeGenericMCPProviders(from: config.mcpEndpoints, privacyModeProvider: privacyModeProvider)

        // Notion provider: constructed when the user has enabled the Notion integration.
        if config.notionEnabled {
            providers.append(NotionProvider(credentialStore: credentialStore))
        }

        if let obsidianProvider = makeObsidianProvider(bookmark: config.obsidianVaultBookmark) {
            providers.append(obsidianProvider)
        }

        // Wrap every provider in the caching layer when a cache is available.
        guard let cache = contextCache else { return providers }
        let cacheConfig = config.contextCache
        return providers.map { provider in
            CachingContextProvider(
                inner: provider,
                cache: cache,
                ttlSeconds: cacheConfig.exactTTLSeconds,
                semanticTTLSeconds: cacheConfig.semanticTTLSeconds,
                semanticThreshold: cacheConfig.semanticThreshold,
                maxEntries: cacheConfig.maxEntries,
            )
        }
    }

    /// Semantic caching of query results, persisted under Directories.appSupport so cached
    /// entries survive relaunch. Only constructed when the user has enabled context caching;
    /// if cache initialization fails, providers degrade gracefully to working without caching.
    private func makeContextCache(config: ContextCacheConfig) -> GRDBContextCache? {
        guard config.enabled else { return nil }
        do {
            let dbDir = Directories.appSupport
            try Directories.ensureDirectory(at: dbDir)
            let dbURL = dbDir.appendingPathComponent(AppConstants.Paths.contextCacheDatabaseFileName)
            return try GRDBContextCache(databasePath: dbURL)
        } catch {
            let errDesc = String(reflecting: error)
            logger.warning("Failed to initialize context cache: \(errDesc, privacy: .public)")
            return nil
        }
    }

    private func makeGenericMCPProviders(
        from endpoints: [MCPEndpointConfig],
        privacyModeProvider: LivePrivacyModeProvider
    ) -> [any ContextProvider] {
        var providers: [any ContextProvider] = []
        for endpoint in endpoints {
            let isLocal = endpoint.url.host == "localhost" || endpoint.url.host == "127.0.0.1"
            guard endpoint.url.scheme == "https" || isLocal else { continue }
            providers.append(GenericMCPProvider(
                endpoint: endpoint.url,
                providerID: endpoint.providerID,
                privacyModeProvider: privacyModeProvider
            ))
        }
        return providers
    }

    /// The security-scoped bookmark is resolved here (the app is sandboxed; a plain path
    /// would not resolve after relaunch). Starting the security scope around actual file
    /// reads is ObsidianProvider's responsibility (see E4/E6); this call site only needs a
    /// URL to construct the provider. A stale bookmark (e.g. after a volume rename or app
    /// relocation) still resolves to a usable URL for this launch, so we log rather than
    /// fail; regenerating and persisting a fresh bookmark happens in
    /// LiveIntegrationSettingsStore.loadObsidianVaultPath(), which already owns config
    /// persistence and is re-run whenever Settings are opened.
    private func makeObsidianProvider(bookmark: Data?) -> ObsidianProvider? {
        guard let bookmark else { return nil }
        var isStale = false
        guard let vaultURL = try? URL(
            resolvingBookmarkData: bookmark,
            options: .withSecurityScope,
            relativeTo: nil,
            bookmarkDataIsStale: &isStale
        ) else {
            logger.warning("Failed to resolve Obsidian vault security-scoped bookmark; Obsidian provider disabled")
            return nil
        }
        if isStale {
            logger
                .warning(
                    // swiftlint:disable:next line_length
                    "Obsidian vault security-scoped bookmark is stale; using it for this launch, but it should be refreshed (open Settings > Integrations)"
                )
        }
        return ObsidianProvider(vaultPath: vaultURL)
    }

    // MARK: - Library VM

    func buildLibraryVM(
        storage: GRDBStorageActor,
    ) -> (MeetingLibraryViewModel, Task<Void, Never>) {
        let libVM = MeetingLibraryViewModel(storage: storage)
        let migrationTask = Task<Void, Never> {
            do {
                let migrated = try await JSONMigrationHelper.migrate(
                    from: Directories.appSupport, reader: storage, writer: storage,
                )
                if migrated > 0 { logger.info("Migrated \(migrated, privacy: .public) recordings to SQLite") }
            } catch {
                let errDesc = String(reflecting: error)
                logger.error("Migration failed: \(errDesc, privacy: .public)")
                await MainActor.run { libVM.errorMessage = "Migration failed: \(error.localizedDescription)" }
            }
        }
        return (libVM, migrationTask)
    }

    // MARK: - MenuBar VM

    // sequential setup — extraction would harm readability
    // swiftlint:disable:next function_parameter_count
    func buildMenuBarVM(
        storage: GRDBStorageActor,
        engine: TheRecordEngine,
        suggestionsVM: ContextSuggestionsViewModel,
        migrationTask: Task<Void, Never>,
        config: AppConfig,
        queryContext: QueryContextUseCase,
        enableCoreAudioListeners: Bool = true,
    ) -> (MenuBarViewModel, PipelineCoordinator) {
        let audio = AudioSubAssembler().build(
            storage: storage, config: config, queryContext: queryContext,
        )
        let transcription = TranscriptionSubAssembler().build(
            storage: storage, audioCapture: audio.audioCapture, config: config,
        )
        transcriptionBuilt = transcription
        let audioDetector = AudioSessionDetector(
            selfRecordingProvider: audio.audioCapture,
            autoListen: enableCoreAudioListeners,
        )
        let eventKit = EventKitPlugin()
        // #250: retain on self — the un-retained detector was deallocated by ARC
        // before its init-spawned background Task ever ran, making calendar-aware
        // meeting detection a silent no-op.
        calendarAwareMeetingDetector = CalendarAwareMeetingDetector(
            calendar: eventKit,
            audioDetector: audioDetector,
        )
        let pipelineCoordinator = PipelineCoordinator(
            cleanupTranscribe: transcription.cleanupUseCase,
            diarizeMeeting: transcription.diarizeUseCase,
            summarizeMeeting: transcription.summarizeUseCase,
            primaryEngine: transcription.primaryEngine,
            archivePassEnabled: config.transcription.archivePassEnabled,
        )
        Task {
            for await notification in NotificationCenter.default.notifications(named: .archivePassEnabledChanged) {
                guard let enabled = notification.userInfo?["enabled"] as? Bool else { continue }
                await pipelineCoordinator.updateArchivePassEnabled(enabled)
            }
        }
        var deps = MenuBarViewModel.Dependencies(
            startRecording: audio.startUseCase,
            stopAndTranscribe: transcription.stopUseCase,
            pipelineCoordinator: pipelineCoordinator,
            deleteRecording: DeleteRecordingUseCase(storage: storage),
            searchRecordings: SearchRecordingsUseCase(storage: storage),
            autoCleanup: audio.autoCleanup,
            exportAudio: ExportAudioUseCase(storage: storage, exportEngine: AVFoundationExporter()),
            migrationTask: migrationTask,
            engine: engine,
            contextSuggestionsVM: suggestionsVM,
            streamingTranscription: transcription.streamingUseCase,
            liveTranscriptionVM: transcription.liveTranscriptionVM,
            waveformVM: audio.waveformVM,
            liveTranslation: transcription.liveTranslateUseCase,
            listUpcomingMeetings: ListUpcomingMeetingsUseCase(calendar: eventKit),
            micAECProcessor: audio.aecProcessor,
            sleepAssertionService: IOKitSleepAssertionService(),
        )
        // epic-28 / task-003: AEC toggle + cleaned-WAV sink wiring
        deps.cleanedAudioSinkFactory = audio.cleanedAudioSinkFactory
        deps.echoCancellationEnabled = config.audioCapture.echoCancellationEnabled
        deps.cleanedMicPathWriter = storage
        // #211 / #124: wire the live disk-space monitor so the pre-recording guard
        // in RecordingStateViewModel actually executes instead of always seeing nil.
        deps.diskSpaceMonitor = FileSystemDiskSpaceMonitor()
        let menuBarVM = MenuBarViewModel(dependencies: deps)
        // #212: connect the delegate MenuBarViewModel already conforms to
        // (MenuBarViewModelDownload.swift) so real model-download progress reaches
        // downloadProgress/statusMessage instead of never firing.
        Task { await transcription.connectDownloadDelegate(menuBarVM) }
        return (menuBarVM, pipelineCoordinator)
    }
}

import Foundation
import Logging
import Domain
import Business
import AudioInfrastructure
import MLInfrastructure
import StorageInfrastructure
import Presentation

/// Builds the transcription, diarization, summarization, and export stack.
///
/// Pure struct with no stored state — call `build(storage:audioCapture:config:)` once per assembly.
@MainActor
struct TranscriptionSubAssembler {
    private let logger = AppLogger.for(category: "TranscriptionSubAssembler")
    struct Built {
        let stopUseCase: StopAndTranscribeUseCase
        let cleanupUseCase: CleanupTranscriptionUseCase
        let diarizeUseCase: DiarizeMeetingUseCase
        let summarizeUseCase: SummarizeMeetingUseCase
        let exportUseCase: ExportAudioUseCase
        let streamingUseCase: StreamingTranscriptionUseCase
        let liveTranscriptionVM: LiveTranscriptionViewModel
        let liveTranslateUseCase: LiveTranslateUseCase
        /// The primary transcription engine; passed to PipelineCoordinator for memory-gate unload.
        let primaryEngine: any TranscriptionEngine
        /// The summarization engine; shared with RepairTranscriptUseCase to avoid duplicate model loads.
        let summarizationEngine: any SummarizationEngine
        /// Stored handle for the background prewarm task.
        /// AppAssembler holds Built for the app lifetime, so this task can be
        /// cancelled on teardown by calling prewarmTask.cancel().
        let prewarmTask: Task<Void, Never>
        /// Connects a delegate to receive model-download progress from every
        /// download-capable engine in this stack (primary + cleanup). Wired by
        /// AppAssemblerBuilders.buildMenuBarVM once MenuBarViewModel exists,
        /// since MenuBarViewModel is constructed after Built (#212).
        let connectDownloadDelegate: @Sendable (any ModelDownloadDelegate) async -> Void
    }

    private func createPrewarmTask(
        summarizeUseCase: SummarizeMeetingUseCase,
        primaryEngine: any TranscriptionEngine,
    ) -> Task<Void, Never> {
        let logger = self.logger
        return Task.detached(priority: .background) {
            do {
                try await summarizeUseCase.prewarm()
            } catch {
                logger.warning("Summarization prewarm failed (non-fatal): \(error, privacy: .private)")
            }
            do {
                try await primaryEngine.loadModel(ModelIDs.parakeetPrimary)
            } catch {
                logger.warning("Primary model pre-load failed (non-fatal): \(error, privacy: .private)")
            }
        }
    }

    func build(
        storage: GRDBStorageActor,
        audioCapture: CoreAudioTapCaptureActor,
        config: AppConfig,
    ) -> Built {
        let telemetry = InferenceTelemetry()
        // Keep concrete references (not yet erased to `any TranscriptionEngine`) so
        // connectDownloadDelegate can call each plugin's own setDownloadDelegate — that
        // setter isn't part of the TranscriptionEngine protocol (#212).
        let parakeetPrimary: ParakeetPlugin?
        let whisperKitPrimary: WhisperKitPlugin?
        let primaryEngine: any TranscriptionEngine
        switch config.transcription.defaultEngine {
        case .parakeet:
            let plugin = ParakeetPlugin()
            parakeetPrimary = plugin
            whisperKitPrimary = nil
            primaryEngine = plugin
        case .whisperkit:
            let plugin = WhisperKitPlugin()
            parakeetPrimary = nil
            whisperKitPrimary = plugin
            primaryEngine = plugin
        }
        let cleanupEngine = WhisperKitPlugin()
        let sampleLoader = AudioFileLoader()
        let diarization = FluidDiarizationPlugin()
        let summarizationEngine: any SummarizationEngine = MLXSummarizationPlugin()
        let summarizeUseCase = SummarizeMeetingUseCase(
            summarization: summarizationEngine,
            config: config.summarization,
            storage: storage,
        )
        let prewarmTask = createPrewarmTask(summarizeUseCase: summarizeUseCase, primaryEngine: primaryEngine)
        return Built(
            stopUseCase: StopAndTranscribeUseCase(
                audioCapture: audioCapture, transcription: primaryEngine,
                storage: storage, sampleLoader: sampleLoader,
                modelId: ModelIDs.parakeetPrimary, telemetry: telemetry,
            ),
            cleanupUseCase: CleanupTranscriptionUseCase(
                transcription: cleanupEngine, sampleLoader: sampleLoader,
                reader: storage, transcriptReader: storage, writer: storage, telemetry: telemetry,
            ),
            diarizeUseCase: DiarizeMeetingUseCase(
                diarization: diarization, sampleLoader: sampleLoader, reader: storage, writer: storage,
            ),
            summarizeUseCase: summarizeUseCase,
            exportUseCase: ExportAudioUseCase(storage: storage, exportEngine: AVFoundationExporter()),
            streamingUseCase: StreamingTranscriptionUseCase(transcription: primaryEngine),
            liveTranscriptionVM: LiveTranscriptionViewModel(),
            liveTranslateUseCase: LiveTranslateUseCase(translation: AppleTranslationPlugin()),
            primaryEngine: primaryEngine,
            summarizationEngine: summarizationEngine,
            prewarmTask: prewarmTask,
            connectDownloadDelegate: { delegate in
                await parakeetPrimary?.setDownloadDelegate(delegate)
                await whisperKitPrimary?.setDownloadDelegate(delegate)
                await cleanupEngine.setDownloadDelegate(delegate)
            },
        )
    }
}

