import Foundation
import Logging
import Domain
import Business
import AudioInfrastructure
import MLInfrastructure
import StorageInfrastructure
import Presentation

/// Builds the transcription, diarization, summarization, and export stack.
///
/// Pure struct with no stored state — call `build(storage:audioCapture:config:)` once per assembly.
@MainActor
struct TranscriptionSubAssembler {
    private let logger = AppLogger.for(category: "TranscriptionSubAssembler")
    struct Built {
        let stopUseCase: StopAndTranscribeUseCase
        let cleanupUseCase: CleanupTranscriptionUseCase
        let diarizeUseCase: DiarizeMeetingUseCase
        let summarizeUseCase: SummarizeMeetingUseCase
        let exportUseCase: ExportAudioUseCase
        let streamingUseCase: StreamingTranscriptionUseCase
        let liveTranscriptionVM: LiveTranscriptionViewModel
        let liveTranslateUseCase: LiveTranslateUseCase
        /// The primary transcription engine; passed to PipelineCoordinator for memory-gate unload.
        let primaryEngine: any TranscriptionEngine
        /// The summarization engine; shared with RepairTranscriptUseCase to avoid duplicate model loads.
        let summarizationEngine: any SummarizationEngine
        /// Stored handle for the background prewarm task.
        /// AppAssembler holds Built for the app lifetime, so this task can be
        /// cancelled on teardown by calling prewarmTask.cancel().
        let prewarmTask: Task<Void, Never>
        /// Connects a delegate to receive model-download progress from every
        /// download-capable engine in this stack (primary + cleanup). Wired by
        /// AppAssemblerBuilders.buildMenuBarVM once MenuBarViewModel exists,
        /// since MenuBarViewModel is constructed after Built (#212).
        let connectDownloadDelegate: @Sendable (any ModelDownloadDelegate) async -> Void
    }

    private func createPrewarmTask(
        summarizeUseCase: SummarizeMeetingUseCase,
        primaryEngine: any TranscriptionEngine,
    ) -> Task<Void, Never> {
        let logger = self.logger
        return Task.detached(priority: .background) {
            do {
                try await summarizeUseCase.prewarm()
            } catch {
                logger.warning("Summarization prewarm failed (non-fatal): \(error, privacy: .private)")
            }
            do {
                try await primaryEngine.loadModel(ModelIDs.parakeetPrimary)
            } catch {
                logger.warning("Primary model pre-load failed (non-fatal): \(error, privacy: .private)")
            }
        }
    }

    func build(
        storage: GRDBStorageActor,
        audioCapture: CoreAudioTapCaptureActor,
        config: AppConfig,
    ) -> Built {
        let telemetry = InferenceTelemetry()
        // Keep concrete references (not yet erased to `any TranscriptionEngine`) so
        // connectDownloadDelegate can call each plugin's own setDownloadDelegate — that
        // setter isn't part of the TranscriptionEngine protocol (#212).
        let parakeetPrimary: ParakeetPlugin?
        let whisperKitPrimary: WhisperKitPlugin?
        let primaryEngine: any TranscriptionEngine
        switch config.transcription.defaultEngine {
        case .parakeet:
            let plugin = ParakeetPlugin()
            parakeetPrimary = plugin
            whisperKitPrimary = nil
            primaryEngine = plugin
        case .whisperkit:
            let plugin = WhisperKitPlugin()
            parakeetPrimary = nil
            whisperKitPrimary = plugin
            primaryEngine = plugin
        }
        let cleanupEngine = WhisperKitPlugin()
        let sampleLoader = AudioFileLoader()
        let diarization = FluidDiarizationPlugin()
        let summarizationEngine: any SummarizationEngine = MLXSummarizationPlugin()
        let summarizeUseCase = SummarizeMeetingUseCase(
            summarization: summarizationEngine,
            config: config.summarization,
            storage: storage,
        )
        let prewarmTask = createPrewarmTask(summarizeUseCase: summarizeUseCase, primaryEngine: primaryEngine)
        return Built(
            stopUseCase: StopAndTranscribeUseCase(
                audioCapture: audioCapture, transcription: primaryEngine,
                storage: storage, sampleLoader: sampleLoader,
                modelId: ModelIDs.parakeetPrimary, telemetry: telemetry,
            ),
            cleanupUseCase: CleanupTranscriptionUseCase(
                transcription: cleanupEngine, sampleLoader: sampleLoader,
                reader: storage, transcriptReader: storage, writer: storage, telemetry: telemetry,
            ),
            diarizeUseCase: DiarizeMeetingUseCase(
                diarization: diarization, sampleLoader: sampleLoader, reader: storage, writer: storage,
            ),
            summarizeUseCase: summarizeUseCase,
            exportUseCase: ExportAudioUseCase(storage: storage, exportEngine: AVFoundationExporter()),
            streamingUseCase: StreamingTranscriptionUseCase(transcription: primaryEngine),
            liveTranscriptionVM: LiveTranscriptionViewModel(),
            liveTranslateUseCase: LiveTranslateUseCase(translation: AppleTranslationPlugin()),
            primaryEngine: primaryEngine,
            summarizationEngine: summarizationEngine,
            prewarmTask: prewarmTask,
            connectDownloadDelegate: { delegate in
                await parakeetPrimary?.setDownloadDelegate(delegate)
                await whisperKitPrimary?.setDownloadDelegate(delegate)
                await cleanupEngine.setDownloadDelegate(delegate)
            },
        )
    }
}

