import Foundation

/// Abstracts reading PCM audio samples from a file URL so the domain layer
/// has no compile-time dependency on AVFoundation, AudioToolbox, or any other
/// audio I/O framework.
///
/// Conforming types are expected to be actors or otherwise internally
/// thread-safe; the `Sendable` requirement enforces that instances can cross
/// concurrency boundaries without data races under Swift strict concurrency.
public protocol AudioSampleLoader: Sendable {
    // MARK: - Loading

    /// Reads and decodes the audio file at `url`, returning its samples as
    /// mono, 16 kHz, 32-bit float PCM data.
    ///
    /// Implementations are responsible for any format conversion (sample-rate
    /// resampling, channel down-mixing, bit-depth normalisation) required to
    /// produce the canonical representation consumed by ``TranscriptionEngine``.
    ///
    /// - Parameter url: A file URL pointing to a supported audio file (e.g.
    ///   WAV, AIFF, M4A, MP3).
    /// - Returns: A flat array of interleaved 32-bit float PCM samples
    ///   normalised to the range `[-1.0, 1.0]`.
    /// - Throws: A domain error if the file cannot be opened, decoded, or
    ///   converted to the required format.
    func loadSamples(from url: URL) async throws -> [Float]
}
