    func listRecordings(limit: Int?, offset: Int?) async throws -> [RecordingSummary]
    func totalStorageSize() async throws -> Int64
    func listPendingSessions() async throws -> [RecordingID]
    func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata]
    /// Returns IDs of recordings whose transcription failed and need a retry (#116).
    ///
    /// A recording enters this state when `markNeedsRetranscription(id:audioURL:)` was
    /// called by `StopAndTranscribeUseCase` after a WhisperKit/MLX crash, and has not
    /// yet been successfully re-transcribed.
    ///
    /// - Returns: An array of ``RecordingID`` values for crash-recoverable sessions, oldest-first.
    func listNeedsRetranscription() async throws -> [RecordingID]
}

extension RecordingReadRepository {
    public func listRecordings() async throws -> [RecordingSummary] {
        return try await listRecordings(limit: nil, offset: nil)
    }
}

/// Capability protocol for persisting audio recording metadata.
public protocol RecordingWriteRepository: Sendable {
    func saveRecording(_ file: AudioFile) async throws -> StoredRecording
    func deleteRecording(id: RecordingID) async throws
    func markSessionStarted(id: RecordingID, startedAt: Date) async throws
    /// Attaches the AEC-cleaned microphone WAV path to an existing recording row.
    /// A no-op when `path` is nil. Idempotent — safe to call more than once (IDEM-002).
    func updateCleanedMicPath(id: RecordingID, path: URL?) async throws
    /// Marks a stored recording as needing re-transcription after a WhisperKit/MLX crash (#116).
    ///
    /// Called by `StopAndTranscribeUseCase` when transcription fails after the audio was already
    /// saved to storage. The WAV at `audioURL` is retained on disk so the session can be retried
    /// on next app launch via `RecoverPendingSessionsUseCase`.
    ///
    /// - Parameters:
    ///   - id: The stable identifier of the recording to mark.
    ///   - audioURL: The on-disk URL of the preserved WAV file.
    func markNeedsRetranscription(id: RecordingID, audioURL: URL) async throws
    func importMetadata(_ metadata: RecordingMetadata) async throws
}

public typealias RecordingRepository = RecordingReadRepository & RecordingWriteRepository
import Foundation

/// Capability protocol for persisting and retrieving audio recording metadata.
///
/// Consumed by the recording, transcription, and summarization use cases that need
/// to store or look up meeting recordings. The canonical conforming type is
/// the persistent storage backend.
public protocol RecordingRepository: Sendable {
    /// Persists an audio file and its associated metadata.
    ///
    /// - Parameter file: The completed audio file to store, including its on-disk URL and capture metadata.
    /// - Returns: A ``StoredRecording`` representing the newly persisted record.
    /// - Throws: A storage error if the underlying persistence layer fails to write the record.
    func saveRecording(_ file: AudioFile) async throws -> StoredRecording

    /// Fetches a single recording by its unique identifier.
    ///
    /// - Parameter id: The stable, opaque identifier of the recording to retrieve.
    /// - Returns: The ``StoredRecording`` associated with `id`.
    /// - Throws: ``RecordingNotFoundError`` if no recording exists for `id`;
    ///   a storage error for any other persistence failure.
    func getRecording(id: RecordingID) async throws -> StoredRecording

    /// Returns all recordings, sorted by creation date descending (newest first).
    ///
    /// An empty array signals that no recordings exist; this method does not throw
    /// to indicate an empty collection.
    /// - Returns: An array of ``RecordingSummary`` values ordered newest-first,
    ///   or an empty array if no recordings have been saved.
    /// - Throws: A storage error if the underlying persistence layer cannot be queried.
    func listRecordings(limit: Int?, offset: Int?) async throws -> [RecordingSummary]

    /// Removes the recording with the given identifier.
    ///
    /// This operation is **not** idempotent — attempting to delete a recording that
    /// does not exist throws ``RecordingNotFoundError`` rather than succeeding silently.
    /// - Parameter id: The stable, opaque identifier of the recording to delete.
    /// - Throws: ``RecordingNotFoundError`` if no recording exists for `id`;
    ///   a storage error for any other persistence failure.
    func deleteRecording(id: RecordingID) async throws

    /// Returns the total disk space consumed by all stored recordings, in bytes.
    ///
    /// Counts only audio files tracked by this repository; temporary files and
    /// WAV debug dumps are excluded.
    /// - Returns: The aggregate file size in bytes (`Int64`).
    /// - Throws: A storage error if the size cannot be computed.
    func totalStorageSize() async throws -> Int64

    /// Persists a pending session stub at recording start so a crash mid-recording
    /// leaves a recoverable row in storage (#161).
    ///
    /// Called by `StartRecordingUseCase` immediately after audio capture begins.
    /// The stub uses placeholder values for fields that aren't known until stop().
    /// Calling `saveRecording(_:)` with the same ID later overwrites the stub.
    ///
    /// - Parameters:
    ///   - id: The session ID, matching the `RecordingSession.id` created by the use case.
    ///   - startedAt: Wall-clock time when recording began.
    /// - Throws: A storage error if the underlying persistence layer fails.
    func markSessionStarted(id: RecordingID, startedAt: Date) async throws

    /// Returns the IDs of all sessions that were started but never completed (#161 recovery flow).
    ///
    /// A pending session is one where `markSessionStarted(id:startedAt:)` was called
    /// but `saveRecording(_:)` was never called (e.g. the app crashed mid-recording).
    /// Called once at app launch to surface crash-recovery candidates to the user.
    ///
    /// - Returns: An array of ``RecordingID`` values for incomplete sessions, oldest-first.
    /// - Throws: A storage error if the underlying persistence layer cannot be queried.
    func listPendingSessions() async throws -> [RecordingID]

    /// Returns full metadata for all recordings in a single storage call, sorted
    /// newest-first.
    ///
    /// Prefer this over listRecordings() + N x getRecording(id:) when the caller
    /// needs the complete RecordingMetadata for every recording. One round-trip
    /// to the persistence layer replaces N+1 serial calls.
    ///
    /// - Returns: An array of RecordingMetadata ordered newest-first.
    /// - Throws: A storage error if the underlying persistence layer cannot be queried.
    func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata]
}

public extension RecordingRepository {
    /// Convenience overload: full unbounded listing (protocols cannot declare default arguments).
    func listRecordings() async throws -> [RecordingSummary] {
        try await listRecordings(limit: nil, offset: nil)
    }
}
