import Domain
import Foundation
@testable import Presentation
import Testing

// RED: SettingsViewModelDeleteAllTests
// Issue #123 — Uninstall / data cleanup: Delete All Data + reset
//
// These tests call properties and methods that do not yet exist on
// SettingsViewModel. They must fail to compile (RED stage) until the
// GREEN agent adds the corresponding API surface.

// MARK: - Mock DataEraser

/// Minimal mock for the DataEraser protocol (does not exist yet — RED trigger).
/// The GREEN agent must declare `DataEraser` in Domain or Presentation.
private final class MockDataEraser: DataEraser, @unchecked Sendable {
    private(set) var erasedAll = false
    private(set) var deletedLog: [String] = []

    func eraseAllData() async throws -> [String] {
        erasedAll = true
        deletedLog = [
            "DuckDB database",
            "WAV recordings",
            "Transcripts",
            "ML model cache",
            "Keychain entries",
            "UserDefaults",
        ]
        return deletedLog
    }
}

/// Eraser that throws to simulate partial-failure scenarios.
private final class FailingDataEraser: DataEraser, @unchecked Sendable {
    func eraseAllData() async throws -> [String] {
        throw DataEraseError.partialFailure(paths: ["DuckDB database"])
    }
}

// MARK: - SettingsViewModel DeleteAll Tests

@Suite("SettingsViewModel — Delete All Data (#123)", .serialized)
@MainActor
struct SettingsViewModelDeleteAllTests {

    // MARK: AC1 — "Delete All Data" button state

    @Test("AC1a: deleteAllConfirmationText defaults to empty string")
    func confirmationTextDefaultsToEmpty() {
        let vm = SettingsViewModel()
        #expect(vm.deleteAllConfirmationText == "")
    }

    @Test("AC1b: isDeleteAllConfirmed is false when confirmationText is empty")
    func isNotConfirmedWhenTextIsEmpty() {
        let vm = SettingsViewModel()
        #expect(vm.isDeleteAllConfirmed == false)
    }

    @Test("AC1c: isDeleteAllConfirmed is false when confirmationText is incorrect")
    func isNotConfirmedWhenTextIsWrong() {
        let vm = SettingsViewModel()
        vm.deleteAllConfirmationText = "delete"
        #expect(vm.isDeleteAllConfirmed == false, "Case-sensitive match required")
        vm.deleteAllConfirmationText = "DELETE "
        #expect(vm.isDeleteAllConfirmed == false, "Trailing whitespace must not match")
        vm.deleteAllConfirmationText = "DELET"
        #expect(vm.isDeleteAllConfirmed == false, "Partial match must not be accepted")
    }

    @Test("AC1d: isDeleteAllConfirmed is true only when confirmationText is exactly 'DELETE'")
    func isConfirmedOnlyWhenTextIsExactlyDELETE() {
        let vm = SettingsViewModel()
        vm.deleteAllConfirmationText = "DELETE"
        #expect(vm.isDeleteAllConfirmed == true)
    }

    // MARK: AC2 — disabled while recording in progress

    @Test("AC2a: isDeleteAllDataEnabled is true when no recording is in progress")
    func deleteAllEnabledWhenNotRecording() {
        let vm = SettingsViewModel()
        #expect(vm.isDeleteAllDataEnabled == true)
    }

    @Test("AC2b: isDeleteAllDataEnabled is false when a recording is active")
    func deleteAllDisabledWhileRecording() {
        let vm = SettingsViewModel()
        vm.isRecordingActive = true
        #expect(vm.isDeleteAllDataEnabled == false)
    }

    @Test("AC2c: isDeleteAllDataEnabled re-enables when recording stops")
    func deleteAllReEnablesAfterRecordingStops() {
        let vm = SettingsViewModel()
        vm.isRecordingActive = true
        #expect(vm.isDeleteAllDataEnabled == false)
        vm.isRecordingActive = false
        #expect(vm.isDeleteAllDataEnabled == true)
    }

    // MARK: AC3 — isDeletingAllData progress state

    @Test("AC3a: isDeletingAllData is false initially")
    func isDeletingAllDataIsFalseInitially() {
        let vm = SettingsViewModel()
        #expect(vm.isDeletingAllData == false)
    }

    // MARK: AC4 — performDeleteAllData orchestration

    @Test("AC4a: performDeleteAllData calls eraseAllData on the injected eraser")
    func performDeleteAllDataCallsEraser() async throws {
        let eraser = MockDataEraser()
        let vm = SettingsViewModel()
        vm.deleteAllConfirmationText = "DELETE"
        try await vm.performDeleteAllData(dataEraser: eraser)
        #expect(eraser.erasedAll == true)
    }

    @Test("AC4b: performDeleteAllData is a no-op when isDeleteAllConfirmed is false")
    func performDeleteAllDataNoOpWhenNotConfirmed() async throws {
        let eraser = MockDataEraser()
        let vm = SettingsViewModel()
        vm.deleteAllConfirmationText = "delete"  // wrong case
        try await vm.performDeleteAllData(dataEraser: eraser)
        #expect(eraser.erasedAll == false, "Must not erase without correct confirmation")
    }

    @Test("AC4c: performDeleteAllData sets isDeletingAllData to false after completion")
    func isDeletingAllDataFalseAfterCompletion() async throws {
        let eraser = MockDataEraser()
        let vm = SettingsViewModel()
        vm.deleteAllConfirmationText = "DELETE"
        try await vm.performDeleteAllData(dataEraser: eraser)
        #expect(vm.isDeletingAllData == false)
    }

    @Test("AC4d: performDeleteAllData populates deleteAllDataLog on success")
    func deleteAllDataLogPopulatedOnSuccess() async throws {
        let eraser = MockDataEraser()
        let vm = SettingsViewModel()
        vm.deleteAllConfirmationText = "DELETE"
        try await vm.performDeleteAllData(dataEraser: eraser)
        #expect(vm.deleteAllDataLog.isEmpty == false, "Log must record what was deleted")
        #expect(vm.deleteAllDataLog.contains("DuckDB database"))
    }

    @Test("AC4e: performDeleteAllData resets confirmationText to empty after run")
    func confirmationTextClearedAfterDeletion() async throws {
        let eraser = MockDataEraser()
        let vm = SettingsViewModel()
        vm.deleteAllConfirmationText = "DELETE"
        try await vm.performDeleteAllData(dataEraser: eraser)
        #expect(vm.deleteAllConfirmationText == "")
    }

    @Test("AC4f: performDeleteAllData propagates errors from the eraser")
    func performDeleteAllDataPropagatesEraserError() async {
        let eraser = FailingDataEraser()
        let vm = SettingsViewModel()
        vm.deleteAllConfirmationText = "DELETE"
        do {
            try await vm.performDeleteAllData(dataEraser: eraser)
            Issue.record("Expected performDeleteAllData to throw but it did not")
        } catch {
            // expected — FailingDataEraser throws DataEraseError.partialFailure
        }
    }

    @Test("AC4g: performDeleteAllData is no-op when isDeleteAllDataEnabled is false (recording active)")
    func performDeleteAllDataNoOpWhileRecording() async throws {
        let eraser = MockDataEraser()
        let vm = SettingsViewModel()
        vm.deleteAllConfirmationText = "DELETE"
        vm.isRecordingActive = true
        try await vm.performDeleteAllData(dataEraser: eraser)
        #expect(eraser.erasedAll == false, "Must not erase while recording is in progress")
    }

    // MARK: AC5 — source inspection: SettingsView exposes "Delete All Data" section

    private static let generalTabSource: String = {
        let path = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent() // Presentation/
            .deletingLastPathComponent() // Unit/
            .deletingLastPathComponent() // Tests/
            .deletingLastPathComponent() // Record-Presentation/
            .appendingPathComponent("Sources/Presentation/Views/SettingsViewGeneralTab.swift")
        return (try? String(contentsOf: path, encoding: .utf8)) ?? ""
    }()

    @Test("AC5a: SettingsViewGeneralTab contains a 'Delete All Data' button or section")
    func settingsViewHasDeleteAllDataButton() {
        #expect(
            Self.generalTabSource.contains("Delete All Data"),
            "SettingsViewGeneralTab must contain a 'Delete All Data' control"
        )
    }

    @Test("AC5b: SettingsViewGeneralTab binds to deleteAllConfirmationText")
    func settingsViewBindsConfirmationText() {
        #expect(
            Self.generalTabSource.contains("deleteAllConfirmationText"),
            "SettingsViewGeneralTab must bind to viewModel.deleteAllConfirmationText"
        )
    }
}

// MARK: - DataEraser Protocol Tests (verify protocol surface)

@Suite("DataEraser protocol (#123)", .serialized)
struct DataEraserProtocolTests {

    @Test("DataEraseError.partialFailure carries failed paths")
    func partialFailureCarriesPaths() {
        let error = DataEraseError.partialFailure(paths: ["DuckDB database", "Keychain"])
        guard case .partialFailure(let paths) = error else {
            Issue.record("Expected partialFailure case")
            return
        }
        #expect(paths.count == 2)
        #expect(paths.contains("DuckDB database"))
        #expect(paths.contains("Keychain"))
    }
}

