        if let error = errorToThrow { throw error }
        if let existing = store[id] {
            let updated = RecordingMetadata(
                id: existing.metadata.id,
                recordedAt: existing.metadata.recordedAt,
                duration: existing.metadata.duration,
                fileSize: existing.metadata.fileSize,
                audioURL: existing.metadata.audioURL,
                transcriptURL: existing.metadata.transcriptURL,
                modelId: existing.metadata.modelId,
                processingTime: existing.metadata.processingTime,
                computeUnit: existing.metadata.computeUnit,
                wordCount: existing.metadata.wordCount,
                speakerCount: existing.metadata.speakerCount,
                diarizationTime: existing.metadata.diarizationTime,
                cleanedMicAudioPath: path
            )
            store[id] = StoredRecording(metadata: updated, transcript: existing.transcript)
        }
    }

    public func saveRecording(_ file: AudioFile) async throws -> StoredRecording {
        saveRecordingCalled = true
        saveRecordingCallCount += 1
        if let error = errorToThrow { throw error }
        if let mock = mockStoredRecording { return mock }
        let meta = RecordingMetadata(
            id: file.id,
