        if let error = errorToThrow { throw error }
        let all = mockRecordings.isEmpty ? Array(store.values) : mockRecordings
        return all.map(\.metadata).sorted { $0.recordedAt > $1.recordedAt }
    }

    public func listRecordings(limit: Int? = nil, offset: Int? = nil) async throws -> [RecordingSummary] {
