        if let error = errorToThrow { throw error }
        let all = mockRecordings.isEmpty ? Array(store.values) : mockRecordings
        return all.map {
            RecordingSummary(
                id: $0.metadata.id,
                date: $0.metadata.recordedAt,
                duration: $0.metadata.duration,
                wordCount: $0.metadata.wordCount,
            )
        }
    }

    public func listPendingSessions() async throws -> [RecordingID] {
        []
    }

    // MARK: - Crash Resilience (AC-1..AC-4 / #116)

    private var needsRetranscriptionStore: [RecordingID: URL] = [:]

    public func markNeedsRetranscription(id: RecordingID, audioURL: URL) async throws {
        markNeedsRetranscriptionCalled = true
        markNeedsRetranscriptionCallCount += 1
        if let error = errorToThrow { throw error }
        needsRetranscriptionStore[id] = audioURL
    }

    public var importMetadataCalled = false

