    public func seedNeedsRetranscription(id: RecordingID, audioURL: URL) {
        needsRetranscriptionStore[id] = audioURL
    }

    public func deleteRecording(id: RecordingID) async throws {
        deleteRecordingCalled = true
        deleteRecordingCallCount += 1
        if let error = errorToThrow { throw error }
        guard store[id] != nil || mockRecordings.contains(where: { $0.metadata.id == id }) else {
            throw StorageError.recordingNotFound(id: id)
        }
        store.removeValue(forKey: id)
        mockRecordings.removeAll { $0.metadata.id == id }
    }

    public func totalStorageSize() async throws -> Int64 {
        totalStorageSizeCalled = true
        if let error = errorToThrow { throw error }
        return mockTotalSize
    }

    // MARK: - TranscriptRepository

    public func updateTranscript(id: RecordingID, transcript: TranscriptionResult) async throws {
