            store[id] = StoredRecording(metadata: mock.metadata, transcript: transcript)
        } else {
            throw StorageError.recordingNotFound(id: id)
        }
    }

    public func searchTranscripts(query: String, limit: Int? = nil, offset: Int? = nil) async throws -> [RecordingSummary] {
        searchTranscriptsCalled = true
        if let error = errorToThrow { throw error }
        return store.values.compactMap { stored in
            guard stored.transcript?.fullText.localizedCaseInsensitiveContains(query) == true
            else { return nil }
            return RecordingSummary(
                id: stored.metadata.id,
                date: stored.metadata.recordedAt,
                duration: stored.metadata.duration,
                wordCount: stored.metadata.wordCount,
            )
        }
    }

    public func saveDraftTranscript(draftText: String, for id: RecordingID) async throws {
        saveDraftTranscriptCalled = true
        if let error = errorToThrow { throw error }
        draftStore[id] = draftText
    }

    public func getTranscriptDraft(for id: RecordingID) async throws -> String? {
        getTranscriptDraftCalled = true
        if let error = errorToThrow { throw error }
        return draftStore[id]
    }

    // MARK: - DiarizationRepository

    public func attachDiarization(id: RecordingID, diarization: DiarizedTranscript) async throws {
        attachDiarizationCalled = true
        if let error = errorToThrow { throw error }
        guard store[id] != nil || mockStoredRecording != nil else {
            throw StorageError.recordingNotFound(id: id)
        }
        diarizations[id] = diarization
    }

    // MARK: - SummaryRepository

    public var saveSummaryCalled = false
    public var saveSummaryCallCount = 0
    public var savedSummaries: [RecordingID: MeetingSummary] = [:]
    public var getSummaryCalled = false

    public func saveSummary(for recordingId: RecordingID, summary: MeetingSummary) async throws {
        saveSummaryCalled = true
        saveSummaryCallCount += 1
        if let error = errorToThrow { throw error }
        savedSummaries[recordingId] = summary
    }

    public func getSummary(for recordingId: RecordingID) async throws -> MeetingSummary? {
        getSummaryCalled = true
        if let error = errorToThrow { throw error }
        return savedSummaries[recordingId]
    }

    // MARK: - NotesRepository

    public var savedNotes: [RecordingID: String] = [:]

    public func saveNotes(meetingId: RecordingID, text: String) async throws {
        if let error = errorToThrow { throw error }
        savedNotes[meetingId] = text
    }

    public func getNotes(meetingId: RecordingID) async throws -> String {
        if let error = errorToThrow { throw error }
        return savedNotes[meetingId] ?? ""
    }

    // MARK: - Test Helpers

    public func setErrorToThrow(_ error: Error?) {
        errorToThrow = error
    }

    public func setMockStoredRecording(_ recording: StoredRecording) {
        mockStoredRecording = recording
    }

    public func seedRecording(_ recording: StoredRecording) {
        store[recording.metadata.id] = recording
    }

    public func setMockRecordings(_ recordings: [StoredRecording]) {
        mockRecordings = recordings
    }

    public func setMockTotalSize(_ size: Int64) {
        mockTotalSize = size
    }
}

public enum MockStorageEngineError: Error {
    case notFound
