import Foundation

/// A transcribed segment attributed to a single speaker.
///
/// Combines the spoken text from a transcription pass with the speaker
/// identity and time boundaries from the diarization pipeline.
public struct DiarizedSegment: Sendable, Identifiable {
    public var id: String {
        "\(speakerId)-\(startTime)"
    }

    /// The transcribed text for this segment.
    public let text: String

    /// Stable identifier for the attributed speaker (e.g. "speaker-0").
    public let speakerId: SpeakerID

    /// Start time of the segment relative to the audio stream origin, in seconds.
    public let startTime: TimeInterval

    /// End time of the segment relative to the audio stream origin, in seconds.
    public let endTime: TimeInterval

    /// Combined diarization and transcription confidence in the range [0, 1].
    public let confidence: Double

    /// Word-level timing information for each word in this segment.
    ///
    /// `nil` when the transcription engine did not produce word-level timestamps.
    public let wordTimings: [WordTimestamp]?

    public init(
        text: String,
        speakerId: SpeakerID,
        startTime: TimeInterval,
        endTime: TimeInterval,
        confidence: Double,
        wordTimings: [WordTimestamp]? = nil
    ) {
        self.text = text
        self.speakerId = speakerId
        self.startTime = startTime
        self.endTime = endTime
        self.confidence = confidence
        self.wordTimings = wordTimings
    }
}

/// The complete diarized transcript for a single recording.
///
/// Aggregates all ``DiarizedSegment`` values produced by aligning the
/// transcription output with the diarization pipeline, along with summary
/// metadata about the run.
public struct DiarizedTranscript: Sendable {
    /// Ordered segments that make up this transcript, each attributed to a speaker.
    public let segments: [DiarizedSegment]

    /// Number of distinct speakers identified in this transcript.
    public let speakerCount: Int

    /// Wall-clock time in seconds taken to produce the diarized transcript.
    public let processingTime: TimeInterval

    public init(
        segments: [DiarizedSegment],
        speakerCount: Int,
        processingTime: TimeInterval
    ) {
        self.segments = segments
        self.speakerCount = speakerCount
        self.processingTime = processingTime
    }
}

