import Business
import Domain
import Foundation

// MARK: - Speaker profiles + audio device config

extension SettingsViewModel {
    public func loadProfiles() async {
        guard let store = profileStore else { return }
        do {
            speakerProfiles = try await store.allProfiles()
        } catch {
            errorMessage = "Failed to load speaker profiles"
        }
    }

    public func deleteProfile(id: SpeakerID) async {
        guard let store = profileStore else { return }
        do {
            try await store.delete(id: id)
            speakerProfiles.removeAll { $0.id == id }
        } catch {
            errorMessage = "Failed to delete profile"
        }
    }

    /// Enrolls a new speaker profile from a diarized recording — collects that
    /// speaker's segments' audio and hands it to `EnrollSpeakerUseCase`.
    public func enrollSpeaker(fromRecording recordingId: RecordingID, speakerId: SpeakerID, name: String) async {
        guard let enrollSpeaker, let audioSampleLoader, let diarizationReader, let recordingReadRepository else {
            return
        }
        do {
            let recording = try await recordingReadRepository.getRecording(id: recordingId)
            let segments = try await diarizationReader.getSegments(id: recordingId)
            let matching = segments.filter { $0.speakerId == speakerId }
            let allSamples = try await audioSampleLoader.loadSamples(from: recording.metadata.audioURL)

            var collected: [Float] = []
            for segment in matching {
                let start = Int(segment.startTime * 16000)
                let end = min(Int(segment.endTime * 16000), allSamples.count)
                guard end > start else { continue }
                collected.append(contentsOf: allSamples[start ..< end])
            }

            _ = try await enrollSpeaker.enroll(name: name, samples: collected)
            await loadProfiles()
        } catch let error as SpeakerError {
            switch error {
            case .invalidName: errorMessage = "Speaker name cannot be empty"
            case .insufficientAudio: errorMessage = "Not enough audio to enroll this speaker"
            case .duplicateName: errorMessage = "A speaker with that name already exists"
            case .profileNotFound, .noMatch: errorMessage = "Failed to enroll speaker"
            }
        } catch {
            errorMessage = "Failed to enroll speaker"
        }
    }

