     )

     if let matchSpeakers {
         diarizedTranscript = try await matchSpeakers.labelDiarization(
             diarizedTranscript, audioSamples: samples, sampleRate: 16000,
         )
     }

     try await writer.attachDiarization(id: recordingId, diarization: diarizedTranscript)
     ```
