    // Dependencies (not `private`: SettingsViewModelTheme.swift needs access)
    let appState: AppState?
    let profileStore: (any SpeakerProfileStore)?
    let audioDeviceConfigStore: (any AudioDeviceConfigStore)?
    let deviceEnumeration: (any AudioDeviceEnumeration)?
    let recordingReadRepository: (any RecordingReadRepository)?
    let diskSpaceMonitor: (any DiskSpaceMonitor)?
    let integrationSettingsStore: (any IntegrationSettingsStore)?
    // #300: enrolling a speaker from an existing recording's diarized segments.
    let diarizationReader: (any DiarizationReadRepository)?
    let enrollSpeaker: EnrollSpeakerUseCase?
    let audioSampleLoader: (any AudioSampleLoader)?

    public init(
        appState: AppState? = nil,
        profileStore: (any SpeakerProfileStore)? = nil,
        audioDeviceConfigStore: (any AudioDeviceConfigStore)? = nil,
        deviceEnumeration: (any AudioDeviceEnumeration)? = nil,
        recordingReadRepository: (any RecordingReadRepository)? = nil,
        diskSpaceMonitor: (any DiskSpaceMonitor)? = nil,
        integrationSettingsStore: (any IntegrationSettingsStore)? = nil,
        diarizationReader: (any DiarizationReadRepository)? = nil,
        enrollSpeaker: EnrollSpeakerUseCase? = nil,
