import Business
import Domain
import Foundation
@testable import Presentation
import Testing
import TestMocks

// RED: SettingsViewModel.enrollSpeaker(fromRecording:speakerId:name:) does not exist yet.
// Issue #300 — speaker enrollment from an existing recording's diarized segments.

@Suite("SettingsViewModel speaker enrollment from recording (#300)", .serialized)
@MainActor
struct SettingsViewModelSpeakerEnrollmentTests {

    private func makeRecording(id: RecordingID) -> StoredRecording {
        StoredRecording(metadata: RecordingMetadata(
            id: id,
            recordedAt: Date(timeIntervalSince1970: 1_700_000_000),
            duration: 30.0,
            fileSize: 100,
            audioURL: URL(fileURLWithPath: "/recordings/\(id.rawValue).wav"),
            transcriptURL: nil,
            modelId: ModelID("openai_whisper-tiny"),
            processingTime: 1.0,
            computeUnit: .cpuAndNeuralEngine,
            wordCount: 0,
        ))
    }

    private func makeSegments(speakerId: SpeakerID) -> [DiarizedSegment] {
        [
            DiarizedSegment(text: "hello", speakerId: speakerId, startTime: 0, endTime: 1, confidence: 0.9),
            DiarizedSegment(
                text: "world", speakerId: SpeakerID("other-speaker"), startTime: 1, endTime: 2, confidence: 0.9,
            ),
        ]
    }

    @Test("AC1: enrolling from a recording's matching speaker segments creates a profile")
    func enrollFromRecordingCreatesProfile() async throws {
        let recordingId = RecordingID("recording-001")
        let speakerId = SpeakerID("speaker-0")

        let mockStorage = MockStorageEngine()
        await mockStorage.setMockStoredRecording(makeRecording(id: recordingId))
        await mockStorage.setMockDiarizedSegments(makeSegments(speakerId: speakerId))

        let sampleLoader = MockAudioSampleLoader()
        await sampleLoader.setMockSamples([Float](repeating: 0.5, count: 32000))

        let profileStore = MockSpeakerProfileStore()
        let embedding = MockVoiceEmbeddingEngine()
        let enrollSpeaker = EnrollSpeakerUseCase(store: profileStore, embedding: embedding)

        let vm = SettingsViewModel(
            recordingReadRepository: mockStorage,
            diarizationReader: mockStorage,
            enrollSpeaker: enrollSpeaker,
            audioSampleLoader: sampleLoader,
        )

        await vm.enrollSpeaker(fromRecording: recordingId, speakerId: speakerId, name: "Alice")

        let profiles = try await profileStore.allProfiles()
        #expect(profiles.count == 1)
        #expect(profiles.first?.name == "Alice")
        #expect(vm.errorMessage == nil)
    }

    @Test("AC2: insufficient audio for the matched speaker surfaces SpeakerError.insufficientAudio")
    func enrollWithInsufficientAudioSurfacesError() async throws {
        let recordingId = RecordingID("recording-002")
        let speakerId = SpeakerID("speaker-0")

        let mockStorage = MockStorageEngine()
        await mockStorage.setMockStoredRecording(makeRecording(id: recordingId))
        // Only 1s of matching-speaker audio (0-1s) — below the 16000-sample minimum.
        await mockStorage.setMockDiarizedSegments(makeSegments(speakerId: speakerId))

        let sampleLoader = MockAudioSampleLoader()
        await sampleLoader.setMockSamples([Float](repeating: 0.5, count: 16000))

        let profileStore = MockSpeakerProfileStore()
        let embedding = MockVoiceEmbeddingEngine()
        let enrollSpeaker = EnrollSpeakerUseCase(store: profileStore, embedding: embedding)

        let vm = SettingsViewModel(
            recordingReadRepository: mockStorage,
            diarizationReader: mockStorage,
            enrollSpeaker: enrollSpeaker,
            audioSampleLoader: sampleLoader,
        )

        await vm.enrollSpeaker(fromRecording: recordingId, speakerId: speakerId, name: "Bob")

        let profiles = try await profileStore.allProfiles()
        #expect(profiles.isEmpty)
        #expect(vm.errorMessage != nil)
    }

