import SwiftUI
import Utilities
import AppKit
import Domain
import Logging
import Business
import AudioInfrastructure
import MLInfrastructure
import Presentation

/// The top-level SwiftUI application entry point for THE RECORD.
@main
public struct TheRecordApp: App {
    /// The application delegate managing the status bar, popover, and composition root.
    @NSApplicationDelegateAdaptor(AppDelegate.self) public var appDelegate

    public init() {}

    public var body: some Scene {
        Window("THE RECORD", id: "main") {
            AppContentView(appDelegate: appDelegate)
                .environment(appDelegate.appState)
        }
        .commands {
            CommandGroup(after: .appInfo) {
                Button("Third-Party Licenses") {
                    if let url = Bundle.main.url(forResource: "ThirdPartyLicenses", withExtension: "txt") {
                        NSWorkspace.shared.open(url)
                    }
                }
            }
            CommandGroup(after: .newItem) {
                Button("New Meeting") {
                    Task { @MainActor in
                        await appDelegate.menuBarVM?.startRecordingTapped()
                    }
                }
                .keyboardShortcut("n", modifiers: .command)
                .disabled(appDelegate.menuBarVM?.isRecording == true)
                Divider()
                Button("Stop Recording") {
                    Task { @MainActor in
                        await appDelegate.menuBarVM?.stopRecordingTapped()
                    }
                }
                .keyboardShortcut(".", modifiers: .command)
                Divider()
                Button("Re-transcribe from Audio") {
                    Task { @MainActor in
                        if let id = appDelegate.menuBarVM?.cleanupRecordingId {
                            _ = await appDelegate.menuBarVM?.runCleanupPass(recordingId: id)
                        }
                    }
                }
                .keyboardShortcut("r", modifiers: [.command, .shift])
                .disabled(appDelegate.menuBarVM?.cleanupRecordingId == nil || appDelegate.menuBarVM?
                    .isRecording == true)
            }
        }
        Settings {
            if let appState = appDelegate.appState, let speakerProfileStore = appDelegate.speakerProfileStore {
                SettingsView(
                    viewModel: SettingsViewModel(
                        appState: appState,
                        profileStore: speakerProfileStore,
                        audioDeviceConfigStore: AudioDeviceConfigStoreImpl(configManager: appDelegate.sharedConfigManager),
                        deviceEnumeration: AudioDeviceEnumerator(),
                        diskSpaceMonitor: FileSystemDiskSpaceMonitor(),
                        integrationSettingsStore: LiveIntegrationSettingsStore(
                            configManager: appDelegate.sharedConfigManager
                        )
                    ),
                    modelDownloadViewModel: ModelDownloadViewModel(
                        downloadWhisper: { modelId, token in
                            let typedModelId = ModelID(modelId)
                            if let token { setenv("HF_TOKEN", token, 1) } // swiftlint:disable:this no_setenv
                            defer { if token != nil { unsetenv("HF_TOKEN") } }
                            try await WhisperKitPlugin().loadModel(typedModelId)
                        },
                        downloadParakeet: { modelId, token in
                            let typedModelId = ModelID(modelId)
                            if let token { setenv("HF_TOKEN", token, 1) } // swiftlint:disable:this no_setenv
                            defer { if token != nil { unsetenv("HF_TOKEN") } }
                            try await ParakeetPlugin().loadModel(typedModelId)
                        },
                        downloadMLX: { modelId, token in
                            let config = SummaryConfig(
                                modelId: ModelID(modelId),
                                maxTokens: SummaryConfig.default.maxTokens,
                                temperature: SummaryConfig.default.temperature,

            }
        } teardown: {
            // Storage must close even if detector shutdown misbehaves.
            do {
                try await storage?.close()
            } catch {
                logger.error("Storage close during teardown failed: \(error.localizedDescription, privacy: .public)")
            }
        }
    }

    // sequential setup — extraction would harm readability
    // swiftlint:disable:next function_body_length
    func assemble(config: AppConfig, enableCoreAudioListeners: Bool = true) async -> Assembled {
        taskBag = TaskBag()
        let st = await buildStorage()
        // #216: composition root wiring — was constructed inline in TheRecordApp.
        let speakerProfileStore = JSONSpeakerProfileStore()
        // #300: shared voice embedding engine backs both enrollment and auto-matching.
        let voiceEmbedding = VoiceEmbeddingActor()
        let enrollSpeaker = EnrollSpeakerUseCase(store: speakerProfileStore, embedding: voiceEmbedding)
        let matchSpeakers = MatchSpeakersUseCase(store: speakerProfileStore, embedding: voiceEmbedding)
        // Resolve the commitment use case once — both engine and VM share the same instance.
        let sharedTrackUseCase = trackCommitmentsUseCase ?? TrackCommitmentsUseCase(store: InMemoryCommitmentStore())

        let alignUseCase = AlignTranscriptUseCase(
            sampleLoader: AudioFileLoader(),
            reader: st,
            writer: st
        )
        // #213: real PrivacyModeProvider, seeded from the persisted setting, so
        // ExportTranscriptUseCase/QueryContextUseCase/GenericMCPProvider stop
        // seeing nil and their privacy-mode guards actually execute.
        let privacyModeProvider = LivePrivacyModeProvider(initialMode: config.privacyMode)
        let (_, engine, suggestionsVM, queryContext) = buildEngine(
            config: config,
            fallbackTrack: sharedTrackUseCase,
            alignment: alignUseCase,
            privacyModeProvider: privacyModeProvider
        )
        let (libVM, migrationTask) = buildLibraryVM(storage: st)
        let (menuBarVM, pipelineCoordinator) = buildMenuBarVM(
            storage: st, engine: engine, suggestionsVM: suggestionsVM,
            migrationTask: migrationTask, config: config, queryContext: queryContext,
            matchSpeakers: matchSpeakers,
            enableCoreAudioListeners: enableCoreAudioListeners
        )

        // Initialize the Single Source of Truth
        let appState = AppState(
            recording: menuBarVM.recordingStateVM,
            library: libVM,
            initialConfig: config
        )

        // Late-bind AppState to MenuBarVM
        menuBarVM.bindAppState(appState)

        // Wire PipelineCoordinator to AppState.pipeline
        await pipelineCoordinator.setOnStateChange { [weak appState] cleanup, pipeline in
            guard let appState else { return }
            Task { @MainActor in
                appState.pipeline.cleanupState = cleanup
                appState.pipeline.pipelineState = pipeline
            }
        }

        // Recovery fires AFTER menuBarVM is wired
        taskBag.add(Task {
            do {
                let ids = try await RecoverPendingSessionsUseCase(storage: st)()
                for id in ids {
                    await menuBarVM.recoverPendingSession(id)
                }
            } catch {
                let errDesc = String(reflecting: error)
