// MARK: - Storage

func buildStorage() async -> GRDBStorageActor {
    let isTest = ProcessInfo.processInfo.environment["XCTestConfigurationFilePath"] != nil
        || ProcessInfo.processInfo.processName.lowercased().contains("test")
        || ProcessInfo.processInfo.processName.lowercased().contains("xctest")

    let storage: GRDBStorageActor
    do {
        storage = try await Task.detached {
            try isTest ? GRDBStorageActor(databasePath: nil) : GRDBStorageActor()
        }.value
    } catch {
        let errDesc = String(reflecting: error)
        logger
            .critical(
                "SQLite initialization failed: \(errDesc, privacy: .public) — falling back to in-memory storage",
            )
        do {
            storage = try await Task.detached {
                try GRDBStorageActor(databasePath: nil)
            }.value
            await showFatalAlert(error: error)
        } catch let fallbackError {
            let fbDesc = String(reflecting: fallbackError)
            logger
                .critical(
                    "SQLite fallback also failed: \(fbDesc, privacy: .public) — terminating via NSApp.terminate",
                )
            await showFatalAlert(error: fallbackError)
            do { try await Task.sleep(nanoseconds: 10_000_000_000) } catch {}
            exit(1)
        }
    }

    let commitmentStore: GRDBCommitmentStore?
    do {
        commitmentStore = try await Task.detached {
            if isTest {
                return try GRDBCommitmentStore(databasePath: nil)
            } else {
                let dbDir = Directories.appSupport
                try Directories.ensureDirectory(at: dbDir)
                let dbURL = dbDir.appendingPathComponent(
                    AppConstants.Paths.commitmentsDatabaseFileName
                )
                return try GRDBCommitmentStore(databasePath: dbURL)
            }
        }.value
    } catch {

