import Domain
import SwiftUI

/// Meeting picker → speaker picker → name field → enroll (issue #300).
struct SpeakerEnrollmentDisclosure: View {
    @Bindable var viewModel: SettingsViewModel

    @State private var isExpanded = false
    @State private var recordings: [RecordingMetadata] = []
    @State private var speakerIds: [SpeakerID] = []
    @State private var selectedRecordingId: RecordingID?
    @State private var selectedSpeakerId: SpeakerID?
    @State private var name = ""
    @State private var isEnrolling = false

    var body: some View {
        DisclosureGroup("Enroll from meeting", isExpanded: $isExpanded) {
            Picker("Meeting", selection: $selectedRecordingId) {
                Text("Choose a meeting").tag(RecordingID?.none)
                ForEach(recordings, id: \.id) { recording in
                    Text(recording.recordedAt.formatted(date: .abbreviated, time: .shortened))
                        .tag(RecordingID?.some(recording.id))
                }
            }
            .onChange(of: selectedRecordingId) { _, newValue in
                Task { await loadSpeakerIds(for: newValue) }
            }

            Picker("Speaker", selection: $selectedSpeakerId) {
                Text("Choose a speaker").tag(SpeakerID?.none)
                ForEach(speakerIds, id: \.self) { speakerId in
                    Text(speakerId.rawValue).tag(SpeakerID?.some(speakerId))
                }
            }
            .disabled(speakerIds.isEmpty)

            TextField("Speaker name", text: $name)

            Button("Enroll") {
                Task { await enroll() }
            }
            .disabled(selectedRecordingId == nil || selectedSpeakerId == nil || name.isEmpty || isEnrolling)
        }
        .task { await loadRecordings() }
    }

    private func loadRecordings() async {
        guard let repo = viewModel.recordingReadRepository else { return }
        recordings = (try? await repo.listAllRecordingsWithMetadata()) ?? []
    }

    private func loadSpeakerIds(for recordingId: RecordingID?) async {
        guard let recordingId, let reader = viewModel.diarizationReader else {
            speakerIds = []
            return
        }
        let segments = (try? await reader.getSegments(id: recordingId)) ?? []
        var seen = Set<SpeakerID>()
        speakerIds = segments.map(\.speakerId).filter { seen.insert($0).inserted }
    }

    private func enroll() async {
        guard let recordingId = selectedRecordingId, let speakerId = selectedSpeakerId else { return }
        isEnrolling = true
        await viewModel.enrollSpeaker(fromRecording: recordingId, speakerId: speakerId, name: name)
        isEnrolling = false
        if viewModel.errorMessage == nil {
            name = ""
            selectedRecordingId = nil
            selectedSpeakerId = nil
            isExpanded = false
        }
    }
}

