    /// Controls what `isReady()` returns. Defaults to `false` (model not yet
    /// loaded) so existing tests that check `loadModel` is called continue to
    /// pass. Set to `true` in prewarm-path tests.
    public var stubIsReady = false

    public init() {}

    // MARK: - SummarizationEngine

    public func loadModel(_ config: SummaryConfig) async throws {
        loadModelCalled = true
        loadModelCallCount += 1
        lastConfig = config
        if let error = errorToThrow { throw error }
        stubIsReady = true
    }

