        return mockSummary ?? MeetingSummary(
            summary: "Test summary",
            decisions: [],
            actionItems: [],
            topics: [],
            openQuestions: [],
            generatedAt: Date(timeIntervalSince1970: 0),
            modelId: ModelID("test-model"),
            processingTime: 0.5,
        )
    }

    public func isReady() async -> Bool {
        stubIsReady
    }

    public func generate(prompt: String) async throws -> String {
        generateCalled = true
        lastGeneratePrompt = prompt
        if let error = errorToThrow { throw error }
        return "Generated response for mock"
    }

    // MARK: - Test helpers

    public func setErrorToThrow(_ error: Error?) {
        errorToThrow = error
    }

    public func setMockSummary(_ summary: MeetingSummary) {
        mockSummary = summary
    }

    public func setStubIsReady(_ value: Bool) {
        stubIsReady = value
    }
}

