// MARK: - Helpers

private func makeSegment(
    text: String,
    startTime: Double,
    endTime: Double,
    sequenceNumber: Int = 0
) -> TranscriptionSegment {
    TranscriptionSegment(
        id: SegmentID.generate(),
        text: text,
        startTime: startTime,
        endTime: endTime,
        confidence: 0.9,
        isFinal: true,
        sequenceNumber: sequenceNumber,
        wordTimings: nil
    )
}

/// Generate a synthetic audio buffer (sine wave at 16 kHz).
private func sineWave(seconds: Double, hz: Double = 440, sampleRate: Int = 16_000) -> [Float] {
    let count = Int(seconds * Double(sampleRate))
    var result = [Float](repeating: 0, count: count)
    let twoPiHz = 2.0 * Double.pi * hz
    for i in 0 ..< count {
        result[i] = Float(sin(twoPiHz * Double(i) / Double(sampleRate)))
    }
    return result
}

