import Business
import Domain
import Foundation

@MainActor
public extension BroadsheetAppState {
    /// Re-runs the high-quality transcription pass on the stored audio file
    /// and updates the transcript displayed in the detail view.
    func redriveTranscription() async {
        guard let id = selectedMeetingID else {
            logger.warning("redriveTranscription — no meeting selected")
            return
        }
        logger.info("redriveTranscription START — recording=\(id, privacy: .public)")
        showToast(ToastMessage(severity: .info, message: "Re-transcribing...", duration: 120))
        do {
            let result = try await menuBarVM.pipelineCoordinator.cleanupTranscribe.transcribeCleanupPass(
                recordingId: id,
                modelId: ModelIDs.cleanupTranscription
            )
            detailVM.transcript = result.fullText
            logger
                .info(
                    // swiftlint:disable:next line_length
                    "redriveTranscription DONE — \(result.segments.count, privacy: .public) segments, \(result.fullText.count, privacy: .public) chars"
                )
            try Task.checkCancellation()

            showToast(ToastMessage(severity: .info, message: "Diarizing speakers...", duration: 120))
            logger.info("redriveTranscription attempting diarization — recording=\(id, privacy: .public)")
            let diarized = try await menuBarVM.pipelineCoordinator.diarizeMeeting.diarize(
                recordingId: id,
                transcription: result
            )
            guard selectedMeetingID == id else {
                logger.info("redriveTranscription — meeting switched during diarization, discarding result")
                return
            }
            detailVM.segments = diarized.segments
            logger
                .info(
                    // swiftlint:disable:next line_length
                    "redriveTranscription diarization DONE — \(diarized.segments.count, privacy: .public) segments, \(diarized.speakerCount, privacy: .public) speakers"
                )
            try Task.checkCancellation()

            // redriveTranscription was previously missing the summarization pass (Concern #7).
            showToast(ToastMessage(severity: .info, message: "Summarizing...", duration: 120))
            await menuBarVM.runSummarizationPass(recordingId: id, transcript: diarized)

            await libraryVM.loadMeetingsAndCaptureError()
            showToast(ToastMessage(severity: .success, message: "Transcription updated"))
        } catch is CancellationError {
            return // silently cancelled — user navigated away
        } catch {
            let msg = "Re-transcription failed: \(error.userFacingMessage)"
            logger.error("\(msg, privacy: .private)")
            showToast(ToastMessage(severity: .error, message: msg))
        }
    }

    /// Runs summarization on the selected meeting using existing diarized segments
    /// (or falls back to the transcript as a single-speaker input), then persists
    /// the result and updates the detail view.
    func summarizeNow(meetingType: MeetingType = SummaryConfig.default.meetingType) async {
        guard let id = selectedMeetingID else { return }
        showToast(ToastMessage(severity: .info, message: "Summarizing...", duration: 120))
        logger.info("summarizeNow entered — recordingId=\(id, privacy: .private) meetingType=\(meetingType.rawValue, privacy: .public)")
        do {
            let rawSegments = try await detailVM.loadSegmentsForCurrentMeeting()
            let transcriptText = detailVM.transcript ?? ""

            guard !rawSegments.isEmpty || !transcriptText.isEmpty else {
                showToast(ToastMessage(
                    severity: .warning,
                    message: "Nothing to summarize — no transcript or speaker segments found."
                ))
                return
            }

            let diarized = if rawSegments.isEmpty {
                DiarizedTranscript(
                    segments: [DiarizedSegment(
                        text: transcriptText, speakerId: SpeakerID.singleSpeaker,
                        startTime: 0, endTime: 0, confidence: 1.0
                    )],
                    speakerCount: 1, processingTime: 0
                )
            } else {
                DiarizedTranscript(
                    segments: rawSegments,
                    speakerCount: Set(rawSegments.map(\.speakerId)).count,
                    processingTime: 0
                )
            }
            let summary = try await menuBarVM.pipelineCoordinator.summarizeMeeting.summarize(
                recordingId: id, transcript: diarized, meetingType: meetingType
            )
            guard selectedMeetingID == id else {
                logger.info("summarizeNow — meeting switched during summarization, discarding result")
                return
            }
            detailVM.summary = summary
            showToast(ToastMessage(severity: .success, message: "Summary generated"))
        } catch is CancellationError {
            return
        } catch {
            let msg = "Summarization failed: \(error.userFacingMessage)"
            logger.error("\(msg, privacy: .private)")
            showToast(ToastMessage(severity: .error, message: msg))
        }
    }
}

import SwiftUI

// MARK: - Detail Tabs + Split Body (Phase 8)

@MainActor
public struct BroadsheetDetailTabs: View {
    @Environment(BroadsheetAppState.self) private var appState

    public init() {}

    public var body: some View {
        VStack(spacing: 0) {
            tabBar
            Rectangle().fill(Color.hairlineColor).frame(height: Metrics.hairline)
            tabContent
        }
    }

    /// Custom tab bar — no system TabView, no blue selection
    private var tabBar: some View {
        HStack(spacing: 0) {
            ForEach(BroadsheetTab.allCases, id: \.self) { tab in
                tabButton(tab)
            }
            Spacer()
            HStack(spacing: Metrics.unit) {
                Text("↓ EXPORT").folio()
                Text("⇪ SHARE").folio()
            }
            .padding(.trailing, Metrics.unit * 2)
        }
        .background(Color.bg)
    }

    private func tabButton(_ tab: BroadsheetTab) -> some View {
        let isActive = appState.selectedTab == tab
        return Button {
            appState.selectedTab = tab
        } label: {
            VStack(spacing: 0) {
                Text(tab.displayName)
                    .font(Typography.uiLabel)
                    .foregroundStyle(isActive ? Color.ink : Color.ink3)
                    .padding(.horizontal, Metrics.unit * 2)
                    .padding(.vertical, Metrics.unit)
                Rectangle()
                    .fill(isActive ? Color.rule : Color.clear)
                    .frame(height: 2)
            }
        }
        .buttonStyle(.plain)
        .accessibilityAddTraits(isActive ? [.isButton, .isSelected] : .isButton)
        .accessibilityLabel(tab.displayName)
    }

    /// Keeps all tab views alive in the hierarchy so scroll state (and other
    /// view state) is preserved across tab switches. Only the active tab is
    /// visible; inactive tabs are hidden via opacity + hit-testing.
    ///
    /// Bug #17: switching tabs with a plain `switch` destroyed and recreated
    /// `TranscriptColumn`, resetting its `ScrollView` scroll position.
    private var tabContent: some View {
        ZStack {
            NotesColumn()
                .opacity(appState.selectedTab == .notes ? 1 : 0)
                .allowsHitTesting(appState.selectedTab == .notes)
                .accessibilityHidden(appState.selectedTab != .notes)

            TranscriptColumn()
                .opacity(appState.selectedTab == .transcript ? 1 : 0)
                .allowsHitTesting(appState.selectedTab == .transcript)
                .accessibilityHidden(appState.selectedTab != .transcript)

            BroadsheetSummaryView()
                .opacity(appState.selectedTab == .summary ? 1 : 0)
                .allowsHitTesting(appState.selectedTab == .summary)
                .accessibilityHidden(appState.selectedTab != .summary)

            suggestionsContent
                .opacity(appState.selectedTab == .suggestions ? 1 : 0)
                .allowsHitTesting(appState.selectedTab == .suggestions)
                .accessibilityHidden(appState.selectedTab != .suggestions)

            Text("Actions").font(Typography.body).foregroundStyle(Color.ink3)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .opacity(appState.selectedTab == .actions ? 1 : 0)
                .allowsHitTesting(appState.selectedTab == .actions)
                .accessibilityHidden(appState.selectedTab != .actions)

            Text("Templates").font(Typography.body).foregroundStyle(Color.ink3)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .opacity(appState.selectedTab == .templates ? 1 : 0)
                .allowsHitTesting(appState.selectedTab == .templates)
                .accessibilityHidden(appState.selectedTab != .templates)
        }
    }

    @ViewBuilder
    private var suggestionsContent: some View {
        if let vm = appState.contextSuggestionsVM {
            ContextSuggestionsPanelView(viewModel: vm)
        } else {
            Text("No signals yet.")
                .foregroundStyle(Color.ink3)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
    }
}

