import Foundation

/// Defines the service boundary for generating a business plan document from a
/// meeting transcript. Implementations own the concrete guided-generation
/// pipeline (extraction, correction, schema verification) and return the
/// final plan rendered as markdown.
public protocol BusinessPlanGenerator: Sendable {

    /// Generates a business plan from a meeting transcript.
    ///
    /// - Parameter transcript: the meeting transcript to derive the plan from.
    /// - Returns: the rendered business plan, as markdown.
    /// - Throws: any implementation-specific error from the generation pipeline.
    func generatePlan(from transcript: String) async throws -> String
}

