struct BusinessPlanSkillTests {
    private static let validJSON = """
    {
        "executiveSummary": "Summary text",
        "goalsAndObjectives": "Goals text",
        "businessBackground": "Background text",
        "ownershipAndHR": "Ownership text",
        "productsAndTargetMarket": "Products text",
        "valueChain": "Value chain text",
        "productCosts": "Costs text",
        "salesAndMarketing": "Sales text",
        "swotAnalysis": "SWOT text",
        "industryAnalysis": "Industry text",
        "riskEvaluation": "Risk text",
        "financialProjections": "Financial text"
    }
    """

    @Test("AC1: runs all 3 stages and renders markdown with all 12 section headings")
    func generatesFullPlan() async throws {
        let engine = ScriptedSummarizationEngine(responses: [
            "[extracted facts]",
            "[corrected text]",
            Self.validJSON,
        ])
        let skill = BusinessPlanSkill(engine: engine)

        let markdown = try await skill.generatePlan(from: "raw transcript")

        let headings = [
            "Executive Summary", "Goals and Objectives", "Business Background",
            "Ownership and HR", "Products and Target Market", "Value Chain",
            "Product Costs", "Sales and Marketing", "SWOT Analysis",
            "Industry Analysis", "Risk Evaluation", "Financial Projections",
        ]
        for heading in headings {
            #expect(markdown.contains(heading), "missing section: \(heading)")
        }
        let promptCount = await engine.prompts.count
        #expect(promptCount == 3)
    }

    @Test("AC2: verifier decode failure surfaces an error")
