        let mockService = MockTranscriptRepairService()
        await mockService.setMockRepairedTranscript("Fixed transcript")

        let useCase = RepairTranscriptUseCase(repairService: mockService)
        let result = try await useCase.execute(transcript: "broken transcript")

        let called = await mockService.repairCalled
        #expect(called == true)
        #expect(result == "Fixed transcript")
    }

    @Test("execute() throws if service throws")
    func testExecuteThrows() async {
        let mockService = MockTranscriptRepairService()
        struct TestError: Error {}
        await mockService.setErrorToThrow(TestError())

        let useCase = RepairTranscriptUseCase(repairService: mockService)

        do {
            _ = try await useCase.execute(transcript: "broken transcript")
            Issue.record("Expected execute to throw")
        } catch is TestError {
            // Expected
        } catch {
            Issue.record("Unexpected error: \(error)")
        }
    }
}

extension MockTranscriptRepairService {
    func setMockRepairedTranscript(_ transcript: String?) {
        self.mockRepairedTranscript = transcript
    }

    func setErrorToThrow(_ error: Error?) {
        self.errorToThrow = error
    }
}

