import Domain
import Logging
import SwiftUI

// MARK: - Summary View ("The Published Article")

@MainActor
public struct BroadsheetSummaryView: View {
    @Environment(BroadsheetAppState.self) private var appState

    private static let uiLogger = AppLogger.for(category: "UI")

    public init() {}

    @ViewBuilder
    private var summarizeButton: some View {
        let hasSummary = appState.detailVM.summary != nil
        let label = hasSummary ? "Re-summarize" : "Summarize Now"
        let state = appState
        let action: @MainActor () -> Void = {
            Self.uiLogger.info("CHECKPOINT 1: Summarize button tapped")
            Task { await state.summarizeNow() }
        }
        if hasSummary {
            Button(label, action: action).buttonStyle(.bordered).disabled(appState.pipelineIsSummarizing)
                .controlSize(.small)
        } else {
            Button(label, action: action).buttonStyle(.borderedProminent).disabled(appState.pipelineIsSummarizing)
                .controlSize(.small)
        }
    }

    public var body: some View {
        ScrollView {
            if let summary = appState.detailVM.summary,
               let meeting = appState.selectedMeeting
            {
                VStack(alignment: .leading, spacing: 0) {
                    article(summary: summary, meeting: meeting)
                    if appState.detailVM.selectedMeeting != nil {
                        summarizeButton.padding(.horizontal, Metrics.unit * 3).padding(.bottom, Metrics.unit * 2)
                    }
                }
            } else {
                VStack(spacing: Metrics.unit * 2) {
                    if appState.pipelineIsSummarizing {
                        ProgressView()
                            .accessibilityLabel("Summarizing")
                            .accessibilityHint("Please wait")
                    } else {
                        Text("No summary yet.")
                            .font(Typography.body)
                            .foregroundStyle(Color.ink3)
                    }
                    if appState.detailVM.selectedMeeting != nil {
                        summarizeButton
                    }
                }
                .padding(Metrics.unit * 3)
                .frame(maxWidth: .infinity)
            }
        }
        .background(Color.bg)
    }

    private func article(summary: MeetingSummary, meeting: RecordingMetadata) -> some View {
        VStack(alignment: .leading, spacing: Metrics.unit * 2) {
            // Dateline
            Text(dateline(from: meeting))
                .folio()

            // TL;DR with drop cap
            if !summary.summary.isEmpty {
                DropCapText(text: summary.summary)
            }

            Rectangle().fill(Color.midRule).frame(height: Metrics.hairline)

            // Decisions
            if !summary.decisions.isEmpty {
                StandfirstBox(header: "DECISIONS", items: summary.decisions, style: .section)
            }

            // Action items
            if !summary.actionItems.isEmpty {
                StandfirstBox(
                    header: "ACTION ITEMS",
                    items: summary.actionItems.map { item in
                        "\(item.description)\(item.assignee.map { " — \($0)" } ?? "")"
                    },
                    style: .checkbox
                )
            }

            // Open questions
            if !summary.openQuestions.isEmpty {
                StandfirstBox(header: "OPEN QUESTIONS", items: summary.openQuestions, style: .section)
            }

            Text("— ENDS —")
                .folio()
                .frame(maxWidth: .infinity, alignment: .center)
                .padding(.top, Metrics.unit)
        }
        .padding(Metrics.unit * 3)
        .frame(maxWidth: 640, alignment: .leading)
    }

    // swiftlint:disable no_nsformatter_instantiation
    // safe: @MainActor isolation serialises all access to these non-Sendable formatters
    @MainActor private static let dateFormatter: DateFormatter = {
        let f = DateFormatter()
        f.dateFormat = "EEE MMM d, yyyy"
        return f
    }()

    @MainActor private static let timeFormatter: DateFormatter = {
        let f = DateFormatter()
        f.dateFormat = "HH:mm"
        return f
    }()

    // swiftlint:enable no_nsformatter_instantiation

    @MainActor private func dateline(from meeting: RecordingMetadata) -> String {
        let start = Self.dateFormatter.string(from: meeting.recordedAt).uppercased()
        let end = meeting.recordedAt.addingTimeInterval(meeting.duration)
        // swiftlint:disable:next line_length
        return "\(start) · \(Self.timeFormatter.string(from: meeting.recordedAt))–\(Self.timeFormatter.string(from: end))"
    }
}

