import Foundation

/// Protocol for domain errors that can be shown to users and fully logged.
///
/// Conformance gives every error case a human-readable `userMessage` for the UI
/// and a technical `debugDescription` for logs, plus an optional deep-link into
/// System Settings when the error is permission-related.
public protocol UserFacingError: Error {
    /// Human-readable message suitable for UI display (e.g. `errorMessage`).
    var userMessage: String { get }

    /// Full technical detail for structured logging.
    var debugDescription: String { get }

    /// Optional `x-apple.systempreferences:` URL to open the relevant
    /// System Settings pane so the user can fix the issue.
    var settingsDeepLink: URL? { get }
}

public extension UserFacingError {
    /// Default: no deep-link.
    var settingsDeepLink: URL? {
        nil
    }
}

public extension Error {
    /// Returns `userMessage` if the error conforms to `UserFacingError`;
    /// falls back to `localizedDescription` for all other error types (#57).
    var userFacingMessage: String {
        (self as? any UserFacingError)?.userMessage ?? localizedDescription
    }
}

