@Observable
@MainActor
public final class MeetingDetailViewModel {
    public var selectedMeeting: RecordingMetadata?

    /// The audio file URL for the currently selected meeting.
    /// Used by ``TranscriptTabView`` to load audio into ``AudioPlayerViewModel``.
    public var audioURL: URL? { selectedMeeting?.audioURL }

    public var transcript: String?
    public var segments: [DiarizedSegment] = []

    // #174: summary uses didSet to rebuild summaryMarkdownText once on change,
    // so SummaryTabView reads a pre-built String rather than calling .map/.joined
    // on every body evaluation.
    public var summary: MeetingSummary? {
        didSet { summaryMarkdownText = Self.buildSummaryMarkdown(summary) }
    }

    /// Pre-built markdown string for SummaryTabView. Updated whenever `summary`
    /// changes via `didSet` — never recomputed during SwiftUI body evaluation.
    public private(set) var summaryMarkdownText = ""

    public var notes = ""
    public private(set) var notesError: (any Error)?
    public private(set) var saveError: (any Error)?

    // #302: Business Plan Pro action.
    public private(set) var businessPlanMarkdown: String?
    public private(set) var businessPlanError: (any Error)?
    public private(set) var isGeneratingBusinessPlan = false
    public var canGenerateBusinessPlan: Bool { generateBusinessPlanUseCase != nil }

    private let reader: any MeetingDetailReadRepository
    private let writer: any MeetingDetailWriteRepository
    private let repairUseCase: RepairTranscriptUseCase?
    private let generateBusinessPlanUseCase: GenerateBusinessPlanUseCase?
    private let logger = AppLogger.for(category: "MeetingDetail")
    private var loadTask: Task<Void, any Error>?
    private var saveDebounceTask: Task<Void, Never>?

    public init(
        reader: any MeetingDetailReadRepository,
        writer: any MeetingDetailWriteRepository,
        repairUseCase: RepairTranscriptUseCase? = nil,
        generateBusinessPlanUseCase: GenerateBusinessPlanUseCase? = nil
    ) {
        self.reader = reader
        self.writer = writer
        self.repairUseCase = repairUseCase
        self.generateBusinessPlanUseCase = generateBusinessPlanUseCase
    }

    // MARK: - Summary Markdown (#174)

    /// Builds the markdown representation of a `MeetingSummary` without accessing
    /// any @Observable stored properties — safe to call from `didSet`.
    static func buildSummaryMarkdown(_ summary: MeetingSummary?) -> String {
        guard let s = summary else { return "" }
        var md = s.summary
        if !s.topics.isEmpty {
            md += "\n\n## Topics\n" + s.topics.map { "- \($0)" }.joined(separator: "\n")
        }
        if !s.decisions.isEmpty {
            md += "\n\n## Decisions\n" + s.decisions.map { "- \($0)" }.joined(separator: "\n")
        }
        if !s.actionItems.isEmpty {
            md += "\n\n## Action Items\n" + s.actionItems.map { item in
                var line = "- \(item.description)"
                if let who = item.assignee { line += " (\(who))" }
                if let due = item.dueDate {
                    line += " — due \(due.formatted(date: .abbreviated, time: .omitted))"
                }
                return line
            }.joined(separator: "\n")
        }
        if !s.openQuestions.isEmpty {
            md += "\n\n## Open Questions\n" + s.openQuestions.map { "- \($0)" }.joined(separator: "\n")
        }
        return md
    }

    // MARK: - Detail Loading

    public func loadDetail(for meeting: RecordingMetadata) async throws {
        saveDebounceTask?.cancel()
        saveDebounceTask = nil
        loadTask?.cancel()
        selectedMeeting = meeting
        // Don't nil out summary/transcript immediately — keep the previous meeting's
        // content visible until the new one loads to avoid a blank flash.
        let requestedId = meeting.id

        let task = Task { [weak self] in
            guard let self else { return }
            let stored = try await self.reader.getRecording(id: meeting.id)
            try Task.checkCancellation()
            guard self.selectedMeeting?.id == requestedId else { return }
            self.transcript = stored.transcript?.fullText

            let loadedSummary = try await self.reader.getSummary(for: meeting.id)
            try Task.checkCancellation()
            guard self.selectedMeeting?.id == requestedId else { return }
            self.summary = loadedSummary

            let loadedSegments = try await self.reader.getSegments(id: meeting.id)
            try Task.checkCancellation()
            guard self.selectedMeeting?.id == requestedId else { return }
            self.segments = loadedSegments

            do {
                let loadedNotes = try await self.reader.getNotes(meetingId: requestedId)
                try Task.checkCancellation()
                guard self.selectedMeeting?.id == requestedId else { return }
                self.notes = loadedNotes
            } catch {
                self.logger
                    .error(
                        // swiftlint:disable:next line_length
                        "getNotes failed for \(requestedId, privacy: .public): \(String(describing: error), privacy: .private)"
                    )
                self.notesError = error
            }
        }
        loadTask = task
        try await task.value
    }

    public func saveNotes(_ text: String) async {
        guard let id = selectedMeeting?.id else { return }
        await saveNotes(text, forMeetingId: id)
    }

    /// Saves notes for an explicit meeting ID. Used by the debounce path to avoid
    /// resolving `selectedMeeting` at execution time (which may have changed).
    public func saveNotes(_ text: String, forMeetingId meetingId: RecordingID) async {
        saveError = nil
        do {
            try await writer.saveNotes(meetingId: meetingId, text: text)
        } catch {
            logger
                .error(
                    // swiftlint:disable:next line_length
                    "saveNotes failed for \(meetingId, privacy: .public): \(String(describing: error), privacy: .private)"
                )
            saveError = error
        }
    }

    /// Loads the diarized segments for the currently selected meeting.
    public func loadSegmentsForCurrentMeeting() async throws -> [DiarizedSegment] {
        guard let id = selectedMeeting?.id else { return [] }
        return try await reader.getSegments(id: id)
    }

    /// Persists a summary for the currently selected meeting and updates the local state.
    public func applySummary(_ summary: MeetingSummary) async throws {
        guard let id = selectedMeeting?.id else { return }
        try await writer.saveSummary(for: id, summary: summary)
        self.summary = summary
    }

    /// Debounced entry point for keystroke-driven saves. Cancels any pending save
    /// and schedules a new one after 500 ms so rapid edits coalesce into one write.
    /// The meeting ID is captured at schedule time — not at execution time — to
    /// prevent cross-meeting note corruption when the user switches meetings within
    /// the debounce window.
    public func debouncedSaveNotes(_ text: String) {
        let meetingId = selectedMeeting?.id // capture NOW, before any await
        saveDebounceTask?.cancel()
        saveDebounceTask = Task { [weak self] in
            do { try await Task.sleep(for: .milliseconds(500)) } catch { return }
            guard !Task.isCancelled, let self, let meetingId else { return }
            await self.saveNotes(text, forMeetingId: meetingId)
        }
    }

    public func recordingIDsWithSummaries() async throws -> Set<RecordingID> {
        try await reader.recordingIDsWithSummaries()
    }

    /// Generates a business plan from the currently loaded transcript (#302).
    public func generateBusinessPlan() async {
        guard let generateBusinessPlanUseCase, let transcript else { return }
        isGeneratingBusinessPlan = true
        businessPlanError = nil
        do {
            businessPlanMarkdown = try await generateBusinessPlanUseCase.execute(transcript: transcript)
        } catch {
            businessPlanError = error
        }
        isGeneratingBusinessPlan = false
    }
}

struct Run: AsyncParsableCommand {
    static let configuration = CommandConfiguration(
        abstract: "Run the pipeline on a single WAV file"
    )

    @Argument(help: "Path to a WAV file (16-bit PCM, any sample rate)")
    var wavFile: String

    @Flag(name: .long, help: "Skip the summarization stage")
    var skipSummary: Bool = false

    @Option(name: .long, help: "Quality: fast (Parakeet), high (two-pass), max (WhisperKit only)")
    var quality: String = "fast"

    @Option(name: .long, help: "Summary model HF slug (default: gemma-4-e4b-it-4bit)")
    var model: String?

    func run() async throws {
        Term.banner()
        let url = URL(fileURLWithPath: wavFile)
        guard FileManager.default.fileExists(atPath: url.path) else {
            Term.error("File not found: \(wavFile)")
            throw ExitCode.failure
        }
        guard let q = Quality(rawValue: quality) else {
            Term.error("Invalid quality: \(quality). Use: fast, high, or max")
            throw ExitCode.failure
        }

        Term.header("PIPELINE: \(url.lastPathComponent)")
        let runner = PipelineRunner()
        let result = try await runner.run(wavURL: url, quality: q, skipSummary: skipSummary, summaryModelId: model)
        ResultPrinter.print(result: result, file: url.lastPathComponent)
        Term.success("Pipeline complete")
    }
}

