/// Single composition root for THE RECORD.
///
/// Owns all long-lived infrastructure objects and constructs the full
/// dependency graph when `assemble(config:)` is called.
@MainActor
final class AppAssembler {

    struct Assembled {
        let appState: AppState
        let menuBarVM: MenuBarViewModel
        let libraryVM: MeetingLibraryViewModel
        let searchVM: SearchViewModel
        let detailVM: MeetingDetailViewModel
        let commitmentsVM: CommitmentsViewModel
        let contextSuggestionsVM: ContextSuggestionsViewModel
        let migrationTask: Task<Void, Never>
        let repairUseCase: RepairTranscriptUseCase
        let privacyModeProvider: LivePrivacyModeProvider
        let speakerProfileStore: JSONSpeakerProfileStore
    }

    // Long-lived infrastructure — must outlive all VMs.
    var storage: GRDBStorageActor?
    var trackCommitmentsUseCase: TrackCommitmentsUseCase?
    var transcriptionBuilt: TranscriptionSubAssembler.Built?
    // #250: retained so its init-spawned launch()/start() chain (weak self)
    // survives past buildMenuBarVM() returning — otherwise ARC deallocates it
    // before the detector ever observes a calendar event.
    var calendarAwareMeetingDetector: CalendarAwareMeetingDetector?

    let logger = AppLogger.for(category: "AppAssembler")

    // Retained so assemble() can be called again without leaking the previous loop.
    var searchSyncTask: Task<Void, Never>?
    var taskBag = TaskBag()

    /// Stops long-lived infrastructure that requires explicit teardown.
    /// Awaited from `applicationShouldTerminate` (#44, #280) so shutdown
    /// completes before the process exits — previously the detector shutdown
    /// was fire-and-forget and the database pool was never closed.
    func teardown() async {
        transcriptionBuilt?.prewarmTask.cancel()
        searchSyncTask?.cancel()
        await withAsyncTeardown {
            if let detector = calendarAwareMeetingDetector {
                await detector.shutdown()
            }
        } teardown: {
            // Storage must close even if detector shutdown misbehaves.
            do {
                try await storage?.close()
            } catch {
                logger.error("Storage close during teardown failed: \(error.localizedDescription, privacy: .public)")
            }
        }
    }

    // sequential setup — extraction would harm readability
    // swiftlint:disable:next function_body_length
    func assemble(config: AppConfig, enableCoreAudioListeners: Bool = true) async -> Assembled {
        taskBag = TaskBag()
        let st = await buildStorage()
        // #216: composition root wiring — was constructed inline in TheRecordApp.
        let speakerProfileStore = JSONSpeakerProfileStore()
        // Resolve the commitment use case once — both engine and VM share the same instance.
        let sharedTrackUseCase = trackCommitmentsUseCase ?? TrackCommitmentsUseCase(store: InMemoryCommitmentStore())

        let alignUseCase = AlignTranscriptUseCase(
            sampleLoader: AudioFileLoader(),
            reader: st,
            writer: st
        )
        // #213: real PrivacyModeProvider, seeded from the persisted setting, so
        // ExportTranscriptUseCase/QueryContextUseCase/GenericMCPProvider stop
        // seeing nil and their privacy-mode guards actually execute.
        let privacyModeProvider = LivePrivacyModeProvider(initialMode: config.privacyMode)
        let (_, engine, suggestionsVM, queryContext) = buildEngine(
            config: config,
            fallbackTrack: sharedTrackUseCase,
            alignment: alignUseCase,
            privacyModeProvider: privacyModeProvider
        )
        let (libVM, migrationTask) = buildLibraryVM(storage: st)
        let (menuBarVM, pipelineCoordinator) = buildMenuBarVM(
            storage: st, engine: engine, suggestionsVM: suggestionsVM,
            migrationTask: migrationTask, config: config, queryContext: queryContext,
            enableCoreAudioListeners: enableCoreAudioListeners
        )

        // Initialize the Single Source of Truth
        let appState = AppState(
            recording: menuBarVM.recordingStateVM,
            library: libVM,
            initialConfig: config
        )

        // Late-bind AppState to MenuBarVM
        menuBarVM.bindAppState(appState)

        // Wire PipelineCoordinator to AppState.pipeline
        await pipelineCoordinator.setOnStateChange { [weak appState] cleanup, pipeline in
            guard let appState else { return }
            Task { @MainActor in
                appState.pipeline.cleanupState = cleanup
                appState.pipeline.pipelineState = pipeline
            }
        }

        // Recovery fires AFTER menuBarVM is wired
        taskBag.add(Task {
            do {
                let ids = try await RecoverPendingSessionsUseCase(storage: st)()
                for id in ids {
                    await menuBarVM.recoverPendingSession(id)
                }
            } catch {
                let errDesc = String(reflecting: error)
                logger.error("Crash recovery check failed: \(errDesc, privacy: .public)")
            }
        })

        let commitmentsVM = CommitmentsViewModel(useCase: sharedTrackUseCase)

        let repairEngine = transcriptionBuilt?.summarizationEngine ?? MLXSummarizationPlugin()
        let repairUseCase = RepairTranscriptUseCase(
            repairService: ProTranscriptRepairService(engine: repairEngine)
        )
        // #302: same summarization engine drives the guided business-plan pipeline.
        let generateBusinessPlanUseCase = GenerateBusinessPlanUseCase(
            generator: BusinessPlanSkill(engine: repairEngine)
        )

        let detailVM = MeetingDetailViewModel(
            reader: st, writer: st, repairUseCase: repairUseCase,
            generateBusinessPlanUseCase: generateBusinessPlanUseCase
        )

        // Bind DetailVM to AppState for unified selection auto-loading
        appState.bind(detailVM: detailVM)

        let searchVM = SearchViewModel(
            searchUseCase: SearchRecordingsUseCase(storage: st),
            libraryViewModel: libVM
        )

        // Keep searchVM.meetings in sync with libraryVM whenever it reloads (#72, #85).
        searchSyncTask?.cancel()
        searchSyncTask = SearchLibrarySync.start(library: libVM, search: searchVM)

        return Assembled(
            appState: appState,
            menuBarVM: menuBarVM,
            libraryVM: libVM,
            searchVM: searchVM,
            detailVM: detailVM,
            commitmentsVM: commitmentsVM,
            contextSuggestionsVM: suggestionsVM,
            migrationTask: migrationTask,
            repairUseCase: repairUseCase,
            privacyModeProvider: privacyModeProvider,
            speakerProfileStore: speakerProfileStore
        )
    }

}

import Domain
import MarkdownUI
import SwiftUI

/// Surfaces the "Generate Business Plan" Pro action for the selected meeting (#302).
@MainActor
public struct BroadsheetBusinessPlanView: View {
    @Environment(BroadsheetAppState.self) private var appState

    public init() {}

    @ViewBuilder
    private var generateButton: some View {
        let detailVM = appState.detailVM
        let hasPlan = detailVM.businessPlanMarkdown != nil
        let label = hasPlan ? "Regenerate Business Plan" : "Generate Business Plan"
        let action: @MainActor () -> Void = {
            Task { await detailVM.generateBusinessPlan() }
        }
        let isDisabled = detailVM.isGeneratingBusinessPlan || detailVM.transcript == nil
        if hasPlan {
            Button(label, action: action).buttonStyle(.bordered).disabled(isDisabled)
                .controlSize(.small).accessibilityLabel(label)
        } else {
            Button(label, action: action).buttonStyle(.borderedProminent).disabled(isDisabled)
                .controlSize(.small).accessibilityLabel(label)
        }
    }

    public var body: some View {
        let detailVM = appState.detailVM
        ScrollView {
            VStack(alignment: .leading, spacing: Metrics.unit * 2) {
                if !detailVM.canGenerateBusinessPlan {
                    Text("Business Plan generation is a Pro feature.")
                        .font(Typography.body)
                        .foregroundStyle(Color.ink3)
                } else if let markdown = detailVM.businessPlanMarkdown {
                    Markdown(markdown)
                    generateButton
                } else if detailVM.isGeneratingBusinessPlan {
                    ProgressView()
                        .accessibilityLabel("Generating business plan")
                        .accessibilityHint("Please wait")
                } else {
                    Text("No business plan yet.")
                        .font(Typography.body)
                        .foregroundStyle(Color.ink3)
                    generateButton
                }
                if let error = detailVM.businessPlanError {
                    Text("Failed: \(error.userFacingMessage)")
                        .font(Typography.body)
                        .foregroundStyle(.red)
                }
            }
            .padding(Metrics.unit * 3)
            .frame(maxWidth: .infinity, alignment: .leading)
        }
        .background(Color.bg)
    }
}

import SwiftUI

// MARK: - Detail Tabs + Split Body (Phase 8)

@MainActor
public struct BroadsheetDetailTabs: View {
    @Environment(BroadsheetAppState.self) private var appState

    public init() {}

    public var body: some View {
        VStack(spacing: 0) {
            tabBar
            Rectangle().fill(Color.hairlineColor).frame(height: Metrics.hairline)
            tabContent
        }
    }

    /// Custom tab bar — no system TabView, no blue selection
    private var tabBar: some View {
        HStack(spacing: 0) {
            ForEach(BroadsheetTab.allCases, id: \.self) { tab in
                tabButton(tab)
            }
            Spacer()
            HStack(spacing: Metrics.unit) {
                Text("↓ EXPORT").folio()
                Text("⇪ SHARE").folio()
            }
            .padding(.trailing, Metrics.unit * 2)
        }
        .background(Color.bg)
    }

    private func tabButton(_ tab: BroadsheetTab) -> some View {
        let isActive = appState.selectedTab == tab
        return Button {
            appState.selectedTab = tab
        } label: {
            VStack(spacing: 0) {
                Text(tab.displayName)
                    .font(Typography.uiLabel)
                    .foregroundStyle(isActive ? Color.ink : Color.ink3)
                    .padding(.horizontal, Metrics.unit * 2)
                    .padding(.vertical, Metrics.unit)
                Rectangle()
                    .fill(isActive ? Color.rule : Color.clear)
                    .frame(height: 2)
            }
        }
        .buttonStyle(.plain)
        .accessibilityAddTraits(isActive ? [.isButton, .isSelected] : .isButton)
        .accessibilityLabel(tab.displayName)
    }

    /// Keeps all tab views alive in the hierarchy so scroll state (and other
    /// view state) is preserved across tab switches. Only the active tab is
    /// visible; inactive tabs are hidden via opacity + hit-testing.
    ///
    /// Bug #17: switching tabs with a plain `switch` destroyed and recreated
    /// `TranscriptColumn`, resetting its `ScrollView` scroll position.
    private var tabContent: some View {
        ZStack {
            NotesColumn()
                .opacity(appState.selectedTab == .notes ? 1 : 0)
                .allowsHitTesting(appState.selectedTab == .notes)
                .accessibilityHidden(appState.selectedTab != .notes)

            TranscriptColumn()
                .opacity(appState.selectedTab == .transcript ? 1 : 0)
                .allowsHitTesting(appState.selectedTab == .transcript)
                .accessibilityHidden(appState.selectedTab != .transcript)

            BroadsheetSummaryView()
                .opacity(appState.selectedTab == .summary ? 1 : 0)
                .allowsHitTesting(appState.selectedTab == .summary)
                .accessibilityHidden(appState.selectedTab != .summary)

            suggestionsContent
                .opacity(appState.selectedTab == .suggestions ? 1 : 0)
                .allowsHitTesting(appState.selectedTab == .suggestions)
                .accessibilityHidden(appState.selectedTab != .suggestions)

            Text("Actions").font(Typography.body).foregroundStyle(Color.ink3)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .opacity(appState.selectedTab == .actions ? 1 : 0)
                .allowsHitTesting(appState.selectedTab == .actions)
                .accessibilityHidden(appState.selectedTab != .actions)

            BroadsheetBusinessPlanView()
                .opacity(appState.selectedTab == .templates ? 1 : 0)
                .allowsHitTesting(appState.selectedTab == .templates)
                .accessibilityHidden(appState.selectedTab != .templates)
        }
    }

    @ViewBuilder
    private var suggestionsContent: some View {
        if let vm = appState.contextSuggestionsVM {
            ContextSuggestionsPanelView(viewModel: vm)
        } else {
            Text("No signals yet.")
                .foregroundStyle(Color.ink3)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
    }
}

import Business
import Domain
import Foundation
import Logging
import Observation

@Observable
@MainActor
public final class MeetingDetailViewModel {
    public var selectedMeeting: RecordingMetadata?

    /// The audio file URL for the currently selected meeting.
    /// Used by ``TranscriptTabView`` to load audio into ``AudioPlayerViewModel``.
    public var audioURL: URL? { selectedMeeting?.audioURL }

    public var transcript: String?
    public var segments: [DiarizedSegment] = []

    // #174: summary uses didSet to rebuild summaryMarkdownText once on change,
    // so SummaryTabView reads a pre-built String rather than calling .map/.joined
    // on every body evaluation.
    public var summary: MeetingSummary? {
        didSet { summaryMarkdownText = Self.buildSummaryMarkdown(summary) }
    }

    /// Pre-built markdown string for SummaryTabView. Updated whenever `summary`
    /// changes via `didSet` — never recomputed during SwiftUI body evaluation.
    public private(set) var summaryMarkdownText = ""

    public var notes = ""
    public private(set) var notesError: (any Error)?
    public private(set) var saveError: (any Error)?

    // #302: Business Plan Pro action.
    public private(set) var businessPlanMarkdown: String?
    public private(set) var businessPlanError: (any Error)?
    public private(set) var isGeneratingBusinessPlan = false
    public var canGenerateBusinessPlan: Bool { generateBusinessPlanUseCase != nil }

    private let reader: any MeetingDetailReadRepository
    private let writer: any MeetingDetailWriteRepository
    private let repairUseCase: RepairTranscriptUseCase?
    private let generateBusinessPlanUseCase: GenerateBusinessPlanUseCase?
    private let logger = AppLogger.for(category: "MeetingDetail")
    private var loadTask: Task<Void, any Error>?
    private var saveDebounceTask: Task<Void, Never>?

    public init(
        reader: any MeetingDetailReadRepository,
        writer: any MeetingDetailWriteRepository,
        repairUseCase: RepairTranscriptUseCase? = nil,
        generateBusinessPlanUseCase: GenerateBusinessPlanUseCase? = nil
    ) {
        self.reader = reader
        self.writer = writer
        self.repairUseCase = repairUseCase
        self.generateBusinessPlanUseCase = generateBusinessPlanUseCase
    }

    // MARK: - Summary Markdown (#174)

    /// Builds the markdown representation of a `MeetingSummary` without accessing
    /// any @Observable stored properties — safe to call from `didSet`.
    static func buildSummaryMarkdown(_ summary: MeetingSummary?) -> String {
        guard let s = summary else { return "" }
        var md = s.summary
        if !s.topics.isEmpty {
            md += "\n\n## Topics\n" + s.topics.map { "- \($0)" }.joined(separator: "\n")
        }
        if !s.decisions.isEmpty {
            md += "\n\n## Decisions\n" + s.decisions.map { "- \($0)" }.joined(separator: "\n")
        }
        if !s.actionItems.isEmpty {
            md += "\n\n## Action Items\n" + s.actionItems.map { item in
                var line = "- \(item.description)"
                if let who = item.assignee { line += " (\(who))" }
                if let due = item.dueDate {
                    line += " — due \(due.formatted(date: .abbreviated, time: .omitted))"
                }
                return line
            }.joined(separator: "\n")
        }
        if !s.openQuestions.isEmpty {
            md += "\n\n## Open Questions\n" + s.openQuestions.map { "- \($0)" }.joined(separator: "\n")
        }
        return md
    }

    // MARK: - Detail Loading

    public func loadDetail(for meeting: RecordingMetadata) async throws {
        saveDebounceTask?.cancel()
        saveDebounceTask = nil
        loadTask?.cancel()
        selectedMeeting = meeting
        // Don't nil out summary/transcript immediately — keep the previous meeting's
        // content visible until the new one loads to avoid a blank flash.
        let requestedId = meeting.id

        let task = Task { [weak self] in
            guard let self else { return }
            let stored = try await self.reader.getRecording(id: meeting.id)
            try Task.checkCancellation()
            guard self.selectedMeeting?.id == requestedId else { return }
            self.transcript = stored.transcript?.fullText

            let loadedSummary = try await self.reader.getSummary(for: meeting.id)
            try Task.checkCancellation()
            guard self.selectedMeeting?.id == requestedId else { return }
            self.summary = loadedSummary

            let loadedSegments = try await self.reader.getSegments(id: meeting.id)
            try Task.checkCancellation()
            guard self.selectedMeeting?.id == requestedId else { return }
            self.segments = loadedSegments

            do {
                let loadedNotes = try await self.reader.getNotes(meetingId: requestedId)
                try Task.checkCancellation()
                guard self.selectedMeeting?.id == requestedId else { return }
                self.notes = loadedNotes
            } catch {
                self.logger
                    .error(
                        // swiftlint:disable:next line_length
                        "getNotes failed for \(requestedId, privacy: .public): \(String(describing: error), privacy: .private)"
                    )
                self.notesError = error
            }
        }
        loadTask = task
        try await task.value
    }

    public func saveNotes(_ text: String) async {
        guard let id = selectedMeeting?.id else { return }
        await saveNotes(text, forMeetingId: id)
    }

    /// Saves notes for an explicit meeting ID. Used by the debounce path to avoid
    /// resolving `selectedMeeting` at execution time (which may have changed).
    public func saveNotes(_ text: String, forMeetingId meetingId: RecordingID) async {
        saveError = nil
        do {
            try await writer.saveNotes(meetingId: meetingId, text: text)
        } catch {
            logger
                .error(
                    // swiftlint:disable:next line_length
                    "saveNotes failed for \(meetingId, privacy: .public): \(String(describing: error), privacy: .private)"
                )
            saveError = error
        }
    }

    /// Loads the diarized segments for the currently selected meeting.
    public func loadSegmentsForCurrentMeeting() async throws -> [DiarizedSegment] {
        guard let id = selectedMeeting?.id else { return [] }
        return try await reader.getSegments(id: id)
    }

    /// Persists a summary for the currently selected meeting and updates the local state.
    public func applySummary(_ summary: MeetingSummary) async throws {
        guard let id = selectedMeeting?.id else { return }
        try await writer.saveSummary(for: id, summary: summary)
        self.summary = summary
    }

    /// Debounced entry point for keystroke-driven saves. Cancels any pending save
    /// and schedules a new one after 500 ms so rapid edits coalesce into one write.
    /// The meeting ID is captured at schedule time — not at execution time — to
    /// prevent cross-meeting note corruption when the user switches meetings within
    /// the debounce window.
    public func debouncedSaveNotes(_ text: String) {
        let meetingId = selectedMeeting?.id // capture NOW, before any await
        saveDebounceTask?.cancel()
        saveDebounceTask = Task { [weak self] in
            do { try await Task.sleep(for: .milliseconds(500)) } catch { return }
            guard !Task.isCancelled, let self, let meetingId else { return }
            await self.saveNotes(text, forMeetingId: meetingId)
        }
    }

    public func recordingIDsWithSummaries() async throws -> Set<RecordingID> {
        try await reader.recordingIDsWithSummaries()
    }

    /// Generates a business plan from the currently loaded transcript (#302).
    public func generateBusinessPlan() async {
        guard let generateBusinessPlanUseCase, let transcript else { return }
        isGeneratingBusinessPlan = true
        businessPlanError = nil
        do {
            businessPlanMarkdown = try await generateBusinessPlanUseCase.execute(transcript: transcript)
        } catch {
            businessPlanError = error
        }
        isGeneratingBusinessPlan = false
    }
}
